import{n as s}from"./shared-CAKwAg2C.js";const r={"LEARN HOW THE INTERNET WORKS":"SCOPRI COME FUNZIONA INTERNET","NOW LEARNING":"STAI IMPARANDO","OSI LAYER":"LIVELLO OSI","LEARNING PROGRESS":"I TUOI PROGRESSI",COMPLETE:"COMPLETATI","IN PROGRESS":"IN CORSO","{pct}% complete":"{pct}% completato","DESIGNED BY":"DESIGN DI","Dilum Sanjaya on X":"Dilum Sanjaya su X","Layer {n}: {name}":"Livello {n}: {name}",Physical:"Fisico","Data Link":"Collegamento dati",Network:"Rete",Transport:"Trasporto",Session:"Sessione",Presentation:"Presentazione",Application:"Applicazione","OVERVIEW · {n} STEPS":"PANORAMICA · {n} PASSAGGI","STEP {n}/{total} · {title}":"PASSAGGIO {n}/{total} · {title}","LESSON COMPLETE":"LEZIONE COMPLETATA",PROTOCOLS:"PROTOCOLLI",Protocols:"Protocolli",Language:"Lingua",Theme:"Tema","Light mode":"Tema chiaro","Dark mode":"Tema scuro","INTERNET PROTOCOLS":"PROTOCOLLI INTERNET","Close the protocol list":"Chiudi l’elenco dei protocolli","Close (Esc)":"Chiudi (Esc)",ALL:"TUTTI",CORE:"BASE",APPLICATION:"APPLICAZIONI",SECURITY:"SICUREZZA",NETWORK:"RETE",SEQUENCE:"SEQUENZA",View:"Vista","Switch view (V)":"Cambia vista (V)","Network diagram":"Diagramma di rete","Sequence diagram":"Diagramma di sequenza","STEP {n}":"PASSAGGIO {n}","PROTOCOL OVERVIEW":"PANORAMICA","STEP DETAILS":"DETTAGLI","LESSON SUMMARY":"RIEPILOGO DELLA LEZIONE",OVERVIEW:"PANORAMICA",ACTIVE:"ATTIVO","STEP {n} OF {total}":"PASSAGGIO {n} DI {total}","PACKET {n} OF {total}":"PACCHETTO {n} DI {total}","PACKETS {from}–{to} OF {total}":"PACCHETTI {from}–{to} DI {total}","{n} LOST":"{n} PERSI","1 LOST":"1 PERSO",ENCRYPTED:"CIFRATO","LOST ON THE WAY":"PERSO PER STRADA","PACKET FLOW":"FLUSSO DEI PACCHETTI","Colour key":"Legenda dei colori","Playback speed":"Velocità di riproduzione","Previous step (←)":"Passaggio precedente (←)","Previous step":"Passaggio precedente","Play / pause (Space)":"Riproduci / pausa (Spazio)",PLAY:"AVVIA",PAUSE:"PAUSA",REPLAY:"RIVEDI",STEP:"PASSO","One packet at a time":"Un pacchetto alla volta",RESET:"AZZERA",Reset:"Azzera","Back to the overview (Esc)":"Torna alla panoramica (Esc)","NO.":"N.",TIME:"TEMPO",SOURCE:"ORIGINE",DESTINATION:"DESTINAZIONE",PROTOCOL:"PROTOCOLLO",INFO:"INFO",SIZE:"BYTE","No packets on the wire yet.":"Ancora nessun pacchetto in transito.",LOST:"PERSO","Packet inspector":"Ispettore dei pacchetti","Previous packet":"Pacchetto precedente","Previous packet (←)":"Pacchetto precedente (←)","Next packet":"Pacchetto successivo","Next packet (→)":"Pacchetto successivo (→)",Close:"Chiudi","E.G.":"ES.","an example value: it differs in every real capture":"un valore d’esempio: è diverso in ogni cattura reale","bytes the lesson can’t show: encrypted, random, or a file’s contents":"byte che la lezione non può mostrare: cifrati, casuali o il contenuto di un file",BYTES:"BYTE","{n} in this frame":"{n} in questo frame","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Questa riga rappresenta {n} segmenti TCP che portano un messaggio di {size} byte; è mostrato il primo segmento","This packet was lost on the way":"Questo pacchetto è andato perso per strada",Padding:"Riempimento","One packet at a time (S)":"Un pacchetto alla volta (S)","KEYBOARD SHORTCUTS":"SCORCIATOIE DA TASTIERA","Press {key} any time to see these again.":"Premi {key} in qualsiasi momento per rivederle.","Search protocols":"Cerca protocolli","Search protocols and steps":"Cerca protocolli e passaggi","Nothing matches.":"Nessun risultato.","to move":"per spostarti","to open":"per aprire","Protocol list":"Elenco dei protocolli","Diagram only":"Solo il diagramma",Fullscreen:"Schermo intero","Keyboard shortcuts":"Scorciatoie da tastiera",Playback:"Riproduzione","Hide the protocol list (L)":"Nascondi l’elenco dei protocolli (L)","Diagram only (D)":"Solo il diagramma (D)","Fullscreen (F)":"Schermo intero (F)","Keyboard shortcuts (?)":"Scorciatoie da tastiera (?)","Show the protocol list (L)":"Mostra l’elenco dei protocolli (L)","Show all panels (D)":"Mostra tutti i pannelli (D)","Exit fullscreen (F)":"Esci da schermo intero (F)","Play or pause":"Riproduci o metti in pausa","Next step":"Passaggio successivo","Go to step 1 to 9":"Vai ai passaggi da 1 a 9","Slower, faster":"Più lento, più veloce","Back to the overview":"Torna alla panoramica","Network or sequence view":"Vista di rete o di sequenza","Show or hide the protocol list":"Mostra o nascondi l’elenco dei protocolli","Light or dark theme":"Tema chiaro o scuro",Find:"Trova","Next or previous protocol":"Protocollo successivo o precedente","These shortcuts":"Queste scorciatoie","Previous or next packet":"Pacchetto precedente o successivo","Close it":"Chiuderlo"},n={"Hypertext Transfer Protocol":"Hypertext Transfer Protocol","HTTP Secure":"HTTP sicuro","Transmission Control Protocol":"Transmission Control Protocol","User Datagram Protocol":"User Datagram Protocol","Internet Protocol":"Internet Protocol","Domain Name System":"Domain Name System","Dynamic Host Configuration":"Configurazione dinamica degli host","Internet Control Message":"Messaggi di controllo di Internet","Simple Mail Transfer Protocol":"Simple Mail Transfer Protocol","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Accesso ai messaggi Internet","File Transfer Protocol":"File Transfer Protocol","Secure Shell":"Secure Shell","Transport Layer Security":"Transport Layer Security",Internet:"Internet",Client:"Client",Router:"Router","DNS Resolver":"Resolver DNS","Web Server":"Server web","Root Server":"Server radice",".com TLD Server":"Server TLD .com","Authoritative Server":"Server autorevole","Mail Server":"Server di posta",".com Server":"Server .com",Authoritative:"Autorevole",Server:"Server","Web Communication":"Comunicazione web",Request:"Richiesta",Response:"Risposta","Data ACKs not shown":"ACK dei dati non mostrati","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP è il protocollo del web: un client chiede una risorsa, per esempio una pagina HTML, e il server risponde con un codice di stato, delle intestazioni e di solito un corpo. Ogni scambio è una richiesta e una risposta, scritte come testo leggibile in HTTP/1.1.",Layer:"Livello","Application (Layer 7)":"Applicazione (livello 7)","Default Port":"Porta predefinita","Data Format":"Formato dei dati","Text (headers + optional body)":"Testo (intestazioni + corpo facoltativo)","Common Methods":"Metodi comuni","Defined In":"Definito in","Page delivered":"Pagina consegnata","One request, one response":"Una richiesta, una risposta","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"In meno di un decimo di secondo il portatile ha cercato un indirizzo, ha aperto una connessione TCP e ha scambiato una richiesta e una risposta HTTP, tutte leggibili da chiunque lungo il percorso. Premi RIVEDI per guardarlo di nuovo.","Round trips":"Andate e ritorni","Total time":"Tempo totale","Page size":"Dimensione della pagina","Sent as 9 TCP segments":"Inviata in 9 segmenti TCP","Client Request":"Richiesta del client","Browser prepares the request":"Il browser prepara la richiesta","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Apri http://www.example.com. Il browser invierà una richiesta GET, ma i pacchetti viaggiano verso indirizzi IP, non verso nomi, quindi prima gli serve l’indirizzo del server. (Oggi i browser provano prima https://; questa è la versione in chiaro.)",Method:"Metodo","Next hop":"Prossimo salto","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"Risoluzione DNS","Finds the server’s IP address":"Trova l’indirizzo IP del server","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Il portatile chiede al server DNS che ha ricevuto dal DHCP, 8.8.8.8, l’indirizzo di www.example.com. La domanda viaggia su UDP porta 53 e la risposta è un record A con l’indirizzo IPv4. (Su una rete con IPv6 chiederebbe anche un record AAAA.)",Resolver:"Resolver","8.8.8.8 (had it cached)":"8.8.8.8 (ce l’aveva in cache)","UDP, port 53":"UDP, porta 53",Answer:"Risposta","DNS QUERY":"QUERY DNS","DNS REPLY":"RISPOSTA DNS","TCP Connection":"Connessione TCP","Establishes a reliable link":"Stabilisce un collegamento affidabile","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP funziona sopra TCP. Prima che si muova qualsiasi dato della pagina, il portatile e il server aprono una connessione verso la porta 80 con un handshake a tre vie: SYN, SYN-ACK, ACK.","Server port":"Porta del server","Client port":"Porta del client",Handshake:"Handshake","HTTP Exchange":"Scambio HTTP","Request and response messages":"Messaggi di richiesta e risposta","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Il browser invia una richiesta GET con un’intestazione Host. Il server risponde 200 OK con l’HTML nel corpo: 12.2 KB, troppo per un solo pacchetto, quindi TCP lo divide in 9 segmenti fino a 1460 byte (qui disegnati come uno solo).",Status:"Stato",Body:"Corpo","text/html, 12.2 KB":"text/html, 12.2 KB","Sent as":"Inviato come","12.2 KB in 9 segments":"12.2 KB in 9 segmenti","Page Rendering":"Rendering della pagina","Browser displays the content":"Il browser mostra il contenuto","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Il browser analizza l’HTML e disegna la pagina. CSS, immagini e script collegati farebbero partire ognuno altre richieste come questa, riusando la connessione aperta quando possono.",Document:"Documento",Connection:"Connessione","Kept open for reuse":"Tenuta aperta per riusarla","Seen on the laptop’s home network":"Visto sulla rete di casa del portatile",Destination:"Destinazione","The router: anything beyond the home network goes to it first.":"Il router: tutto ciò che va oltre la rete di casa passa prima da lui.",Source:"Origine","The laptop’s network card.":"La scheda di rete del portatile.",Type:"Tipo","What the frame carries.":"Cosa trasporta il frame.","Version, header length":"Versione, lunghezza dell’intestazione","4, 20 bytes":"4, 20 byte","IPv4, with no options.":"IPv4, senza opzioni.","Priority and congestion marks; 0 means ordinary traffic.":"Priorità e segnali di congestione; 0 significa traffico normale.","Total length":"Lunghezza totale","This header and everything inside it.":"Questa intestazione e tutto ciò che contiene.",Identification:"Identificazione","Lets the receiver reassemble the pieces if the packet gets split.":"Permette al destinatario di ricomporre i pezzi se il pacchetto viene diviso.",Flags:"Flag",none:"nessuno","Routers may split it if a link is too small.":"I router possono dividerlo se un collegamento è troppo piccolo.","Time to live":"Tempo di vita","Windows starts at 128.":"Windows parte da 128.",Protocol:"Protocollo","Header checksum":"Checksum dell’intestazione","Covers this header only; every router recomputes it after lowering the TTL.":"Copre solo questa intestazione; ogni router la ricalcola dopo aver abbassato il TTL.","Source port":"Porta di origine","Destination port":"Porta di destinazione",Length:"Lunghezza","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Intestazione UDP e dati. Questo è tutto UDP: niente numerazione, niente conferme.",Checksum:"Checksum","Covers the header, the data and the IP addresses.":"Copre l’intestazione, i dati e gli indirizzi IP.","Transaction ID":"ID transazione","Picked at random; the answer must carry the same one.":"Scelto a caso; la risposta deve riportare lo stesso.","0x0100: query, RD (recursion desired)":"0x0100: query, RD (ricorsione richiesta)",Questions:"Domande",Answers:"Risposte","Authority records":"Record di autorità","Additional records":"Record aggiuntivi",Question:"Domanda","www.example.com, type A, class IN":"www.example.com, tipo A, classe IN","The laptop.":"Il portatile.","The router’s side facing the home network.":"Il lato del router verso la rete di casa.","Started at 128; 10 routers on the way each took 1.":"Partito da 128; 10 router lungo il percorso hanno tolto 1 ciascuno.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: risposta, RD (ricorsione richiesta), RA (ricorsione disponibile)","DF (don’t fragment)":"DF (non frammentare)","Routers must not split it; if it’s too big they report back instead.":"I router non devono dividerlo; se è troppo grande lo segnalano indietro.","Picked by the laptop’s system for this connection.":"Scelta dal sistema del portatile per questa connessione.","Sequence number":"Numero di sequenza","This side’s starting number. Shown as 0; the real one is random.":"Il numero di partenza di questo lato. Mostrato come 0; quello vero è casuale.","Real sequence number":"Numero di sequenza reale",Acknowledgment:"Conferma","0 (not used yet)":"0 (non ancora usato)","A first SYN has nothing to acknowledge.":"Un primo SYN non ha nulla da confermare.","Header length":"Lunghezza dell’intestazione","20 bytes, plus 12 of options.":"20 byte, più 12 di opzioni.",Window:"Finestra","How much more data this side can take right now.":"Quanti altri dati questo lato può accettare in questo momento.","Covers the header, the data and the IP addresses, so damage is caught.":"Copre l’intestazione, i dati e gli indirizzi IP, così i danni vengono scoperti.","Urgent pointer":"Puntatore urgente",Options:"Opzioni","Maximum segment size":"Dimensione massima del segmento","The most data this side wants in one segment.":"Il massimo di dati che questo lato vuole in un segmento.","Spacing, so the next option lines up.":"Riempimento, così l’opzione successiva risulta allineata.","Window scale":"Scala della finestra","Window values are multiplied by this, so windows can be larger than 64 KB.":"I valori della finestra vengono moltiplicati per questo, così le finestre possono superare i 64 KB.","SACK permitted":"SACK consentito",yes:"sì","This side understands selective acknowledgements.":"Questo lato capisce le conferme selettive.","Started at 64; 12 routers on the way each took 1.":"Partito da 64; 12 router lungo il percorso hanno tolto 1 ciascuno.","The next byte this side expects: everything before it has arrived.":"Il prossimo byte che questo lato si aspetta: tutto ciò che viene prima è arrivato.","Position of this segment’s first byte, counted from this side’s SYN.":"Posizione del primo byte di questo segmento, contata dal SYN di questo lato.","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 byte)","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"I frame Ethernet sono di almeno 60 byte (64 con il checksum aggiunto dalla scheda), quindi quelli corti vengono riempiti.",Text:"Testo","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 byte)","covers bytes not shown here":"copre byte non mostrati qui","12,500 bytes: the HTML page":"12,500 byte: la pagina HTML","The page itself; its contents are not part of the lesson.":"La pagina stessa; il suo contenuto non fa parte della lezione.","Secure Web":"Web sicuro","TLS handshake":"Handshake TLS","HTTP request":"Richiesta HTTP","HTTP response":"Risposta HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS è HTTP inviato dentro una connessione TLS cifrata. TLS dimostra con un certificato che il server è chi dice di essere, concorda nuove chiavi di cifratura e poi protegge ogni richiesta e risposta dall’essere letta o modificata lungo la strada.","Application (HTTP over TLS)":"Applicazione (HTTP su TLS)",Security:"Sicurezza","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 ancora diffuso)",Proves:"Dimostra","Server identity (certificate)":"Identità del server (certificato)","Secure page delivered":"Pagina sicura consegnata","Encrypted, except the lookup":"Cifrato, tranne la ricerca","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Il browser ha cercato l’indirizzo con il DNS in chiaro, ha aperto una connessione TCP, ha verificato il certificato del server e ha concordato le chiavi in un solo viaggio di andata e ritorno. Ogni byte HTTP dopo di allora ha viaggiato cifrato. Premi RIVEDI per guardarlo di nuovo.",Cipher:"Cifrario","Still visible":"Ancora visibili","IPs, server name, sizes":"IP, nome del server, dimensioni","Secure Request":"Richiesta sicura","Browser asks for https://":"Il browser chiede https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Scrivi https://www.example.com. La «s» dice al browser di proteggere la connessione con TLS, di norma sulla porta 443. Prima di potersi collegare deve comunque trovare l’indirizzo IP del server.",Port:"Porta","DNS Lookup":"Ricerca DNS","Same lookup as HTTP, not encrypted":"La stessa ricerca di HTTP, non cifrata","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"La ricerca è esattamente la stessa dell’HTTP in chiaro: una query a 8.8.8.8 su UDP porta 53. Non è cifrata, quindi chiunque lungo il percorso può vedere quale nome hai chiesto, a meno che il browser non usi DNS over HTTPS.",Encrypted:"Cifrato","No (plain DNS)":"No (DNS in chiaro)","TCP Handshake":"Handshake TCP","Opens a connection to port 443":"Apre una connessione verso la porta 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS viaggia sopra TCP, quindi prima arriva lo stesso handshake a tre vie, questa volta verso la porta 443. Niente è ancora cifrato.","TLS Handshake":"Handshake TLS","Agrees on keys, checks the certificate":"Concorda le chiavi, verifica il certificato","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Il browser offre cifrari e condivisioni di chiave, tra cui un ibrido post-quantistico. Il server lo sceglie e manda la propria parte, poi il suo certificato, già cifrato. Il browser lo verifica rispetto alle autorità di cui si fida.",Version:"Versione","Key exchange":"Scambio di chiavi","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (ibrido)","Server name":"Nome del server","Sent in clear (SNI)":"Inviato in chiaro (SNI)","key shares: hybrid + x25519":"key share: ibrido + x25519","cipher: AES_128_GCM_SHA256":"cifrario: AES_128_GCM_SHA256","then encrypted: cert, Finished":"poi cifrati: cert, Finished","CERTIFICATE VALID":"CERTIFICATO VALIDO","handshake complete (encrypted)":"handshake completato (cifrato)","Encrypted Exchange":"Scambio cifrato","HTTP inside TLS records":"HTTP dentro i record TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"Il GET e il 200 OK sono gli stessi messaggi HTTP di prima, chiusi in record TLS che sulla linea sembrano «dati applicativi» casuali. Il server consegna anche due ticket di sessione, così una visita successiva può saltare parte dell’handshake.",Inside:"Dentro","GET / and 200 OK":"GET / e 200 OK",Tickets:"Ticket","2, for faster reconnects":"2, per riconnessioni più rapide","APP DATA":"DATI APP","inside: GET / HTTP/1.1":"dentro: GET / HTTP/1.1","outside: encrypted bytes":"fuori: byte cifrati","inside: HTTP/1.1 200 OK":"dentro: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"fuori: 12.9 KB, 9 segmenti","Browser shows the padlock":"Il browser mostra il lucchetto","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Il browser decifra la risposta, disegna la pagina e mostra un lucchetto: la connessione è privata e il server ha dimostrato la sua identità. L’intestazione Strict-Transport-Security gli dice di usare HTTPS per questo sito d’ora in poi.",Remembers:"Ricorda","HTTPS only (HSTS), 1 year":"Solo HTTPS (HSTS), 1 anno","Server Hello + encrypted handshake, 3 segments":"Server Hello + handshake cifrato, 3 segmenti","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (cifrato)","Application Data (HTTP request)":"Application Data (richiesta HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (cifrati)","Application Data (HTTP response), 9 segments":"Application Data (risposta HTTP), 9 segmenti",Record:"Record","Content type":"Tipo di contenuto","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Il record di un Client Hello dice TLS 1.0 così i vecchi apparati intermedi lo lasciano passare; le versioni vere sono offerte all’interno.","Handshake type":"Tipo di handshake",Contents:"Contenuto","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Tutto ciò che il browser supporta. I browser cambiano qualche dettaglio da una connessione all’altra.","Server name (SNI)":"Nome del server (SNI)","Versions offered":"Versioni offerte","Key shares":"Condivisioni di chiave","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 byte), X25519","App protocols (ALPN)":"Protocolli app (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"I record TLS 1.3 dicono 1.2 all’esterno, per compatibilità.","The server’s choices and its half of the hybrid key exchange.":"Le scelte del server e la sua metà dello scambio di chiavi ibrido.","Cipher suite":"Suite di cifratura","Key share":"Condivisione di chiave","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 byte)","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Non ha alcun compito in TLS 1.3; viene inviato perché gli apparati intermedi vedano un handshake familiare.","Every encrypted record says Application Data on the outside; the real type is inside.":"Ogni record cifrato dice Application Data all’esterno; il tipo vero è all’interno.","Encrypted data":"Dati cifrati","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Testo cifrato, che termina con un tag di 16 byte che rivela qualsiasi modifica. Solo i due estremi possono leggerlo.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (la catena), Certificate Verify (la firma), Finished","Finished: a check value over the whole handshake":"Finished: un valore di controllo su tutto l’handshake","The HTTP request":"La richiesta HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: permette a una visita successiva di riprendere","The HTTP response, then the 12,500-byte page":"La risposta HTTP, poi la pagina di 12,500 byte","Reliable Delivery":"Consegna affidabile","Handshake and ACKs":"Handshake e ACK","Data from laptop":"Dati dal portatile","Data from server":"Dati dal server","Closing (FIN)":"Chiusura (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP trasforma la consegna dei pacchetti di Internet, fatta «al meglio», in un flusso di byte affidabile e ordinato. Numera ogni byte, conferma ciò che arriva, rinvia ciò che si perde e regola il ritmo del mittente perché né l’altro lato né la rete vengano sommersi.","Transport (Layer 4)":"Trasporto (livello 4)","Three-way handshake":"Handshake a tre vie",Reliability:"Affidabilità","Sequence numbers + ACKs":"Numeri di sequenza + ACK",Recovery:"Recupero",Retransmission:"Ritrasmissione",Header:"Intestazione","20–60 bytes":"20–60 byte","Connection closed":"Connessione chiusa","Every byte accounted for":"Ogni byte al suo posto","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP ha aperto una connessione, ha numerato e confermato ogni byte, ha notato un buco e ha rinviato solo il segmento mancante, poi ha chiuso entrambe le direzioni in modo pulito. curl ha ricevuto ogni byte in ordine e non si è mai accorto della perdita. Premi RIVEDI per guardarlo di nuovo.",Segments:"Segmenti","14 (1 lost, 1 resent)":"14 (1 perso, 1 rinviato)","Bytes delivered":"Byte consegnati","78 up, 2,920 down":"78 in su, 2,920 in giù","Loss found by":"Perdita scoperta con","Duplicate ACK + SACK":"ACK duplicato + SACK","Open Connection":"Apertura della connessione","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl conosce già l’indirizzo del server. Prima che si muova qualsiasi dato, entrambi i lati scelgono un numero di sequenza iniziale e lo confermano: SYN, SYN-ACK, ACK. Qui i numeri sono relativi; quelli veri partono da un valore casuale.","203.0.113.10, port 80":"203.0.113.10, porta 80","Send Data":"Invio dei dati","Every byte is numbered":"Ogni byte è numerato","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl invia la sua richiesta HTTP di 78 byte: i byte da 1 a 78. Il numero di ACK del server, 79, è il prossimo byte che si aspetta, cioè tutto ciò che viene prima è arrivato.",Sent:"Inviati","78 bytes (seq 1–78)":"78 byte (seq 1–78)","79 = next byte expected":"79 = prossimo byte atteso","Two Segments Back":"Due segmenti di ritorno","One of them is lost":"Uno dei due va perso","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Il server risponde con 2,920 byte: due segmenti pieni da 1,460 byte, il massimo che qui sta in un pacchetto, inviati uno dopo l’altro. Il primo viene scartato da qualche parte su Internet; il secondo passa.","Segment 1":"Segmento 1","bytes 1–1460 (lost)":"byte 1–1460 (perso)","Segment 2":"Segmento 2","bytes 1461–2920":"byte 1461–2920","Segment size":"Dimensione del segmento","1,460 bytes (MSS)":"1,460 byte (MSS)","2 SEGMENTS":"2 SEGMENTI","seq=1 and seq=1461":"seq=1 e seq=1461","the first is lost":"il primo va perso","SEGMENT 1 LOST":"SEGMENTO 1 PERSO","A Gap Is Noticed":"Ci si accorge di un buco","Duplicate ACK with SACK":"ACK duplicato con SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Arrivano i byte 1461–2920, ma 1–1460 non sono mai arrivati. Un ACK può contare solo i byte ricevuti in ordine, quindi il portatile ripete subito ACK 1 e aggiunge un blocco SACK che dice che ha già 1461–2920.","1 (still waiting for byte 1)":"1 (aspetta ancora il byte 1)","holds bytes 1461–2920":"ha i byte 1461–2920","At once, not delayed":"Subito, senza ritardo","DUP ACK":"ACK DUPLICATO","sack: has 1461–2920":"sack: ha 1461–2920","Resend the Gap":"Rinvio del buco","Only the missing bytes":"Solo i byte mancanti","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"Il SACK dice al server esattamente cosa manca, quindi rinvia solo il segmento 1 e il portatile conferma tutto. Se non fosse tornato nessun ACK, sarebbero intervenuti i timer: una sonda dopo circa due viaggi di andata e ritorno, poi un timeout di ritrasmissione (almeno 200 ms su Linux).",Resent:"Rinviati","bytes 1–1460 only":"solo i byte 1–1460","Next ACK":"ACK successivo","2921 (everything)":"2921 (tutto)","curl saw":"curl ha visto","Every byte, in order":"Ogni byte, in ordine",RESEND:"RINVIO","just the missing segment":"solo il segmento mancante","Close Connection":"Chiusura della connessione","Each side says goodbye":"Ogni lato saluta","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl ha finito, quindi chiude. Ogni direzione si chiude per conto suo: il portatile invia FIN e il server lo conferma, poi il server invia il suo FIN e il portatile lo conferma. Il portatile conserva i dati della connessione per un po’ (TIME-WAIT).","Closed by":"Chiusa da","A FIN from each side":"Un FIN da ogni lato",Order:"Ordine",Then:"Poi","Laptop waits (TIME-WAIT)":"Il portatile attende (TIME-WAIT)",Data:"Dati","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 byte: la risposta HTTP, byte 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 byte: la risposta HTTP, byte 1461–2920","has 1461–2920":"ha 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Byte arrivati dopo il buco, quindi va rinviato solo il buco.","Fast Datagrams":"Datagrammi veloci","Your voice":"La tua voce","Their voice":"La sua voce","Media Server":"Server multimediale","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP invia i dati in pacchetti indipendenti chiamati datagrammi, senza connessione, senza conferme e senza rinvii. Così resta veloce e leggero: adatto a voce, video, giochi e DNS, dove una risposta in ritardo è peggio di una mancante.",None:"Nessuna","None (no ACKs, no resends)":"Nessuna (niente ACK, niente rinvii)",Ordering:"Ordine","Not guaranteed":"Non garantito","Call keeps flowing":"La chiamata continua","Fast, simple, no guarantees":"Veloce, semplice, senza garanzie","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"L’audio è partito con il primissimo pacchetto, ogni datagramma ha viaggiato per conto suo e quello perso è semplicemente sparito: UDP non se n’è mai accorto. L’app ha coperto il buco e la chiamata è andata avanti. Premi RIVEDI per guardarlo di nuovo.",Datagrams:"Datagrammi","11 (1 lost, never resent)":"11 (1 perso, mai rinviato)","Setup time":"Tempo di avvio","0 ms (no handshake)":"0 ms (nessun handshake)","8 bytes (TCP: 20+)":"8 byte (TCP: 20+)",Shown:"Mostrati","The first 0.2 s of a call":"I primi 0.2 s di una chiamata","Send Right Away":"Invio immediato","No handshake, data goes first":"Niente handshake, partono subito i dati","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Un’app di chiamate conosce già indirizzo e porta del server multimediale dall’accesso. Non apre una connessione: il primissimo datagramma porta già 20 ms della tua voce, dietro un’intestazione UDP di 8 byte.",Setup:"Avvio",Ports:"Porte","VOICE 1":"VOCE 1","92 B of audio, no setup":"92 B di audio, nessun avvio","A Stream of Datagrams":"Un flusso di datagrammi","One every 20 ms, each on its own":"Uno ogni 20 ms, ciascuno per conto suo","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"L’app continua a inviare un datagramma ogni 20 ms. Ognuno è a sé, con la propria intestazione e nessun legame con gli altri. UDP non li numera e nulla torna indietro a confermare che sono arrivati.",Rate:"Frequenza","1 datagram / 20 ms":"1 datagramma / 20 ms",Numbering:"Numerazione","None in UDP itself":"Nessuna nello stesso UDP",Confirmation:"Conferma","None (no ACKs)":"Nessuna (niente ACK)","4 DATAGRAMS":"4 DATAGRAMMI","voice frames 2–5":"frame vocali 2–5","each with its own 8-byte header":"ognuno con la sua intestazione di 8 byte","Lost on the Way":"Perso per strada","Nobody resends it":"Nessuno lo rinvia","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Il frame 7 viene scartato da qualche parte su Internet. Il server multimediale non lo chiede mai e UDP non lo dice mai al portatile: non ci sono conferme da perdere. I datagrammi successivi arrivano normalmente.",Lost:"Perso","Voice frame 7":"Frame vocale 7","Never (no ACKs)":"Mai (niente ACK)",Missing:"Mancano","20 ms of audio":"20 ms di audio","3 DATAGRAMS":"3 DATAGRAMMI","voice frames 6–8":"frame vocali 6–8","frame 7 is lost":"il frame 7 va perso","FRAME 7 LOST · NOT RESENT":"FRAME 7 PERSO · NON RINVIATO","Replies Come Back":"Arrivano le risposte","The other voice comes back":"L’altra voce torna indietro","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"La voce dell’altra persona arriva allo stesso modo, come datagrammi separati inviati alla porta 50000. Riescono a entrare perché il tuo router ha ricordato la porta in uscita quando ha tradotto il tuo indirizzo (NAT).",Direction:"Direzione","Independent of ours":"Indipendente dalla nostra","Through NAT":"Attraverso il NAT","Router remembers the port":"Il router ricorda la porta","the other person’s voice":"la voce dell’altra persona","sent to port 50000":"inviata alla porta 50000","The App Decides":"Decide l’app","Reliability is up to the app":"L’affidabilità spetta all’app","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"L’app di chiamata numera da sé i propri frame (lo fa RTP), quindi vede che manca il frame 7 e copre il buco di 20 ms invece di aspettare. Aspettare un rinvio farebbe andare in ritardo l’intera chiamata.","App’s job (e.g. RTP)":"Compito dell’app (es. RTP)",Loss:"Perdita","Hidden by the app":"Nascosta dall’app","Also on UDP":"Anche su UDP","DNS, games, QUIC":"DNS, giochi, QUIC","APP COVERS THE 20 MS GAP":"L’APP COPRE IL BUCO DI 20 MS","RTP + audio":"RTP + audio","Version etc.":"Versione ecc.","2, no padding, no extension, no CSRCs":"2, senza riempimento, senza estensione, senza CSRC","Marker, payload type":"Marker, tipo di payload","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, concordato all’avvio della chiamata)","Counts up by one per packet, so the app can spot a missing or late one.":"Aumenta di uno a ogni pacchetto, così l’app può accorgersi di uno mancante o in ritardo.",Timestamp:"Timestamp","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Orologio audio a 48,000 al secondo: +960 per frame da 20 ms.","Identifies this audio stream.":"Identifica questo flusso audio.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 byte di audio Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, concordato all’avvio della chiamata)","Addressing & Routing":"Indirizzamento e instradamento","Outgoing packet":"Pacchetto in uscita",Reply:"Risposta","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP dà a ogni dispositivo un indirizzo e sposta i pacchetti da una rete all’altra. Ogni router guarda solo l’indirizzo di destinazione per scegliere il prossimo salto. IP funziona «al meglio»: non promette né la consegna né l’ordine. Ci pensa TCP, sopra.","Network (Layer 3)":"Rete (livello 3)",Address:"Indirizzo","32 bits (IPv4), 128 (IPv6)":"32 bit (IPv4), 128 (IPv6)","20–60 bytes (IPv4)":"20–60 byte (IPv4)","Lowered by 1 at each router":"Diminuito di 1 a ogni router",Delivery:"Consegna","Best effort":"Al meglio","There and back":"Andata e ritorno","Twelve routers each way":"Dodici router per verso","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Il portatile ha inviato il pacchetto al suo router, che ci ha messo il proprio indirizzo pubblico. In tutto dodici router lo hanno passato avanti guardando solo l’indirizzo di destinazione, e la risposta ha ritrovato la strada allo stesso modo. Premi RIVEDI per guardarlo di nuovo.",Routers:"Router","12 each way (1 home + 11)":"12 per verso (1 di casa + 11)","TTL at server":"TTL al server","116 (sent with 128)":"116 (inviato con 128)","Rewritten by NAT":"Riscritti dal NAT","Source out, destination back":"Origine all’andata, destinazione al ritorno","IPv4 (IPv6 works alike)":"IPv4 (IPv6 funziona allo stesso modo)","Local or Not?":"Locale o no?","Compare the address with the subnet":"Confronta l’indirizzo con la sottorete","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Il portatile è 192.168.1.10 con maschera /24, quindi la sua rete va da 192.168.1.0 a 192.168.1.255. Il server, 203.0.113.10, è fuori da questo intervallo, quindi il pacchetto deve andare al gateway predefinito: il router di casa.",Laptop:"Portatile","Local range":"Intervallo locale",Gateway:"Gateway","203.0.113.10 IS NOT LOCAL":"203.0.113.10 NON È LOCALE","Find the Router":"Trova il router","ARP turns an IP into a MAC":"ARP trasforma un IP in un MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Sulla rete locale i frame vengono consegnati per indirizzo MAC. Se il MAC del router non è nella cache ARP del portatile, questo chiede a tutti «chi ha 192.168.1.1?» e il router risponde con il suo indirizzo MAC.",Asks:"Chiede","Who has 192.168.1.1?":"Chi ha 192.168.1.1?","Sent to":"Inviato a","Everyone (broadcast)":"Tutti (broadcast)",Learns:"Impara","Router’s MAC address":"L’indirizzo MAC del router","ARP REQUEST":"RICHIESTA ARP","who has 192.168.1.1?":"chi ha 192.168.1.1?","tell 192.168.1.10":"dillo a 192.168.1.10","ARP REPLY":"RISPOSTA ARP","Send the Packet":"Invia il pacchetto","Addresses, TTL and protocol":"Indirizzi, TTL e protocollo","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"L’intestazione IP porta gli indirizzi di origine e destinazione, un TTL e il protocollo contenuto. Qui contiene un SYN TCP verso la porta 443. Windows fa partire il TTL da 128 (Linux e macOS usano 64).","From → to":"Da → a","IP PACKET":"PACCHETTO IP","TTL 128 · protocol TCP":"TTL 128 · protocollo TCP","NAT, Then Hop by Hop":"NAT, poi salto dopo salto","The router rewrites and forwards":"Il router riscrive e inoltra","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Il router sostituisce l’origine privata con il suo indirizzo pubblico 198.51.100.7 (e qui la porta 52344 con 40112), annota la corrispondenza e abbassa il TTL a 127. Poi 11 router su Internet scelgono ciascuno il prossimo salto in base alla destinazione e abbassano di nuovo il TTL.","New source":"Nuova origine","Leaves home":"Esce di casa","At the server":"Al server","TTL 116 (11 more hops)":"TTL 116 (altri 11 salti)","TTL 127 · after NAT":"TTL 127 · dopo il NAT","ARRIVED WITH TTL 116":"ARRIVATO CON TTL 116","The Reply Comes Back":"Torna la risposta","NAT translates it for the laptop":"Il NAT la traduce per il portatile","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Il server risponde all’indirizzo che ha visto, 198.51.100.7:40112. Il router lo cerca nella sua tabella NAT, riscrive la destinazione in 192.168.1.10:52344 e la passa avanti. La risposta è partita con TTL 64 e arriva con 52.","Delivered to":"Consegnata a","64 → 52 (12 routers)":"64 → 52 (12 router)",REPLY:"RISPOSTA","TTL 52 · after NAT":"TTL 52 · dopo il NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (dopo il NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (dopo il NAT)","ARP request · 28 bytes":"Richiesta ARP · 28 byte","Broadcast: every device on the network receives it.":"Broadcast: lo riceve ogni dispositivo della rete.","The sender’s network card.":"La scheda di rete del mittente.","Hardware type":"Tipo di hardware","1 (Ethernet)":"1 (Ethernet)","Protocol type":"Tipo di protocollo","Address sizes":"Dimensioni degli indirizzi",Operation:"Operazione","1 (request: who has …?)":"1 (richiesta: chi ha …?)","Sender MAC":"MAC del mittente","Sender IP":"IP del mittente","Target MAC":"MAC di destinazione","All zeros: this is what the request wants to find out.":"Tutti zeri: è proprio ciò che la richiesta vuole scoprire.","Target IP":"IP di destinazione","ARP reply · 28 bytes":"Risposta ARP · 28 byte","Straight back to the device that asked.":"Diretta al dispositivo che ha chiesto.","2 (reply: … is at …)":"2 (risposta: … si trova a …)","Seen as it leaves the router’s internet side":"Visto mentre esce dal lato Internet del router","The internet provider’s router, the next hop.":"Il router del provider Internet, il prossimo salto.","The router’s internet-facing port.":"La porta del router rivolta verso Internet.","As sent: this system starts at 64.":"Come inviato: questo sistema parte da 64.","The router’s NAT swapped in its own port for the laptop’s.":"Il NAT del router ha messo una sua porta al posto di quella del portatile.","The sender’s next router; each hop puts the packet in a new frame.":"Il prossimo router del mittente; ogni salto mette il pacchetto in un nuovo frame.","Name Resolution":"Risoluzione dei nomi",Query:"Query",Referral:"Rimando","DNSSEC not requested here":"DNSSEC non richiesto qui","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"Il DNS trasforma nomi come www.example.com negli indirizzi IP che i computer usano per raggiungersi. Nessun server conosce tutti i nomi: il sistema è una gerarchia di server, e le risposte vengono messe in cache lungo la strada, così la maggior parte delle ricerche non deve mai andare lontano.","53, UDP (TCP if large)":"53, UDP (TCP se grande)",Turns:"Trasforma","Names into IP addresses":"Nomi in indirizzi IP",Hierarchy:"Gerarchia","Root → TLD → authoritative":"Radice → TLD → autorevole",Caching:"Cache","For each record’s TTL":"Per il TTL di ogni record","Name resolved":"Nome risolto","And remembered for an hour":"E ricordato per un’ora","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Partendo da una cache vuota, il resolver è andato dalla radice a .com fino al server di example.com, poi ha risposto al portatile. Finché non scade il TTL, la prossima ricerca di questo nome riceve risposta direttamente da una cache. Premi RIVEDI per guardarlo di nuovo.",Queries:"Query","4 (laptop 1, resolver 3)":"4 (portatile 1, resolver 3)","Cached for":"In cache per","Ask the Resolver":"Chiedi al resolver","The laptop hands the question off":"Il portatile passa la domanda","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Il browser ha bisogno dell’indirizzo IP di www.example.com e né lui né Windows ce l’hanno in cache. Il portatile manda una domanda al resolver ricorsivo che gli è stato assegnato, 8.8.8.8, e gli chiede di fare tutta la ricerca (ricorsione richiesta).","www.example.com, type A":"www.example.com, tipo A",Asked:"Chiesto a","8.8.8.8 (recursive)":"8.8.8.8 (ricorsivo)","RD (recursion desired)":"RD (ricorsione richiesta)","flags: RD":"flag: RD","Points the way to .com":"Indica la strada verso .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"La cache del resolver è vuota (si è appena avviato), quindi parte dall’alto. Un server radice non conosce l’indirizzo, ma sa quali server gestiscono .com e risponde con un rimando. Molti resolver gli mandano solo «com», non il nome intero.","Root servers":"Server radice","13 names, 1,000+ anycast sites":"13 nomi, oltre 1,000 siti anycast","Referral (13 .com servers)":"Rimando (13 server .com)","NOT IN CACHE":"NON IN CACHE",REFERRAL:"RIMANDO","no answer: ask .com":"nessuna risposta: chiedi a .com","Points the way to example.com":"Indica la strada verso example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Il resolver chiede a uno dei server .com. Nemmeno loro conservano gli indirizzi di ogni sito, ma sanno quali name server usa ogni dominio .com, quindi questa risposta è un altro rimando, con allegati gli indirizzi di quei server (glue).",Knows:"Conosce","Name servers of .com domains":"I name server dei domini .com","Referral + glue addresses":"Rimando + indirizzi glue","no answer: ask example.com":"nessuna risposta: chiedi a example.com","Gives the actual answer":"Dà la risposta vera","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Alla fine il resolver chiede al name server di example.com, che contiene i record del dominio. Risponde con il record A e segna la risposta come autorevole. Il proprietario del dominio decide per quanto può restare in cache: qui 3600 secondi.","AA (authoritative), TTL 3600":"AA (autorevole), TTL 3600",ANSWER:"RISPOSTA","TTL 3600 · flag AA":"TTL 3600 · flag AA","Answer & Cache":"Risposta e cache","The laptop gets its address":"Il portatile ottiene l’indirizzo","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Il resolver rimanda la risposta al portatile e ne tiene una copia. Per la prossima ora può rispondere subito per questo nome, ed è per questo che la ricerca nella lezione HTTP ha richiesto solo 24 ms. Anche il portatile la mette in cache.","RD, RA (recursion available)":"RD, RA (ricorsione disponibile)","Cached by":"In cache presso","Resolver and laptop":"Resolver e portatile","flags: RD RA":"flag: RD RA","CACHED · TTL 3600 S":"IN CACHE · TTL 3600 S","Referral: com. NS ×13 (with glue)":"Rimando: com. NS ×13 (con glue)","Referral: example.com. NS ×2 (with glue)":"Rimando: example.com. NS ×2 (con glue)","Response A 203.0.113.10 (authoritative)":"Risposta A 203.0.113.10 (autorevole)","As sent: this system starts at 128.":"Come inviato: questo sistema parte da 128.","0x0000: query":"0x0000: query","UDP size 1232, DNSSEC OK = 0":"Dimensione UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Dice quanto può essere grande una risposta UDP. Qui le firme DNSSEC non vengono chieste, per tenere breve la lezione; un resolver che le verifica, come 8.8.8.8, le chiede.","0x8000: response":"0x8000: risposta",Authority:"Autorità",Additional:"Aggiuntivi","0x8400: response, AA (authoritative)":"0x8400: risposta, AA (autorevole)","Getting an Address":"Ottenere un indirizzo","From the laptop":"Dal portatile","From the DHCP server":"Dal server DHCP","No IP address":"Nessun indirizzo IP","192.168.1.1 · DHCP server":"192.168.1.1 · server DHCP","Dynamic Host Configuration Protocol":"Dynamic Host Configuration Protocol","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP dà a un dispositivo tutto ciò che serve per usare una rete: un indirizzo IP, la maschera di sottorete, il router attraverso cui mandare il traffico e i server DNS da interrogare. Gli indirizzi sono dati in prestito per un tempo stabilito e rinnovati finché il dispositivo resta sulla rete.","UDP 67 (server), 68 (client)":"UDP 67 (server), 68 (client)","Hands out":"Assegna","IP, mask, gateway, DNS":"IP, maschera, gateway, DNS",Exchange:"Scambio",Lease:"Prestito","Renewed at half its time":"Rinnovato a metà del tempo","On the network":"In rete","Leased, and kept up to date":"In prestito, e sempre aggiornato","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Quattro messaggi hanno portato il portatile da nessun indirizzo a una configurazione funzionante, e a metà del prestito di 24 ore l’ha rinnovato con una richiesta diretta al router. Premi RIVEDI per guardarlo di nuovo.",Messages:"Messaggi","4 to join, 2 per renewal":"4 per entrare, 2 per rinnovo","24 h, renewed at 12 h":"24 h, rinnovato a 12 h","No Address Yet":"Ancora nessun indirizzo","The laptop joins the network":"Il portatile entra nella rete","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Il portatile si è appena collegato. Ha un indirizzo MAC integrato, ma nessun indirizzo IP, nessun gateway e nessun server DNS, quindi non può ancora parlare con nulla oltre la propria rete. Li chiede con DHCP.","IP address":"Indirizzo IP","None (uses 0.0.0.0)":"Nessuno (usa 0.0.0.0)","MAC address":"Indirizzo MAC",Needs:"Gli servono","NO IP ADDRESS YET":"ANCORA NESSUN INDIRIZZO IP",Discover:"Discover","Shout to the whole network":"Grida a tutta la rete","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Senza un indirizzo proprio, il portatile invia da 0.0.0.0 all’indirizzo di broadcast 255.255.255.255, così lo riceve ogni dispositivo della rete locale. Rispondono solo i server DHCP.",From:"Da","0.0.0.0, UDP port 68":"0.0.0.0, porta UDP 68","255.255.255.255, port 67":"255.255.255.255, porta 67",Carries:"Porta","MAC, transaction ID":"MAC, ID transazione","any DHCP server out there?":"c’è un server DHCP qui intorno?",Offer:"Offer","The router proposes an address":"Il router propone un indirizzo","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Il server DHCP del router sceglie un indirizzo libero e lo offre insieme alle altre impostazioni. Il portatile non può ancora usare un indirizzo IP, quindi l’offerta va direttamente al suo indirizzo MAC (alcuni client chiedono invece un broadcast).",Offered:"Offerto","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"offerta: 192.168.1.10/24","gateway, DNS, lease 24 h":"gateway, DNS, prestito 24 h","Accept, out loud":"Accettare, ad alta voce","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Il portatile chiede l’indirizzo offerto, nominando il server che ha scelto. Invia ancora in broadcast, così ogni altro server DHCP che ha fatto un’offerta sa di non essere stato scelto e può liberare il suo indirizzo.",Requests:"Chiede","Chosen server":"Server scelto","I’ll take 192.168.1.10":"prendo 192.168.1.10","from server 192.168.1.1":"dal server 192.168.1.1",Acknowledge:"Conferma","The address is the laptop’s":"L’indirizzo è del portatile","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Il server conferma e il portatile configura indirizzo, maschera, gateway e server DNS. Molti sistemi controllano prima con ARP che nessun altro dispositivo stia già usando l’indirizzo.","DNS server":"Server DNS","192.168.1.10 is yours":"192.168.1.10 è tuo","for 24 hours":"per 24 ore","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · PRESTITO 24 H",Renew:"Rinnovo","Halfway through the lease":"A metà del prestito","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Dodici ore dopo è passata metà del prestito. Ora il portatile ha un indirizzo, quindi chiede direttamente al router di prolungare il prestito, e il router lo riporta a 24 ore. Se il router non rispondesse, invierebbe in broadcast all’87.5%.",When:"Quando","50% of lease (T1 = 12 h)":"50% del prestito (T1 = 12 h)","The router (unicast)":"Il router (unicast)","If unanswered":"Se non risponde","Broadcast at 87.5% (T2)":"Broadcast all’87.5% (T2)","renew 192.168.1.10":"rinnova 192.168.1.10","sent straight to 192.168.1.1":"inviato direttamente a 192.168.1.1","lease renewed":"prestito rinnovato","another 24 hours":"altre 24 ore",Message:"Messaggio","1 (request, from a client)":"1 (richiesta, da un client)",Hardware:"Hardware","Ethernet, 6-byte addresses":"Ethernet, indirizzi di 6 byte",Hops:"Salti","Chosen by the client; every reply repeats it.":"Scelto dal client; ogni risposta lo ripete.",Seconds:"Secondi","0x0000 (unicast replies are fine)":"0x0000 (le risposte unicast vanno bene)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Flag di broadcast spento: il server può inviare direttamente all’indirizzo MAC del client.","Client address":"Indirizzo del client","Filled in only when the client already has an address (renewing).":"Compilato solo quando il client ha già un indirizzo (rinnovo).","Your address":"Il tuo indirizzo","The address the server is giving out.":"L’indirizzo che il server sta assegnando.","Next server":"Server successivo","Relay agent":"Agente di inoltro","Client MAC":"MAC del client","Server name, boot file":"Nome del server, file di avvio",empty:"vuoto","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Indica che le opzioni seguenti sono DHCP.","Message type: 1 (Discover)":"Tipo di messaggio: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Identificativo del client: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Nome host: alice-laptop","Vendor class: MSFT 5.0":"Classe del produttore: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Parametri richiesti: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252",End:"Fine","2 (reply, from a server)":"2 (risposta, da un server)","Message type: 2 (Offer)":"Tipo di messaggio: 2 (Offer)","Server identifier: 192.168.1.1":"Identificativo del server: 192.168.1.1","Lease time: 86,400 s (24 h)":"Durata del prestito: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Tempo di rinnovo (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Tempo di riassegnazione (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Maschera di sottorete: 255.255.255.0","Broadcast address: 192.168.1.255":"Indirizzo di broadcast: 192.168.1.255","Router: 192.168.1.1":"Router: 192.168.1.1","DNS server: 8.8.8.8":"Server DNS: 8.8.8.8","Message type: 3 (Request)":"Tipo di messaggio: 3 (Request)","Requested address: 192.168.1.10":"Indirizzo richiesto: 192.168.1.10","Client FQDN: alice-laptop":"FQDN del client: alice-laptop","Message type: 5 (ACK)":"Tipo di messaggio: 5 (ACK)","Network Diagnostics":"Diagnostica di rete","Ping / probe":"Ping / sonda","Echo reply":"Risposta echo","Error report":"Segnalazione di errore","Internet Control Message Protocol":"Internet Control Message Protocol","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP è il modo in cui la rete risponde: un router dice che il tempo di un pacchetto è scaduto, un server dice che nessuno ascolta su una porta. Strumenti come ping e traceroute sono costruiti con questi messaggi. Viaggia dentro IP ma non trasporta dati applicativi.","Carried in":"Trasportato in","IP (protocol 1)":"IP (protocollo 1)","A type and a code":"Un tipo e un codice",Tools:"Strumenti",Often:"Spesso","Filtered by firewalls":"Filtrato dai firewall","The network answered":"La rete ha risposto","Replies, expiries and errors":"Risposte, scadenze ed errori","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Una richiesta echo ha misurato il viaggio di andata e ritorno, pacchetti con un TTL piccolo hanno fatto identificare ogni router lungo il percorso e una porta chiusa è stata segnalata subito indietro. Premi RIVEDI per guardarlo di nuovo.","Round trip":"Andata e ritorno",Path:"Percorso","12 routers, server at hop 13":"12 router, server al salto 13","Types used":"Tipi usati","8, 0, 11 and 3":"8, 0, 11 e 3","Reply TTL":"TTL della risposta","52 (64 − 12 routers)":"52 (64 − 12 router)",Ping:"Ping","Echo request":"Richiesta echo","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"«ping -n 1 203.0.113.10» invia una richiesta echo ICMP (il ping semplice ne invia quattro, a un secondo di distanza): tipo 8, codice 0, con un identificativo, un numero di sequenza e 32 byte di riempimento. Il sistema del server risponde da solo, senza bisogno di un’applicazione.","Type, code":"Tipo, codice","8, 0 (echo request)":"8, 0 (richiesta echo)","32 bytes (Windows)":"32 byte (Windows)","ECHO REQUEST":"RICHIESTA ECHO","type 8 · seq 1":"tipo 8 · seq 1","32 bytes of data":"32 byte di dati","Echo Reply":"Risposta echo","Round-trip time":"Tempo di andata e ritorno","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Il server rimanda una risposta echo, tipo 0, con lo stesso identificativo, numero di sequenza e dati. Ping stampa il tempo impiegato e il TTL con cui è arrivata la risposta: «bytes=32 time=34ms TTL=52».","0, 0 (echo reply)":"0, 0 (risposta echo)","TTL on arrival":"TTL all’arrivo","ECHO REPLY":"RISPOSTA ECHO","type 0 · seq 1":"tipo 0 · seq 1","same 32 bytes back":"gli stessi 32 byte indietro","TIME=34MS TTL=52":"TIME=34MS TTL=52","The first router answers":"Risponde il primo router","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"«ping -n 1 -i 1» invia la stessa richiesta con un TTL di 1. Il router di casa lo abbassa a 0, quindi deve scartare il pacchetto, e rimanda un messaggio Time Exceeded dal proprio indirizzo: «Reply from 192.168.1.1: TTL expired in transit.»","Sent with":"Inviato con","Dropped by":"Scartato da","11, 0 (time exceeded)":"11, 0 (tempo scaduto)","echo request":"richiesta echo","expires at the first router":"scade al primo router","TIME EXCEEDED":"TEMPO SCADUTO","type 11 · from 192.168.1.1":"tipo 11 · da 192.168.1.1","quotes the dropped header":"cita l’intestazione scartata","The next router answers":"Risponde il router successivo","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Con «-i 2», il router di casa abbassa il TTL a 1 e lo inoltra. Il primo router del provider Internet lo abbassa a 0 e risponde da 198.51.100.1. Il router di casa traduce la segnalazione per il portatile come qualsiasi risposta.","ISP router 198.51.100.1":"Router del provider 198.51.100.1","expires at the second router":"scade al secondo router","HOP 2 · 198.51.100.1":"SALTO 2 · 198.51.100.1","type 11 · from 198.51.100.1":"tipo 11 · da 198.51.100.1","That’s Traceroute":"Ecco traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … finché non arriva","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert lo automatizza: alza il TTL di uno ogni volta, invia tre sonde per salto ed elenca chi risponde. I salti da 3 a 12 funzionano allo stesso modo, e con TTL 13 la richiesta raggiunge finalmente il server, che risponde normalmente.","12 routers, then the server":"12 router, poi il server","Per hop":"Per salto","3 probes":"3 sonde","On Linux":"Su Linux","traceroute sends UDP":"traceroute invia UDP","enough hops to arrive":"abbastanza salti per arrivare","the server itself answers":"risponde il server stesso","end of the route":"fine del percorso",Unreachable:"Irraggiungibile","Nothing listening on that port":"Nessuno ascolta su quella porta","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Un’app invia un datagramma UDP alla porta 9999, dove nessuno ascolta. Il server non può consegnarlo, quindi risponde con Destination Unreachable, codice 3 (porta irraggiungibile), citando l’inizio del datagramma. Molti firewall invece scartano questi pacchetti in silenzio.","3, 3 (port unreachable)":"3, 3 (porta irraggiungibile)","Other codes":"Altri codici","0 net, 1 host, 4 too big":"0 rete, 1 host, 4 troppo grande",Firewalls:"Firewall","Often silent instead":"Spesso muti invece","to port 9999":"alla porta 9999","nothing listening there":"nessuno ascolta lì",UNREACHABLE:"IRRAGGIUNGIBILE","type 3 · code 3":"tipo 3 · codice 3","port unreachable":"porta irraggiungibile","ICMP · Echo request":"ICMP · Richiesta echo",Code:"Codice","Covers the whole ICMP message.":"Copre l’intero messaggio ICMP.",Identifier:"Identificativo","Matches replies to this ping program.":"Abbina le risposte a questo programma ping.","Windows counts up across every ping it sends.":"Windows conta in avanti su ogni ping che invia.",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 byte)',"Windows ping’s filler: the alphabet, a to w, then again.":"Il riempimento del ping di Windows: l’alfabeto dalla a alla w, poi di nuovo.","ICMP · Echo reply":"ICMP · Risposta echo","Sent back exactly as it came.":"Rimandati esattamente come sono arrivati.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Tempo scaduto (TTL arrivato a 0)","Time exceeded (TTL reached 0)":"Tempo scaduto (TTL arrivato a 0)",Unused:"Non usato","Original packet":"Pacchetto originale","Its source, destination":"La sua origine e destinazione","its IP header and first 8 bytes (28 bytes)":"la sua intestazione IP e i primi 8 byte (28 byte)","App data":"Dati dell’app",'"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 byte)',"What the app sent; nothing on the server is listening for it.":"Ciò che l’app ha inviato; sul server nessuno è in ascolto.","ICMP · Destination unreachable (port unreachable)":"ICMP · Destinazione irraggiungibile (porta irraggiungibile)","Destination unreachable (port unreachable)":"Destinazione irraggiungibile (porta irraggiungibile)","Sending Email":"Invio della posta","SMTP command":"Comando SMTP","SMTP reply":"Risposta SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP sposta la posta: dalla tua app di posta al server del tuo provider, e da quel server a quello del destinatario. È una conversazione di brevi comandi testuali, ciascuno con una risposta da un codice a tre cifre. Leggere la posta è un altro lavoro, fatto con IMAP o POP3.","465/587 submit, 25 relay":"465/587 invio, 25 inoltro","TCP, usually with TLS":"TCP, di solito con TLS",Commands:"Comandi",Replies:"Risposte","2xx ok, 3xx go on, 4/5xx error":"2xx ok, 3xx continua, 4/5xx errore","Mail delivered":"Posta consegnata","Two hops, one message":"Due salti, un messaggio","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"L’app di Alice ha consegnato il messaggio al suo provider su una connessione cifrata e autenticata. Il provider ha trovato il server di posta di Bob nel DNS e l’ha inoltrato lì, portando quel collegamento a TLS. Ora aspetta nella casella di Bob finché lui non lo legge con IMAP o POP3.","Laptop → provider → Bob’s":"Portatile → provider → Bob",Submission:"Invio","Port 465, TLS, login":"Porta 465, TLS, accesso",Relay:"Inoltro","Port 25, STARTTLS":"Porta 25, STARTTLS","Checks at Bob’s":"Controlli da Bob","Connect Securely":"Connessione sicura","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice preme Invia. La sua app di posta si collega al server di invio del provider, smtp.example.com, sulla porta 465. Su questa porta TLS parte subito, quindi tutta la conversazione SMTP, password compresa, è cifrata.","TLS from the start":"TLS fin dall’inizio","SMTP inside TLS":"SMTP dentro TLS","Greeting & Login":"Saluto e accesso","EHLO, then AUTH":"EHLO, poi AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Il server saluta con il codice 220. L’app dice EHLO e il server elenca ciò che supporta, tra cui AUTH. L’app accede con AUTH PLAIN (nome utente e password, in base64) e riceve 235: autenticato.",Greeting:"Saluto",Capabilities:"Funzionalità","Login result":"Esito dell’accesso","user and password, base64":"utente e password, base64","Send the Message":"Invio del messaggio","Envelope, then content":"Busta, poi contenuto","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM e RCPT TO sono la busta: mittente e destinatario. PIPELINING permette ai tre comandi di stare in un solo pacchetto. Dopo 354 arriva il messaggio, chiuso da una riga che contiene solo un punto.",Envelope:"Busta","Content ends":"Il contenuto finisce","A line with only “.”":"Una riga con solo «.»",Result:"Esito",MESSAGE:"MESSAGGIO","… message …":"… messaggio …","250 QUEUED":"250 IN CODA","Find Bob’s Server":"Il server di Bob","An MX lookup in DNS":"Una ricerca MX nel DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Ora il provider di Alice deve consegnare a example.org. Chiede al DNS il record MX di quel dominio, che indica il server che ne accetta la posta, poi cerca l’indirizzo di quel server.","MX record":"Record MX","Asked by":"Chiesto da","Alice’s provider":"Il provider di Alice","Server to Server":"Da server a server","Port 25, upgraded with STARTTLS":"Porta 25, portata a TLS con STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Il provider si collega a mx.example.org sulla porta 25. Questa conversazione parte in chiaro: il saluto e la risposta a EHLO annunciano STARTTLS, il provider lo chiede, riceve 220 ed entrambi passano a TLS.","Starts as":"Parte come","Plain text":"Testo in chiaro",Upgrade:"Passaggio a TLS",Deliver:"Consegna","The same transaction again":"Di nuovo la stessa transazione","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Con TLS attivo, il provider ripete EHLO, poi la busta e il messaggio, ora con una firma DKIM e un’intestazione Received aggiunte. Il server di Bob controlla SPF, DKIM e DMARC e lo accetta.","Login needed":"Accesso richiesto","No (server to server)":"No (da server a server)","1,316 bytes (signed)":"1,316 byte (firmato)","IN BOB’S MAILBOX":"NELLA CASELLA DI BOB","Server Hello + encrypted handshake, 2 segments":"Server Hello + handshake cifrato, 2 segmenti","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 funzionalità (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (credenziali)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (in pipeline)","Message (316 bytes), then “.”":"Messaggio (316 byte), poi «.»","250 capabilities (PIPELINING, STARTTLS …)":"250 funzionalità (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 funzionalità (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Messaggio (1,316 byte), poi «.»","What this client supports. Its exact contents vary from client to client; this is an example.":"Ciò che supporta questo client. Il contenuto esatto cambia da client a client; questo è un esempio.","up to 512 bytes":"fino a 512 byte","The server’s choices and its key share.":"Le scelte del server e la sua condivisione di chiave.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (la catena), Certificate Verify (la firma), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Il messaggio di Alice (316 byte), poi una riga che contiene solo «.»","example.org, type MX, class IN":"example.org, tipo MX, classe IN","mx.example.org, type A, class IN":"mx.example.org, tipo A, classe IN",Timestamps:"Timestamp","Used to measure round trips; both sides offered them.":"Usati per misurare i viaggi di andata e ritorno; li hanno offerti entrambi i lati.","The signed message (1,316 bytes), then a line holding only “.”":"Il messaggio firmato (1,316 byte), poi una riga che contiene solo «.»","Downloading Email":"Scaricare la posta","POP3 command":"Comando POP3","POP3 reply":"Risposta POP3","Post Office Protocol, version 3":"Post Office Protocol, versione 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 permette a un’app di posta di scaricare i messaggi da una casella su un server. È nato per un solo dispositivo che scarica la posta e poi la toglie dal server. I comandi sono parole brevi e ogni risposta inizia con +OK o -ERR.",Model:"Modello","Download, then delete":"Scarica, poi elimina","+OK or -ERR":"+OK o -ERR","Mail downloaded":"Posta scaricata","And gone from the server":"E sparita dal server","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"L’app di Bob ha effettuato l’accesso, ha visto due messaggi, ha scaricato il primo e l’ha eliminato, cosa che il server ha eseguito al QUIT. Ora quel messaggio esiste solo su questo portatile, ed è per questo che POP3 va bene per un dispositivo e IMAP per diversi.","2 waiting, 1 downloaded":"2 in attesa, 1 scaricato",Deleted:"Eliminato","At QUIT (UPDATE state)":"Al QUIT (stato UPDATE)","Best for":"Ideale per","A single device":"Un solo dispositivo","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"L’app di posta di Bob si collega a pop.example.org sulla porta 995, dove TLS parte subito. Al suo interno il server saluta con +OK. (Sulla porta 110 la sessione parte in chiaro e passa a TLS con il comando STLS.)","Log In":"Accesso","USER, then PASS":"USER, poi PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"L’app invia il nome utente con USER e la password con PASS. Ogni comando riceve il suo +OK. Poiché la sessione è dentro TLS, la password non è leggibile lungo la strada.","Protected by":"Protetto da","Check the Mailbox":"Controllo della casella","STAT and LIST":"STAT e LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT restituisce il numero di messaggi e la loro dimensione totale: 2 messaggi, 5120 byte. LIST dà numero e dimensione di ogni messaggio, chiudendo con una riga che contiene solo un punto.","Message 1":"Messaggio 1","Message 2":"Messaggio 2",Download:"Download","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 chiede il primo messaggio. Il server risponde +OK con la sua dimensione, poi il messaggio e un punto finale: 1904 byte più la riga di risposta, due segmenti TCP.",Command:"Comando","Delete & Quit":"Elimina ed esci","Deleted only at QUIT":"Eliminato solo al QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 si limita a segnare il messaggio. Il server lo rimuove quando l’app dice QUIT: se la connessione cadesse prima, non verrebbe eliminato nulla. Molte app offrono «lascia una copia sul server», che salta DELE.","Marks message 1":"Segna il messaggio 1",Removed:"Rimosso","At QUIT":"Al QUIT",Option:"Opzione","Leave a copy on server":"Lascia una copia sul server","MESSAGE 1 DELETED":"MESSAGGIO 1 ELIMINATO","PASS (password)":"PASS (password)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, messaggio, «.» (2 segmenti)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, il messaggio da 1,904 byte, poi una riga che contiene solo «.»","IMAP command":"Comando IMAP","IMAP response":"Risposta IMAP","Internet Message Access Protocol":"Internet Message Access Protocol","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP permette alle app di posta di lavorare con una casella che resta sul server. Cartelle, segni di letto e contrassegnato ed eliminazioni restano lì, così telefono, portatile e webmail vedono tutti la stessa casella. Il server può anche avvisare un’app della nuova posta appena arriva.","Mail stays on the server":"La posta resta sul server",Syncs:"Sincronizza","Folders and flags":"Cartelle e contrassegni","Mailbox in sync":"Casella sincronizzata","Read once, read everywhere":"Letto una volta, letto ovunque","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"L’app di Bob ha aperto la posta in arrivo e ha letto un messaggio, che sul server è stato segnato \\Seen per tutti i suoi dispositivi, poi ha atteso con IDLE finché il server non ha annunciato nuova posta. Non è stato eliminato nulla: il server conserva ancora tutto.","2, then 3 (new mail)":"2, poi 3 (nuova posta)","Read mark":"Segno di letto","\\Seen, stored on server":"\\Seen, salvato sul server","New mail":"Nuova posta","Pushed during IDLE":"Inviata durante IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"L’app di Bob si collega a imap.example.org sulla porta 993, dove TLS parte subito. Il server saluta con una riga «* OK» senza tag che elenca anche le sue funzionalità, come IDLE.","Commands carry tags":"I comandi hanno un tag","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Ogni comando inizia con un tag scelto dall’app, come a1, e il server chiude la risposta con lo stesso tag. Così più comandi possono essere in corso e ogni risposta viene abbinata. Le righe che iniziano con * sono dati senza tag.",Tags:"Tag","Match replies to commands":"Abbinano risposte e comandi","Open the Inbox":"Apri la posta in arrivo","SELECT a folder":"SELECT di una cartella","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX apre la cartella. Il server indica il numero di messaggi, i contrassegni che supporta e il primo messaggio non letto, poi conferma che la cartella è aperta in lettura e scrittura.","First unread":"Primo non letto",Access:"Accesso","Read a Message":"Leggi un messaggio","FETCH, and the \\Seen flag":"FETCH e il contrassegno \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] scarica il messaggio 2 (tre segmenti TCP). Questo imposta il suo contrassegno \\Seen sul server, quindi appare come letto anche sul telefono di Bob, e il messaggio resta lì.","Flag set":"Contrassegno impostato","\\Seen (on the server)":"\\Seen (sul server)","STILL ON SERVER · \\SEEN":"ANCORA SUL SERVER · \\SEEN","Wait for New Mail":"Attendi nuova posta","IDLE: the server pushes":"IDLE: il server avvisa","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE dice al server «avvisami quando cambia qualcosa». Circa 42 secondi dopo arriva il messaggio di Alice e il server invia subito «* 3 EXISTS». L’app chiude IDLE con DONE e può scaricare la nuova posta.","Server says":"Il server dice","* 3 EXISTS (new mail)":"* 3 EXISTS (nuova posta)","Ended by":"Chiuso da","NEW MAIL ARRIVED":"È ARRIVATA NUOVA POSTA","a1 LOGIN (user and password)":"a1 LOGIN (utente e password)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, il messaggio da 3,216 byte, poi a3 OK FETCH completed","Transferring Files":"Trasferire file","FTP command":"Comando FTP","FTP reply":"Risposta FTP","File data":"Dati del file","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP sposta file tra un client e un server. È insolito perché usa due connessioni TCP: una per comandi e risposte, e una nuova per ogni file o elenco. Risale ai primi anni ’70 e invia tutto, password comprese, in chiaro.","21 control, data varies":"21 controllo, dati variabile",Connections:"Connessioni","Control + one per transfer":"Controllo + una per trasferimento",Encryption:"Cifratura","None (plain text)":"Nessuna (testo in chiaro)","Safer options":"Alternative più sicure","SFTP, or FTPS (FTP + TLS)":"SFTP, o FTPS (FTP + TLS)","File downloaded":"File scaricato","Two connections, no encryption":"Due connessioni, nessuna cifratura","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"I comandi sono passati sulla connessione di controllo, il file sulla sua connessione dati, e la chiusura di quella connessione ha segnato la fine del file. Chiunque lungo il percorso avrebbe potuto leggere la password e il file, ed è per questo che oggi si usa SFTP o FTPS.","2 (control + data)":"2 (controllo + dati)",File:"File","4,000 bytes, 3 segments":"4,000 byte, 3 segmenti",Password:"Password","Sent in plain text":"Inviata in chiaro","Use instead":"Usa invece","SFTP or FTPS":"SFTP o FTPS","Control Connection":"Connessione di controllo","Port 21, plain text":"Porta 21, testo in chiaro","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"L’app FTP apre una connessione TCP verso ftp.example.com sulla porta 21. Questa connessione di controllo porta comandi e risposte per tutta la sessione. Il server saluta con 220. Come in SMTP, ogni risposta inizia con un codice a tre cifre.","USER and PASS, readable by anyone":"USER e PASS, leggibili da chiunque","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"L’app invia USER, il server chiede la password con 331 e PASS la invia. Niente è cifrato, quindi nome utente e password attraversano ogni rete lungo la strada come testo leggibile.","Visible to":"Visibile a","Anyone on the path":"Chiunque lungo il percorso","PASSWORD IN PLAIN TEXT":"PASSWORD IN CHIARO","Passive Mode":"Modalità passiva","The server names a data port":"Il server indica una porta dati","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I chiede una copia binaria byte per byte. PASV chiede al server di aprire una porta per la connessione dati. La risposta codifica indirizzo e porta come sei numeri: 195 × 256 + 149 = porta 50069. Il portatile si collega in uscita, e questo funziona attraverso il NAT.","Data port":"Porta dati","Active mode":"Modalità attiva","Server dials in: NAT blocks":"Il server chiama: il NAT blocca","Data Connection":"Connessione dati","A second TCP connection":"Una seconda connessione TCP","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"L’app apre una seconda connessione TCP, verso la porta 50069, e chiede il file sulla connessione di controllo con RETR. Il server risponde 150 lì e inizia a inviare il file sulla nuova connessione.","Data to":"Dati verso","The File Arrives":"Arriva il file","Closing the connection ends it":"La chiusura della connessione segna la fine","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"I 4,000 byte arrivano in 3 segmenti TCP. FTP non mette alcuna indicazione di lunghezza nei dati: il server chiude la connessione dati per segnare la fine del file. Quando il portatile ha confermato tutto, il server conferma con 226 sulla connessione di controllo.","report.pdf, 4,000 bytes":"report.pdf, 4,000 byte","End of file":"Fine del file","Data connection closed":"Connessione dati chiusa","3 SEGMENTS":"3 SEGMENTI","4,000 bytes, readable by anyone":"4,000 byte, leggibili da chiunque","end of file:":"fine del file:","data connection closed":"connessione dati chiusa",Quit:"Uscita","Close the control connection":"Chiudi la connessione di controllo","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT chiude la sessione e il server saluta con 221. Per tutto ciò che è riservato, SFTP (un protocollo diverso, che funziona su SSH) o FTPS (FTP dentro TLS) fanno lo stesso lavoro con la cifratura.","Encrypted cousins":"Cugini cifrati","FTP data":"Dati FTP","The file itself, unencrypted: anyone on the path could read it.":"Il file stesso, non cifrato: chiunque lungo il percorso potrebbe leggerlo.","Secure Remote Login":"Accesso remoto sicuro","Plain setup":"Avvio in chiaro","From laptop":"Dal portatile","From server":"Dal server","Some packets not shown":"Alcuni pacchetti non mostrati","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH ti dà una connessione cifrata e autenticata verso un altro computer, per eseguirvi comandi, copiare file (SFTP, scp) o far passare altre connessioni. Il server dimostra chi è con una chiave host; tu dimostri chi sei con una coppia di chiavi o una password.","Server proves":"Il server dimostra","Host key (known_hosts)":"Chiave host (known_hosts)","You prove":"Tu dimostri","Key pair or password":"Coppia di chiavi o password","Logged in securely":"Accesso sicuro effettuato","Encrypted from the key exchange on":"Cifrato dallo scambio di chiavi in poi","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"I due lati hanno concordato gli algoritmi, hanno costruito chiavi condivise con uno scambio ibrido post-quantistico e il server ha dimostrato la sua identità con la chiave host. Alice ha dimostrato la sua firmando con una chiave privata che non ha mai lasciato il portatile, poi ha scritto un comando, un pacchetto per tasto.",Login:"Accesso","Ed25519 key, no password":"Chiave Ed25519, senza password","Say Hello":"Saluto","Versions, in plain text":"Versioni, in chiaro","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice esegue «ssh alice@server.example.com». Dopo l’handshake TCP sulla porta 22, ogni lato invia una riga di testo in chiaro con la versione del protocollo SSH (2.0) e il proprio software. Tutto il resto di SSH è binario.",VERSION:"VERSIONE","Agree on Algorithms":"Accordo sugli algoritmi","KEXINIT lists, first match wins":"Liste KEXINIT, vince la prima corrispondenza","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Ogni lato invia un KEXINIT che elenca ogni algoritmo supportato, in ordine di preferenza, per scambio di chiavi, chiavi host, cifratura, integrità e compressione. In ogni categoria viene scelto il primo algoritmo della lista del portatile che anche il server supporta.","Host key":"Chiave host","server’s algorithm lists":"liste di algoritmi del server","in order of preference":"in ordine di preferenza","laptop’s algorithm lists":"liste di algoritmi del portatile","Key Exchange":"Scambio di chiavi","Shared keys, and a host key check":"Chiavi condivise e verifica della chiave host","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Il portatile invia la sua metà di uno scambio ibrido: una chiave Streamlined NTRU Prime, scelta per resistere ai futuri computer quantistici, più una chiave X25519. Il server risponde con la sua metà, la sua chiave host e una firma sullo scambio. NEWKEYS attiva la cifratura.",Hybrid:"Ibrido","Matches known_hosts":"Corrisponde a known_hosts","First visit":"Prima visita","ssh asks you to confirm":"ssh ti chiede di confermare","public keys":"chiavi pubbliche","its half, its host key":"la sua metà, la sua chiave host","and a signature":"e una firma","HOST KEY MATCHES KNOWN_HOSTS":"LA CHIAVE HOST CORRISPONDE A KNOWN_HOSTS","Log In with a Key":"Accesso con una chiave","Sign, don’t send a secret":"Firma, non inviare un segreto","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Il server elenca i metodi di accesso che accetta. Il portatile offre la chiave pubblica di Alice e il server dice che la accetterebbe. Poi il portatile firma questa sessione con la chiave privata, che non lascia mai il portatile. Il server verifica la firma rispetto ad authorized_keys.",Methods:"Metodi",Key:"Chiave","Ed25519, private stays here":"Ed25519, la privata resta qui","Checked with":"Verificata con","AUTH FAILURE":"AUTH FALLITA","OFFER KEY":"OFFRE LA CHIAVE","alice’s public key":"chiave pubblica di alice","would you accept it?":"la accetteresti?","yes, that key":"sì, quella chiave","is in authorized_keys":"è in authorized_keys",SIGNED:"FIRMATO","same key, plus a signature":"stessa chiave, più una firma","made with the private key":"fatta con la chiave privata",SUCCESS:"SUCCESSO","logged in":"accesso effettuato","Open a Session":"Apertura di una sessione","Channels inside one connection":"Canali dentro una connessione","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Una connessione SSH può portare molti canali: una shell, trasferimenti di file, porte inoltrate. Il portatile apre un canale di sessione, poi chiede un terminale e una shell (non mostrato), e il server invia il testo di benvenuto e un prompt.",Channel:"Canale",session:"session","Then asks for":"Poi chiede","A terminal and a shell":"Un terminale e una shell","Also possible":"Possibili anche","SFTP, port forwarding":"SFTP, inoltro di porte","CHANNEL OPEN":"APERTURA CANALE","open a channel:":"apri un canale:",CONFIRMED:"CONFERMATO","channel open":"canale aperto","Type a Command":"Scrivi un comando","Every key is a packet":"Ogni tasto è un pacchetto","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice scrive pwd. Ogni tasto parte subito nel suo pacchetto cifrato, e il server rimanda il carattere da mostrare (l’eco). Dalla 9.5, OpenSSH invia i tasti a un ritmo di 20 ms e aggiunge pacchetti esca, così il ritmo di battitura è più difficile da leggere dai tempi.","Per key":"Per tasto","1 packet, 90 bytes":"1 pacchetto, 90 byte",Echo:"Eco","Sent back by the server":"Rimandato dal server",Timing:"Tempi","20 ms beat plus decoys":"Ritmo di 20 ms più esche",ECHO:"ECO",ENTER:"INVIO","Enter key":"Tasto Invio",OUTPUT:"OUTPUT","EACH KEY IS ITS OWN PACKET":"OGNI TASTO È UN PACCHETTO","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (chiavi pubbliche sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (chiave host, la sua metà, firma)","Encrypted (len=44): service request, ssh-userauth":"Cifrato (len=44): richiesta di servizio, ssh-userauth","Encrypted (len=44): service accept":"Cifrato (len=44): servizio accettato","Encrypted (len=68): login with method none":"Cifrato (len=68): accesso con metodo none","Encrypted (len=52): try publickey,password":"Cifrato (len=52): prova publickey,password","Encrypted (len=140): offer public key":"Cifrato (len=140): offre la chiave pubblica","Encrypted (len=100): public key OK":"Cifrato (len=100): chiave pubblica OK","Encrypted (len=308): public key + signature":"Cifrato (len=308): chiave pubblica + firma","Encrypted (len=28): login success":"Cifrato (len=28): accesso riuscito","Encrypted (len=52): channel open: session":"Cifrato (len=52): apertura canale: session","Encrypted (len=44): channel open confirmed":"Cifrato (len=44): apertura canale confermata","Encrypted (len=36): keystroke":"Cifrato (len=36): tasto","Encrypted (len=36): echo":"Cifrato (len=36): eco","Encrypted (len=36): keystroke (Enter)":"Cifrato (len=36): tasto (Invio)","Encrypted (len=132): output and a new prompt":"Cifrato (len=132): output e un nuovo prompt","Packet length":"Lunghezza del pacchetto","Bytes after this field.":"Byte dopo questo campo.","Padding length":"Lunghezza del riempimento","Random padding brings the packet to a multiple of 8 bytes.":"Un riempimento casuale porta il pacchetto a un multiplo di 8 byte.",Cookie:"Cookie","Host keys":"Chiavi host","Ciphers, out":"Cifrari, in uscita","Ciphers, in":"Cifrari, in entrata","MACs, out":"MAC, in uscita","MACs, in":"MAC, in entrata","Compression, out":"Compressione, in uscita","Compression, in":"Compressione, in entrata","Languages, out":"Lingue, in uscita","Languages, in":"Lingue, in entrata","First packet follows":"Segue il primo pacchetto",Reserved:"Riservato","Public keys":"Chiavi pubbliche","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 byte (sntrup761 1,158 + X25519 32)","51 bytes: ssh-ed25519 public key":"51 byte: chiave pubblica ssh-ed25519","Server’s half":"Metà del server","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 byte (testo cifrato sntrup761 1,039 + X25519 32)",Signature:"Firma","83 bytes: ssh-ed25519 signature over the exchange":"83 byte: firma ssh-ed25519 sullo scambio","From the next packet on, this side encrypts.":"Dal prossimo pacchetto in poi, questo lato cifra.","SSH · encrypted packet":"SSH · pacchetto cifrato","Encrypted packet":"Pacchetto cifrato","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Con chacha20-poly1305 è cifrata perfino la lunghezza; un tag di 16 byte alla fine rivela qualsiasi modifica.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): utente «alice», servizio «ssh-connection», metodo «none»","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): metodi con cui continuare: «publickey,password»","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): metodo «publickey», senza firma, la chiave pubblica ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): la stessa chiave ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): metodo «publickey-hostbound-v00@openssh.com», la chiave, la chiave host del server e una firma","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): «session», canale 0, finestra 2 MB, pacchetti fino a 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): il canale 0 è aperto","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, «p»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, «p», rimandato da mostrare","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, «w»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, «w», rimandato da mostrare","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, «d»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, «d», rimandato da mostrare","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), canale 0: 1 byte, un ritorno a capo (Invio)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), canale 0: 94 byte: una nuova riga, i codici di terminale della shell, «/home/alice» e il prompt colorato","From browser":"Dal browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS mette un canale sicuro sopra TCP. Dimostra l’identità del server con un certificato, concorda nuove chiavi, poi cifra e autentica tutto ciò che viene inviato. HTTPS, la posta sicura e molti altri protocolli funzionano al suo interno. SSL era il nome del suo predecessore.",Sits:"Si trova","Between TCP and the app":"Tra TCP e l’app","OSI layer":"Livello OSI","Often placed at 6":"Spesso messo al 6",Current:"Attuale",Retired:"Ritirati","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 e 3, TLS 1.0 e 1.1","The app’s own (443, 993 …)":"Quella dell’app (443, 993 …)","Secure from start to finish":"Sicuro dall’inizio alla fine","One round trip to set up":"Un viaggio di andata e ritorno per avviarlo","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Un solo viaggio di andata e ritorno ha concordato una versione, un cifrario e una chiave ibrida post-quantistica. La catena di certificati ha dimostrato chi era il server, e ogni byte dopo il Server Hello è stato cifrato e autenticato, fino al close_notify. Premi RIVEDI per guardarlo di nuovo.","1 round trip":"1 viaggio di andata e ritorno","Everything the browser supports":"Tutto ciò che il browser supporta","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Dopo l’handshake TCP il browser elenca ciò che sa fare: versioni TLS, suite di cifratura e condivisioni di chiave per i gruppi che si aspetta, compreso l’ibrido post-quantistico X25519MLKEM768. Indica anche il sito (SNI) e i protocolli che parla (ALPN).",Versions:"Versioni","versions, ciphers, key shares":"versioni, cifrari, key share","Choices made, keys computed":"Scelte fatte, chiavi calcolate","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Il server sceglie TLS 1.3, la suite di cifratura e il gruppo ibrido, e invia la propria condivisione di chiave. Dalle due condivisioni entrambi i lati calcolano lo stesso segreto senza che attraversi mai la rete. Tutto ciò che segue questo messaggio è cifrato.",Group:"Gruppo","From here on":"Da qui in poi","its key share":"la sua key share","SHARED SECRET COMPUTED":"SEGRETO CONDIVISO CALCOLATO",Certificate:"Certificato","Who the server is, proven":"Chi è il server, dimostrato","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Ora cifrato, il volo continua: il protocollo scelto (http/1.1), la catena di certificati, una firma fatta con la chiave privata del certificato e Finished.",Chain:"Catena","Site → intermediate → root":"Sito → intermedio → radice","Proves the private key":"Dimostra la chiave privata",Checked:"Verificati","Name, dates, trusted root":"Nome, date, radice fidata","encrypted: http/1.1, certificates,":"cifrati: http/1.1, certificati,","signature, Finished":"firma, Finished","CHAIN LEADS TO A TRUSTED ROOT":"LA CATENA PORTA A UNA RADICE FIDATA","One round trip, then data":"Un viaggio di andata e ritorno, poi i dati","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Il browser invia il proprio Finished: un valore di controllo su tutto ciò che i due lati si sono detti, calcolato con il nuovo segreto, così qualsiasi manomissione dei saluti verrebbe scoperta. TLS 1.3 richiede un solo viaggio di andata e ritorno prima che i dati scorrano; TLS 1.2 ne richiedeva due.",Covers:"Copre","The whole handshake":"L’intero handshake","For old middleboxes":"Per i vecchi apparati intermedi","check value over":"valore di controllo su","the whole handshake":"l’intero handshake","Encrypted Data":"Dati cifrati","Records, tags and tickets":"Record, tag e ticket","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"Ora HTTP viaggia in record cifrati, ciascuno con un tag di 16 byte che rivela qualsiasi modifica. Il server invia anche due ticket di sessione: la prossima volta il browser potrà riprendere con uno di essi e saltare il certificato.","Per record":"Per record","22 bytes of overhead":"22 byte in più","2, for resuming later":"2, per riprendere più tardi",Visible:"Visibili","IPs, SNI, sizes, timing":"IP, SNI, dimensioni, tempi","2 session tickets":"2 ticket di sessione","for resuming later":"per riprendere più tardi",Closing:"Chiusura","close_notify, then TCP":"close_notify, poi TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Dopo 75 secondi di inattività il server chiude la connessione. Prima invia un avviso close_notify, cifrato come tutto il resto, così il browser sa che i dati sono finiti di proposito e non sono stati troncati da un aggressore. Poi TCP chiude come al solito.",Alert:"Avviso",Why:"Perché","Shows nothing was cut off":"Mostra che nulla è stato troncato","TCP FIN from both sides":"FIN TCP da entrambi i lati","alert: close_notify":"avviso: close_notify",encrypted:"cifrato","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ cifrato)","Encrypted handshake (continued)":"Handshake cifrato (continua)","Encrypted handshake (certificate, verify, Finished)":"Handshake cifrato (certificato, verifica, Finished)","Application Data (inside: close_notify alert)":"Application Data (dentro: avviso close_notify)","Alert: close_notify (the data ends here, on purpose)":"Avviso: close_notify (i dati finiscono qui, di proposito)"},l={"Two-way web messaging":"Messaggi web bidirezionali","Browser video calls":"Videochiamate nel browser","HTTP/3 over UDP":"HTTP/3 su UDP","Routing between networks":"Instradamento tra reti","Address setup, neighbour discovery":"Indirizzi e scoperta dei vicini","Private DNS lookups":"Ricerche DNS private","Signed DNS answers":"Risposte DNS firmate","Network Time Protocol":"Network Time Protocol","Joining a network (WPA2)":"Accesso a una rete (WPA2)","Wi-Fi Protected Access 3":"Wi-Fi Protected Access 3","802.1X Enterprise Wi-Fi":"Wi-Fi aziendale 802.1X","Hotel and café Wi-Fi logins":"Accesso al Wi-Fi di hotel e bar","Windows file sharing":"Condivisione file di Windows","Forward proxy and CONNECT":"Proxy diretto e CONNECT","Socket Secure proxy":"Proxy Socket Secure","TLS offloading":"Scarico del TLS","A modern VPN":"Una VPN moderna","IKEv2 and ESP":"IKEv2 ed ESP","Industrial control (OT)":"Controllo industriale (OT)",Proxy:"Proxy","App Server":"Server applicativo","File Server":"File server","ISP Router":"Router del provider","Transit Router":"Router di transito","Hosting Router":"Router dell’hosting","Their Router":"Router dell’altro","Their Laptop":"Portatile dell’altro",Transit:"Transito",Hosting:"Hosting","The router itself.":"Il router stesso.","Mail in Sync":"Posta sincronizzata","Live Updates":"Aggiornamenti in tempo reale","From the browser":"Dal browser","From the server":"Dal server","The WebSocket Protocol":"The WebSocket Protocol","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"Un WebSocket tiene aperta una connessione tra una pagina web e un server, così ciascun lato può inviare un messaggio in qualsiasi momento: chat, risultati in diretta, giochi, documenti condivisi. Inizia come una normale richiesta HTTP che chiede un upgrade; dopo, i messaggi viaggiano in piccoli frame con un’intestazione di pochi byte.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Una richiesta HTTP (Upgrade)","Frames both ways, any time":"Frame in entrambe le direzioni, in qualsiasi momento","Frame header":"Intestazione del frame","2–14 bytes":"2–14 byte","One request, then messages":"Una richiesta, poi messaggi","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Una sola richiesta HTTP ha trasformato una normale connessione TCP in un canale bidirezionale. Da lì in poi ogni messaggio è costato pochi byte di intestazione, e il server poteva scrivere ogni volta che aveva qualcosa da dire. Premi RIVEDI per guardarlo di nuovo.","GET with Upgrade, then 101":"GET con Upgrade, poi 101","Smallest frame":"Frame più piccolo","2 bytes (a ping)":"2 byte (un ping)","Server push":"Invio dal server","Any time, unasked":"In qualsiasi momento, senza richiesta","Real sites":"Siti reali","wss:// (inside TLS)":"wss:// (dentro TLS)","TCP to the server, as for HTTP":"TCP verso il server, come per HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'La pagina della chat è già aperta, caricata da www.example.com. Il suo script chiama new WebSocket("ws://www.example.com/chat") e il browser parte con una normale connessione TCP verso la porta 80. (I siti reali usano wss://, la stessa cosa dentro TLS; il semplice ws:// permette di leggere ogni byte.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Chiedi l’upgrade","An HTTP request with Upgrade: websocket":"Una richiesta HTTP con Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"Il browser invia un GET HTTP con Upgrade: websocket e Connection: Upgrade. Sec-WebSocket-Key è fatto di 16 byte casuali scritti in base64, a cui il server deve rispondere correttamente. Il browser offre anche di comprimere i messaggi (permessage-deflate).","Asks for":"Chiede","16 random bytes, base64":"16 byte casuali, base64",UPGRADE:"UPGRADE","Switch Protocols":"Cambio di protocollo","101: from now on, WebSocket":"101: d’ora in poi, WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"Il server risponde 101 Switching Protocols. Il suo Sec-WebSocket-Accept è la chiave con aggiunta una stringa fissa, passata in SHA-1 e scritta in base64: la prova che ha capito la richiesta. Non ha accettato la compressione, quindi i messaggi viaggiano come testo semplice. HTTP è finito su questa connessione; d’ora in poi entrambi i lati inviano frame WebSocket.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 della chiave + una stringa fissa",Compression:"Compressione","Offered, not taken":"Offerta, non accettata","NOW A WEBSOCKET":"ORA È UN WEBSOCKET","Small frames, from either side":"Frame piccoli, da entrambi i lati",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Invii "Hello": un’intestazione di 2 byte, una chiave di mascheramento di 4 byte e i 5 byte mascherati, 11 byte in tutto invece di un’intera richiesta HTTP. Pochi secondi dopo il server invia il messaggio di Bob senza che nessuno lo chieda: la connessione è ancora aperta, quindi può farlo. I frame dal browser sono sempre mascherati; quelli dal server mai.',"You send":"Tu invii","Server pushes":"Il server invia",'"bob: hi there"':'"bob: hi there"',Masked:"Mascherati","From the browser only":"Solo dal browser",TEXT:"TESTO",masked:"mascherato",unasked:"senza richiesta","Keeping It Alive":"Tenerla viva","Ping and pong":"Ping e pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Dopo mezzo minuto senza niente da dire, il server invia un ping, così router e firewall lungo la strada non si dimenticano della connessione silenziosa. Il browser risponde da solo con un pong; lo script della pagina non vede né l’uno né l’altro.","Opcode 9, from either side":"Opcode 9, da entrambi i lati",Pong:"Pong","Opcode 10, by itself":"Opcode 10, da solo","How often":"Ogni quanto","Up to the server (30 s)":"Lo decide il server (30 s)","A close frame each way":"Un frame di chiusura per verso","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Quando lasci la chat, lo script della pagina chiude il WebSocket con lo stato 1000 (chiusura normale): il browser invia un frame di chiusura e il server risponde con il suo. Poi il server chiude la connessione TCP. (Chiudere semplicemente la scheda invierebbe 1001, uscita.)",Opcode:"Opcode","8 (close)":"8 (chiusura)","1000 (normal closure)":"1000 (chiusura normale)","TCP closes":"TCP chiude",CLOSE:"CHIUSURA","1000 normal closure":"1000 chiusura normale","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: questo frame è un messaggio intero. L’opcode dice cosa trasporta.","Mask, length":"Maschera, lunghezza","Everything a browser sends is masked.":"Tutto ciò che un browser invia è mascherato.","Masking key":"Chiave di mascheramento","Chosen at random for every frame.":"Scelta a caso per ogni frame.",Payload:"Payload","Each byte XORed with the masking key in turn; the server XORs it back.":"Ogni byte in XOR con la chiave di mascheramento a turno; il server fa di nuovo lo XOR.","A server never masks what it sends.":"Un server non maschera mai ciò che invia.","Status code":"Codice di stato","Joining a Network":"Entrare in una rete","From the access point":"Dall’access point","4-way handshake":"Handshake a 4 vie","Access Point":"Access point","Wi-Fi (802.11) with WPA2":"Wi-Fi (802.11) con WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Il Wi-Fi trasporta una rete via radio. Prima di poter inviare qualcosa, un dispositivo deve trovare la rete, entrarci e dimostrare di conoscere la password. Con WPA2-Personal questa prova è l’handshake a 4 vie: quattro brevi messaggi che trasformano la password in nuove chiavi di cifratura, senza che la password viaggi mai via radio.","Data Link (Layer 2)":"Collegamento dati (livello 2)",Standard:"Standard",Joining:"Ingresso","Probe, authenticate, associate":"Probe, autenticazione, associazione","Keys from":"Chiavi da","The 4-way handshake":"L’handshake a 4 vie",Connected:"Connesso","Eleven frames to a secure link":"Undici frame per un collegamento sicuro","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"Il portatile ha trovato la rete, ci è entrato con due formalità e ha dimostrato di conoscere la password in un handshake di quattro messaggi, senza mai inviarla. Tutto ciò che è venuto dopo è stato cifrato con chiavi create solo per questa connessione. Premi RIVEDI per guardarlo di nuovo.","Frames to join":"Frame per entrare","Password sent":"Password inviata",Never:"Mai","Session keys":"Chiavi di sessione","New every time":"Nuove ogni volta",Next:"Poi","DHCP, for an IP address":"DHCP, per un indirizzo IP","Find the Network":"Trova la rete","A beacon, then a probe":"Un beacon, poi una probe",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Circa dieci volte al secondo il Wi-Fi del router invia un beacon: ecco "HomeNet", protetta con WPA2, sul canale 36. Il portatile potrebbe semplicemente aspettare di sentirne uno; per fare prima chiede anche ad alta voce con una probe request, e l’access point risponde con una probe response.',"WPA2-Personal (password)":"WPA2-Personal (password)",BEACON:"BEACON","WPA2 · channel 36":"WPA2 · canale 36",PROBE:"PROBE","any networks here?":"ci sono reti qui?","PROBE RESPONSE":"PROBE RESPONSE","Join the Network":"Entra nella rete","Two formalities: hello, then join":"Due formalità: ciao, poi l’ingresso","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"L’autenticazione Open System fa arrivare chiunque fin qui: ancora nessuna password. Poi il portatile chiede di associarsi, ripetendo la sicurezza scelta (CCMP, con password), e l’access point gli dà l’ID di associazione 1. Il portatile è connesso, ma l’unica cosa che può inviare è l’handshake che segue.",Authentication:"Autenticazione","Open System (no password)":"Open System (senza password)","Association ID":"ID di associazione","Allowed so far":"Consentito finora",success:"successo",ASSOCIATE:"ASSOCIAZIONE",'join "HomeNet"':'entra in "HomeNet"',"CCMP, password":"CCMP, password",ASSOCIATED:"ASSOCIATO","association ID 1":"ID di associazione 1","Messages 1 and 2":"Messaggi 1 e 2","The 4-way handshake: nonces":"L’handshake a 4 vie: i nonce","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Entrambi i lati hanno già la stessa chiave, ricavata dalla password e dal nome della rete (la PMK); non viaggia mai via radio. L’access point invia un numero casuale, l’ANonce. Il portatile invia il suo, l’SNonce, con un valore di controllo (MIC). Dalla PMK, dai due nonce e da entrambi gli indirizzi MAC, ogni lato ricava ora le stesse chiavi di sessione.","Shared key":"Chiave condivisa","PMK, from the password":"PMK, dalla password",Exchanged:"Scambiati","Two random nonces":"Due nonce casuali","Worked out":"Ricavate","Session keys (PTK)":"Chiavi di sessione (PTK)","MESSAGE 1":"MESSAGGIO 1","MESSAGE 2":"MESSAGGIO 2","Messages 3 and 4":"Messaggi 3 e 4","The 4-way handshake: keys":"L’handshake a 4 vie: le chiavi","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Il messaggio 3 mostra che l’access point ha le stesse chiavi (il suo MIC torna) e porta la chiave di gruppo (GTK) per i broadcast, cifrata. Il messaggio 4 dice che il portatile è pronto, ed entrambi gli estremi iniziano a cifrare.","Group key":"Chiave di gruppo","GTK, sent encrypted":"GTK, inviata cifrata",Install:"Installazione","Both ends at once":"Entrambi gli estremi insieme","MESSAGE 3":"MESSAGGIO 3","group key, encrypted":"chiave di gruppo, cifrata","MESSAGE 4":"MESSAGGIO 4","keys installed":"chiavi installate","Encrypted Now":"Ora è cifrato","And what a listener could still do":"E cosa potrebbe ancora fare chi ascolta","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Ora ogni frame di dati è cifrato, come questo primo che porta un DHCP Discover: chi è vicino vede solo gli indirizzi MAC e la dimensione. Ma chi ha registrato i quattro messaggi dell’handshake può provare a indovinare la password a casa, alla velocità che il suo computer consente: un tentativo è giusto quando dà lo stesso MIC. Una password lunga e casuale rende la cosa impossibile; WPA3 elimina il punto debole.","Others see":"Gli altri vedono","MAC addresses, sizes, timing":"Indirizzi MAC, dimensioni, tempi","Weak point":"Punto debole","Offline password guessing":"Tentativi offline di indovinare la password",Defence:"Difesa","A long password, or WPA3":"Una password lunga, o WPA3","DHCP Discover inside":"Dentro, un DHCP Discover","ENCRYPTED FROM HERE ON":"CIFRATO DA QUI IN POI","QoS Data (encrypted)":"QoS Data (cifrato)","Seen over the air, on Wi-Fi channel 36":"Visto via radio, sul canale Wi-Fi 36","Frame type":"Tipo di frame","Management, Beacon":"Gestione, Beacon",Duration:"Durata","Nobody acknowledges a broadcast, so nothing is booked.":"Nessuno conferma un broadcast, quindi non si prenota nulla.",Receiver:"Ricevitore","Broadcast: every device in range listens.":"Broadcast: ascolta ogni dispositivo nel raggio.",Transmitter:"Trasmettitore","The access point.":"L’access point.","The access point’s own address: which network this is about.":"L’indirizzo dell’access point stesso: di quale rete si tratta.","Lets the receiver spot a repeat when a frame is sent again.":"Permette al ricevitore di riconoscere una ripetizione quando un frame viene rinviato.","The access point’s clock; devices on the network keep theirs in step with it.":"L’orologio dell’access point; i dispositivi della rete tengono il loro allineato con esso.","Beacon interval":"Intervallo dei beacon","A beacon goes out about ten times a second.":"Un beacon parte circa dieci volte al secondo.","0x0011: access point network, encrypted":"0x0011: rete con access point, cifrata","Privacy bit set: joining takes a key.":"Bit di privacy attivo: per entrare serve una chiave.","The network’s name.":"Il nome della rete.","Supported rates":"Velocità supportate","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Solo le velocità più vecchie e lente; quelle veloci sono negli elementi che seguono.","DTIM count 0, period 1":"Conteggio DTIM 0, periodo 1","Tells sleeping devices whether frames are waiting for them.":"Dice ai dispositivi addormentati se ci sono frame in attesa per loro.","Robust Security Network: how this network is protected.":"Robust Security Network: come è protetta questa rete.","Element ID, length":"ID elemento, lunghezza","48, 20 bytes":"48, 20 byte","Group cipher":"Cifrario di gruppo","Encrypts broadcasts, which every device on the network can read.":"Cifra i broadcast, che ogni dispositivo della rete può leggere.","Pairwise cipher":"Cifrario a coppie","Encrypts each device’s own traffic, with keys only it and the access point have.":"Cifra il traffico di ciascun dispositivo, con chiavi che hanno solo lui e l’access point.","Key management":"Gestione delle chiavi","1: PSK (a shared password)":"1: PSK (una password condivisa)","More elements":"Altri elementi","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Funzionalità e impostazioni Wi-Fi 4, 5 e 6 (HT, VHT, HE: canale 36, largo 80 MHz) ed extra del produttore.","Management, Probe Request":"Gestione, Probe Request","The laptop’s Wi-Fi card.":"La scheda Wi-Fi del portatile.","empty (any network)":"vuoto (qualsiasi rete)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"Può rispondere qualsiasi access point. (Un tempo i dispositivi chiedevano per nome ogni rete a cui si erano collegati, dicendo a chiunque ascoltasse dove erano stati.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Cosa sa fare la radio del portatile: funzionalità Wi-Fi 4, 5 e 6 ed extra del produttore.","Management, Probe Response":"Gestione, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Per quanto tempo il canale resta prenotato per questo scambio; gli altri dispositivi aspettano.","The radio this frame is for.":"La radio a cui è destinato questo frame.","Authentication · Open System":"Autenticazione · Open System","Management, Authentication":"Gestione, Authentication",Algorithm:"Algoritmo","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Open: chiunque può arrivare fin qui. La password viene verificata dopo, nell’handshake a 4 vie.",Transaction:"Transazione","0 (success)":"0 (successo)","Management, Association Request":"Gestione, Association Request","Listen interval":"Intervallo di ascolto","10 beacons":"10 beacon","How often the laptop wakes to check for waiting frames when saving power.":"Ogni quanto il portatile si sveglia per controllare i frame in attesa quando risparmia energia.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Cosa sa fare la radio del portatile (Wi-Fi 4, 5 e 6) ed extra del produttore.","Management, Association Response":"Gestione, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Il numero del portatile su questo access point (i due bit più alti sono sempre attivi).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"Le impostazioni usate dall’access point (Wi-Fi 4, 5 e 6) ed extra del produttore.","Data, QoS Data":"Dati, QoS Data","0x02 (from the access point)":"0x02 (dall’access point)","Sent by the access point itself.":"Inviato dall’access point stesso.","QoS control":"Controllo QoS","Priority 7, the highest: the handshake goes first.":"Priorità 7, la più alta: l’handshake passa per primo.",Organization:"Organizzazione","0x888e (802.1X authentication)":"0x888e (autenticazione 802.1X)","What follows: plays the part an Ethernet type field does on a cable.":"Cosa segue: fa la parte che su un cavo fa il campo tipo di Ethernet.","Descriptor type":"Tipo di descrittore","Key information":"Informazioni sulla chiave","0x008a: pairwise, ACK":"0x008a: a coppie, ACK","ACK: the laptop must answer.":"ACK: il portatile deve rispondere.","Key length":"Lunghezza della chiave","The pairwise key is 16 bytes (AES-128).":"La chiave a coppie è di 16 byte (AES-128).","Replay counter":"Contatore anti-replay","Counts up with each message from the access point; an old one sent again is ignored.":"Aumenta a ogni messaggio dell’access point; uno vecchio rinviato viene ignorato.","A random number from the access point.":"Un numero casuale dall’access point.","Key IV":"IV della chiave",zeros:"zeri","Key RSC":"RSC della chiave","No keys yet, so nothing to check with.":"Ancora nessuna chiave, quindi niente con cui verificare.","Key data length":"Lunghezza dei dati della chiave","0x01 (to the access point)":"0x01 (verso l’access point)","The access point itself.":"L’access point stesso.","0x010a: pairwise, MIC":"0x010a: a coppie, MIC","MIC: this message carries a check value.":"MIC: questo messaggio porta un valore di controllo.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Un numero casuale dal portatile. Da entrambi i numeri, da entrambi gli indirizzi MAC e dalla chiave che deriva dalla password, ogni lato ricava le stesse chiavi di sessione.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Calcolato con le nuove chiavi: dimostra che il mittente conosce la password e che il messaggio non è stato modificato.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: a coppie, installa, ACK, MIC, sicuro, dati della chiave cifrati","Install: start using the keys. The group key comes encrypted.":"Installa: inizia a usare le chiavi. La chiave di gruppo arriva cifrata.","Where the group key’s packet numbers start.":"Da dove partono i numeri di pacchetto della chiave di gruppo.","Key data":"Dati della chiave","Encrypted with a key from the handshake.":"Cifrati con una chiave dell’handshake.","The access point’s RSN element":"L’elemento RSN dell’access point","GTK: the group key, for broadcasts":"GTK: la chiave di gruppo, per i broadcast","0x030a: pairwise, MIC, secure":"0x030a: a coppie, MIC, sicuro","Secure: the keys are in place.":"Sicuro: le chiavi sono al loro posto.","CCMP · encrypted":"CCMP · cifrato","0x41 (protected, to the access point)":"0x41 (protetto, verso l’access point)","Protected: what follows the header is encrypted.":"Protetto: ciò che segue l’intestazione è cifrato.","Where the access point should pass it on to: everyone on the network.":"A chi l’access point deve passarlo: a tutti sulla rete.","CCMP header":"Intestazione CCMP","packet number 1, key 0":"numero di pacchetto 1, chiave 0","Counts up with every frame; one seen before is thrown away.":"Aumenta a ogni frame; uno già visto viene scartato.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: un pacchetto IPv4","Shows any change to the frame.":"Rivela qualsiasi modifica al frame.","Safer Wi-Fi":"Wi-Fi più sicuro","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 è lo standard attuale di sicurezza Wi-Fi. La sua modalità Personal mantiene la semplice password condivisa ma cambia il modo in cui viene verificata: SAE, uno scambio di password che nessuna registrazione può attaccare offline, dà a ogni connessione una chiave nuova. Rende anche obbligatori i frame di gestione protetti.","Password check":"Verifica della password",Required:"Obbligatori","Protected management frames":"Frame di gestione protetti",Since:"Dal","Connected with WPA3":"Connesso con WPA3","Same password, better protocol":"Stessa password, protocollo migliore","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"Il portatile e l’access point si sono dimostrati a vicenda di conoscere la password senza dare a nessuno modo di provare tentativi offline, poi hanno creato nuove chiavi esattamente come fa WPA2. Premi RIVEDI per guardarlo di nuovo.","SAE frames":"Frame SAE","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 frame EAPOL-Key","Offline guessing":"Tentativi offline","Not possible":"Impossibili","Forged disconnects":"Disconnessioni falsificate",Ignored:"Ignorate","A WPA3 Network":"Una rete WPA3","The beacon asks for SAE":"Il beacon chiede SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"Il beacon assomiglia a quello di WPA2 con due differenze nel suo elemento RSN: la gestione delle chiavi è SAE invece di PSK, e i frame di gestione protetti sono obbligatori. Tutti usano ancora un’unica password condivisa.","Management frames":"Frame di gestione","Protected (required)":"Protetti (obbligatorio)","Still one for everyone":"Sempre una per tutti","SAE Commit":"SAE Commit","Each side commits to the password":"Ogni lato si impegna sulla password","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"Al posto dell’autenticazione Open System, i due lati eseguono SAE, uno scambio di password alla pari. Ciascuno sceglie un segreto casuale e invia uno scalare e un elemento ricavati da quel segreto e dalla password. La password è la stessa da entrambi i lati, i segreti no, quindi ogni connessione finisce con una chiave nuova.","19 (256-bit curve)":"19 (curva a 256 bit)","Each sends":"Ciascuno invia","A scalar and an element":"Uno scalare e un elemento",Replaces:"Sostituisce","Open System authentication":"L’autenticazione Open System",COMMIT:"COMMIT","scalar + element":"scalare + elemento","SAE Confirm":"SAE Confirm","Proof, without the password":"Una prova, senza la password","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Ora ogni lato ricava la chiave condivisa e invia un confirm, un valore che solo chi ha la password giusta potrebbe produrre. Registrare tutti e quattro i frame SAE non permette a un aggressore di provare tentativi a casa: ogni tentativo richiede uno scambio dal vivo con l’access point, che può rallentarlo o escluderlo.","A new key (PMK) each time":"Una chiave nuova (PMK) ogni volta",Guessing:"Tentativi","Live only, never offline":"Solo dal vivo, mai offline","Password leaks":"Fuga della password","Past traffic stays safe":"Il traffico passato resta al sicuro",CONFIRM:"CONFIRM","proof of the key":"prova della chiave","Join, Handshake":"Ingresso, handshake","Then the 4-way handshake, as in WPA2":"Poi l’handshake a 4 vie, come in WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"L’associazione funziona come prima, ripetendo la scelta di SAE. L’handshake a 4 vie che segue è quello di WPA2, a partire dalla chiave appena creata da SAE, tranne che il messaggio 3 porta anche l’IGTK, una chiave che firma i frame di gestione in broadcast.","Message 3 adds":"Il messaggio 3 aggiunge","Why It’s Safer":"Perché è più sicuro","Forged disconnects stop working":"Le disconnessioni falsificate smettono di funzionare","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Con WPA2 chiunque nel raggio poteva falsificare un frame di «disconnessione» e buttare fuori un dispositivo dalla rete, spesso per registrarne l’handshake quando rientrava. WPA3 richiede frame di gestione protetti, quindi le disconnessioni falsificate vengono ignorate. Molti router offrono anche una modalità di transizione che fa entrare pure i dispositivi WPA2; quei dispositivi mantengono i punti deboli di WPA2.",Protected:"Protetti","Disconnects, other management":"Disconnessioni, altra gestione","WPA2/3 mode":"Modalità WPA2/3","WPA2 devices stay at risk":"I dispositivi WPA2 restano a rischio","Stronger still":"Ancora più forte","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 bit)","MANAGEMENT FRAMES PROTECTED":"FRAME DI GESTIONE PROTETTI","0x00c0: management frame protection required":"0x00c0: protezione dei frame di gestione obbligatoria","Disconnect messages and other management frames are signed, so they can’t be forged.":"I messaggi di disconnessione e gli altri frame di gestione sono firmati, quindi non si possono falsificare.","Authentication · SAE Commit":"Autenticazione · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: lo scambio di password di WPA3.","19 (256-bit elliptic curve)":"19 (curva ellittica a 256 bit)",Scalar:"Scalare","Worked out from a random secret and the password.":"Ricavato da un segreto casuale e dalla password.",Element:"Elemento","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Un punto sulla curva, anch’esso legato alla password. Registrare scalare ed elemento non permette a nessuno di provare in seguito tentativi di password.","Authentication · SAE Confirm":"Autenticazione · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Dimostra che questo lato ha ricavato la stessa chiave, senza rivelarla.","0x0088: pairwise, ACK":"0x0088: a coppie, ACK","0x0108: pairwise, MIC":"0x0108: a coppie, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: a coppie, installa, ACK, MIC, sicuro, dati della chiave cifrati","IGTK: the key that signs broadcast management frames":"IGTK: la chiave che firma i frame di gestione in broadcast","0x0308: pairwise, MIC, secure":"0x0308: a coppie, MIC, sicuro","Sign-In":"Accesso","From the router":"Dal router","From the test server":"Dal server di test","Hotel Router":"Router dell’hotel","192.168.1.1 · captive portal":"192.168.1.1 · portale captive","Wi-Fi login pages":"Pagine di accesso al Wi-Fi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Hotel, bar, aeroporti e treni mettono spesso una pagina di accesso davanti al loro Wi-Fi. Finché non accetti le condizioni (o paghi), il router non lascia uscire nulla verso Internet. Intercetta la prima richiesta HTTP in chiaro del tuo dispositivo e risponde con un reindirizzamento alla propria pagina; il tuo dispositivo se ne accorge perché una pagina di test che conosce torna sbagliata.",Where:"Dove","Hotels, cafés, airports":"Hotel, bar, aeroporti",How:"Come","Catches plain HTTP requests":"Intercetta le richieste HTTP in chiaro","Noticed by":"Rilevato da","Your system’s test page":"La pagina di test del sistema","Logging in":"Accesso","Lets your MAC address through":"Fa passare il tuo indirizzo MAC","Newer way":"Metodo più recente","DHCP option 114 (RFC 8910)":"Opzione DHCP 114 (RFC 8910)","Described In":"Descritto in",Online:"Online","Noticed, logged in, let through":"Rilevato, accesso fatto, via libera","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows ha chiesto a una pagina di test una risposta che conosce e ha ricevuto invece un reindirizzamento, quindi ha capito che c’era un portale di mezzo e ha aperto la pagina di accesso. Una volta accettate le condizioni, il router ha fatto passare il portatile e lo stesso controllo è tornato giusto. Premi RIVEDI per guardarlo di nuovo.","A plain HTTP test page":"Una pagina di test HTTP in chiaro","Faked by":"Falsificata da","The router (TTL 64)":"Il router (TTL 64)","Let through":"Fatto passare","The laptop’s MAC address":"L’indirizzo MAC del portatile","Open Wi-Fi":"Wi-Fi aperto","Use HTTPS, or a VPN":"Usa HTTPS, o una VPN","Joined, Offline":"Connesso, ma offline","An address, but no way out":"Un indirizzo, ma nessuna uscita","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"Il portatile è entrato nel Wi-Fi dell’hotel, che non ha password, e ha ottenuto un indirizzo dal router via DHCP. Il router risponde al portatile e inoltra le sue ricerche DNS, ma scarta tutto il resto diretto a Internet finché l’ospite non ha effettuato l’accesso. (Una rete aperta significa anche che chiunque nei paraggi può leggere ciò che non è protetto da HTTPS.)","192.168.1.10 (by DHCP)":"192.168.1.10 (via DHCP)","Wi-Fi password":"Password Wi-Fi","None (open network)":"Nessuna (rete aperta)","Blocked until you log in":"Bloccato fino all’accesso","CONNECTED, NO INTERNET YET":"CONNESSO, ANCORA SENZA INTERNET","Internet Check":"Controllo di Internet","Windows checks a test page":"Windows controlla una pagina di test",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Dopo essere entrato in qualsiasi rete, Windows cerca www.msftconnecttest.com (il router inoltra la ricerca) e gli chiede /connecttest.txt in HTTP in chiaro; la risposta giusta è il testo "Microsoft Connect Test". Il router intercetta la connessione e risponde da sé all’handshake, a nome del server di test. Il portatile per ora non se ne accorge.',"Test page":"Pagina di test","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Atteso","Answered by":"Risponde","The router, posing as the server":"Il router, fingendosi il server",'from "203.0.113.30"':'da "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Reindirizzato","The wrong answer gives it away":"La risposta sbagliata lo tradisce",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':"Invece del testo di test, il «server» risponde 302 Found, indicando la pagina di accesso del router. Il suo TTL è 64, per niente abbassato, perché arriva direttamente dal router. Windows vede la risposta sbagliata, segna la rete come «richiede un’azione» e apre il browser, la cui prima richiesta viene reindirizzata allo stesso modo, verso la pagina di accesso. Funziona solo con HTTP in chiaro: il router non può falsificare una pagina HTTPS senza un errore di certificato.","302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Indizio","TTL 64, from one hop away":"TTL 64, da un solo salto","Why HTTP":"Perché HTTP","HTTPS can’t be faked":"HTTPS non si può falsificare","302 FOUND":"302 FOUND","ACTION NEEDED":"SERVE UN’AZIONE","The Login Page":"La pagina di accesso","Served by the router itself":"Servita dal router stesso","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"Il browser apre http://192.168.1.1/login, una pagina servita dal router stesso: il nome dell’hotel, le condizioni d’uso e un pulsante Accetta. Questa connessione va davvero al router.",Page:"Pagina","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Servita da","The router":"Il router",Size:"Dimensione","2,400 bytes of HTML":"2,400 byte di HTML","/login":"/login","the login page":"la pagina di accesso","Accept the Terms":"Accetta le condizioni","The router lets the laptop out":"Il router fa uscire il portatile","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Cliccare Accetta invia un piccolo modulo al router. Questo aggiunge l’indirizzo MAC del portatile all’elenco dei dispositivi che possono uscire, spesso per tutta la durata del soggiorno, e rimanda il browser dove stava andando.",Form:"Modulo","terms=accepted":"terms=accepted","Router allows":"Il router consente","302 to where you were going":"302 verso dove stavi andando","you’re online":"sei online","MAC ADDRESS ALLOWED":"INDIRIZZO MAC CONSENTITO","The same check, now real":"Lo stesso controllo, ora vero","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows controlla di nuovo. Stavolta il router fa passare la connessione fino al vero server di test, a dodici router di distanza (le sue risposte arrivano con TTL 52), e la risposta è il testo atteso. La rete viene segnata come connessa a Internet.","Connected to the internet":"Connesso a Internet",ONLINE:"ONLINE","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, tipo A, classe IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Inviato con 64 e per niente abbassato: arriva dal router accanto, non da un server a 12 router di distanza.","2,400 bytes: the login page":"2,400 byte: la pagina di accesso","Via a Proxy":"Tramite un proxy","TLS, through the tunnel":"TLS, attraverso il tunnel","Forward proxy, and CONNECT for HTTPS":"Proxy diretto, e CONNECT per HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Un proxy diretto scarica le pagine web al posto tuo. Aziende e scuole lo usano per filtrare siti, tenere copie delle pagine più visitate e registrare ciò che esce; i siti che visiti vedono il proxy, non te. L’HTTP in chiaro lo attraversa leggibile. Per HTTPS il browser chiede al proxy un tunnel, e la connessione cifrata lo attraversa senza essere letta.","Common ports":"Porte comuni","http:// pages":"Pagine http://","Fetched by the proxy":"Scaricate dal proxy","https:// pages":"Pagine https://","Tunnelled with CONNECT":"In tunnel con CONNECT","Used for":"Usato per","Filtering, caching, logging":"Filtrare, mettere in cache, registrare","Two ways through":"Due modi per passare","Fetched for you, or tunnelled":"Scaricato per te, o in tunnel","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Per la pagina in chiaro il lavoro l’ha fatto il proxy: ha letto la richiesta, ha scaricato la pagina con una sua connessione e avrebbe potuto conservarla, modificarla o rifiutarla. Per HTTPS ha solo aperto un tunnel e copiato byte cifrati, senza sapere nulla oltre al nome del sito. Premi RIVEDI per guardarlo di nuovo.","Server sees":"Il server vede","The proxy (192.0.2.80)":"Il proxy (192.0.2.80)","Plain HTTP":"HTTP in chiaro","The proxy reads it all":"Il proxy legge tutto","Name and sizes only":"Solo nome e dimensioni","DNS for the site":"DNS per il sito","Done by the proxy":"Fatto dal proxy","Proxy Settings":"Impostazioni del proxy","The browser sends everything there":"Il browser manda tutto lì","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"Il browser è impostato per mandare tutto attraverso un proxy a 192.0.2.80, porta 8080, come richiedono molte aziende e scuole. Apri http://www.example.com. Il browser non cerca da sé www.example.com: si collega al proxy e lascia a lui il resto.","Left to the proxy":"Lasciato al proxy","To the Proxy":"Verso il proxy","TCP to port 8080":"TCP verso la porta 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"Il portatile apre una normale connessione TCP, non verso il sito web, ma verso la porta 8080 del proxy.","192.0.2.80, port 8080":"192.0.2.80, porta 8080","Not to":"Non verso","The Whole URL":"L’URL intero","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"Inviata a un proxy, la riga di richiesta porta l’indirizzo intero, non solo il percorso: GET http://www.example.com/ HTTP/1.1. È così che il proxy sa dove andare. Chrome aggiunge Proxy-Connection: keep-alive, un’intestazione che leggono solo i proxy.","Request line":"Riga di richiesta","To a server":"A un server","Readable by":"Leggibile da","The proxy (plain HTTP)":"Il proxy (HTTP in chiaro)","to the proxy":"al proxy","Proxy Fetches It":"Il proxy la scarica","Its own connection to the server":"Una sua connessione verso il server","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"Il proxy cerca da sé www.example.com (non mostrato) e apre una sua connessione verso il server. La sua richiesta è di quelle normali, GET /, con intestazioni proprie: Via nomina il proxy e X-Forwarded-For indica l’indirizzo da cui è partita la richiesta (l’indirizzo pubblico del router di casa, visto che il portatile è dietro NAT).","The proxy’s own":"Quella del proxy","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Inoltrato per","Page Passed On":"Pagina passata avanti","The page, passed on":"La pagina, passata avanti","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"Il server risponde al proxy, e il proxy passa la pagina al portatile con una sua intestazione Via. Potrebbe tenerne una copia e darla al prossimo che la chiede senza disturbare il server (X-Cache: MISS dice che non ne aveva ancora), e può rifiutare i siti non consentiti.","The proxy, not the laptop":"Il proxy, non il portatile",Cache:"Cache","MISS (first request)":"MISS (prima richiesta)","Proxy can":"Il proxy può","Cache, filter, log, change":"Mettere in cache, filtrare, registrare, modificare","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Ora apri https://www.example.com. Un proxy non può scaricare una pagina HTTPS per te senza romperne la cifratura, quindi il browser chiede invece un tunnel: CONNECT www.example.com:443. Il proxy apre una connessione TCP verso la porta 443 e risponde 200 Connection established.","Proxy opens":"Il proxy apre","TCP to port 443":"TCP verso la porta 443","200 Connection established":"200 Connection established","Connection established":"Connessione stabilita","In the Tunnel":"Nel tunnel","The proxy copies, unread":"Il proxy copia, senza leggere","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"D’ora in poi il proxy copia byte in entrambe le direzioni senza leggerli. Il TLS Client Hello del browser entra dalla connessione del portatile ed esce, identico byte per byte, dalla connessione del proxy verso il server. TLS va da un capo all’altro, quindi il proxy viene a sapere il nome del sito e le dimensioni, mai le pagine. (Alcuni proxy aziendali aprono comunque HTTPS, usando un’autorità di certificazione installata su ogni portatile aziendale; allora vedono tutto.)","Proxy sees":"Il proxy vede","Site name, sizes, timing":"Nome del sito, dimensioni, tempi","Hidden from it":"Nascosto al proxy","Pages, passwords, cookies":"Pagine, password, cookie","TLS, laptop to server":"TLS, dal portatile al server","the same bytes":"gli stessi byte","COPIES BYTES, CAN’T READ THEM":"COPIA I BYTE, NON PUÒ LEGGERLI","Any Connection":"Qualsiasi connessione","From the proxy":"Dal proxy","SOCKS Proxy":"Proxy SOCKS","Socket Secure, version 5":"Socket Secure, versione 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS è un proxy generico. Mentre un proxy HTTP capisce le richieste web, un proxy SOCKS si limita ad aprire una connessione al posto tuo e a copiarne i byte, qualunque sia il protocollo: web, posta, giochi, SSH. Le app lo usano per raggiungere una rete attraverso un unico gateway, o per nascondere il proprio indirizzo; ssh -D e Tor ne offrono uno.","Session (Layer 5)":"Sessione (livello 5)","Any TCP, and UDP":"Qualsiasi TCP, e UDP",Logins:"Accesso","None, or user and password":"Nessuno, o utente e password","Offered by":"Offerto da","ssh -D, Tor, proxy servers":"ssh -D, Tor, server proxy","Tunnel open":"Tunnel aperto","A few bytes, then just copying":"Pochi byte, poi solo copia","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Quattro minuscoli messaggi hanno detto al proxy dove collegarsi; poi si è limitato a copiare byte. Il sito web ha visto l’indirizzo del proxy, e poiché il portatile ha inviato un nome invece di un indirizzo, perfino la ricerca DNS è avvenuta sul proxy. Premi RIVEDI per guardarlo di nuovo.","4 messages, 37 bytes":"4 messaggi, 37 byte","DNS lookup":"Ricerca DNS","At the proxy":"Sul proxy","Only the TLS inside":"Solo il TLS all’interno","TCP to port 1080":"TCP verso la porta 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Un’app impostata per usare un proxy SOCKS (un browser, un launcher di giochi o un tunnel creato con ssh -D) apre una connessione TCP verso di esso, porta 1080. A SOCKS non importa cosa viaggerà dentro: può portare qualsiasi connessione TCP.","Any TCP connection":"Qualsiasi connessione TCP","Wants to reach":"Vuole raggiungere","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Versione 5, e come accedere","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"Il portatile invia tre byte: versione 5, un metodo di accesso offerto, e quel metodo, 0: nessun accesso. Il proxy risponde con due: versione 5, metodo 0. Se avesse scelto il metodo 2, l’app avrebbe poi inviato nome utente e password, in chiaro.","Laptop sends":"Il portatile invia","05 01 00 (3 bytes)":"05 01 00 (3 byte)","Proxy answers":"Il proxy risponde","05 00 (2 bytes)":"05 00 (2 byte)","None needed here":"Non serve qui",GREETING:"SALUTO","no login, please":"niente accesso, grazie",METHOD:"METODO","no login needed":"nessun accesso richiesto","Where To?":"Dove?","Connect to www.example.com:443":"Collegati a www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"Il portatile chiede al proxy di collegarsi a www.example.com, porta 443. Dà il nome invece di un indirizzo, quindi la ricerca DNS la fa il proxy e il portatile non ne ha bisogno. Il proxy apre una sua connessione TCP verso il server, poi risponde: riuscito, con l’indirizzo e la porta da cui si è collegato.","www.example.com (a name)":"www.example.com (un nome)","Succeeded, from 192.0.2.80:40220":"Riuscito, da 192.0.2.80:40220",SUCCEEDED:"RIUSCITO","from 192.0.2.80:40220":"da 192.0.2.80:40220","Copied both ways, unread":"Copiato in entrambe le direzioni, senza leggere","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Ora il proxy si limita a copiare. L’app avvia TLS con il server: il suo Client Hello entra dalla connessione del portatile ed esce invariato da quella del proxy, e la risposta del server torna allo stesso modo. Il server vede sempre e solo l’indirizzo del proxy; il proxy vede solo byte cifrati.","The proxy’s address":"L’indirizzo del proxy","Encrypted bytes":"Byte cifrati","Same bytes":"Stessi byte","On both connections":"Su entrambe le connessioni",unchanged:"invariato","+ encrypted handshake":"+ handshake cifrato","Version 5, 1 method: no login":"Versione 5, 1 metodo: nessun accesso","Version 5, method chosen: no login":"Versione 5, metodo scelto: nessun accesso","Succeeded, bound to 192.0.2.80:40220":"Riuscito, legato a 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · saluto","Methods offered":"Metodi offerti","0 (no login)":"0 (nessun accesso)","SOCKS5 · method chosen":"SOCKS5 · metodo scelto","Method chosen":"Metodo scelto","SOCKS5 · connect request":"SOCKS5 · richiesta di connessione","Open a TCP connection on my behalf.":"Apri una connessione TCP al posto mio.","Address type":"Tipo di indirizzo","3 (domain name)":"3 (nome di dominio)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"Il proxy cerca il nome da sé, quindi al portatile non serve una sua ricerca DNS.","SOCKS5 · reply":"SOCKS5 · risposta","0 (succeeded)":"0 (riuscito)","The address the proxy connects from.":"L’indirizzo da cui si collega il proxy.",Offloading:"Scarico","Reverse Proxy":"Reverse proxy","TLS (SSL) offloading":"Scarico di TLS (SSL)","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Un reverse proxy sta davanti ai server di un sito: i visitatori si collegano a lui e lui passa le loro richieste a un server applicativo dietro di sé. Può distribuire il carico su molti server, tenere copie delle pagine e respingere attacchi. Spesso fa anche il lavoro TLS, decifrando l’HTTPS al bordo così che i server dietro parlino HTTP in chiaro. Questo è lo scarico SSL (o TLS).","Visitors reach":"I visitatori raggiungono","The proxy, never the app":"Il proxy, mai l’app","TLS ends":"TLS finisce","At the proxy (offloading)":"Sul proxy (scarico)","Plain HTTP (or TLS again)":"HTTP in chiaro (o di nuovo TLS)",Adds:"Aggiunge","For example":"Per esempio","nginx, HAProxy, cloud LBs":"nginx, HAProxy, bilanciatori cloud","Served from the edge":"Servito dal bordo","Encrypted outside, plain inside":"Cifrato fuori, in chiaro dentro","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"Il portatile ha visto un unico sito HTTPS. Dietro, il reverse proxy ha decifrato la richiesta, l’ha girata a un server applicativo in HTTP in chiaro sulla rete privata e ha cifrato la risposta per il viaggio di ritorno. Premi RIVEDI per guardarlo di nuovo.","Laptop ↔ proxy only":"Solo portatile ↔ proxy","App learns visitor":"L’app conosce il visitatore","From X-Forwarded-For":"Da X-Forwarded-For","Certificate kept":"Certificato custodito","On the proxy":"Sul proxy","The Front Door":"La porta d’ingresso","The proxy holds the certificate":"Il proxy custodisce il certificato","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"Il portatile apre https://www.example.com. L’indirizzo che il DNS dà per quel nome appartiene al reverse proxy, che custodisce il certificato del sito e fa l’handshake TLS. Nulla dice al portatile che dietro c’è un altro server.","Laptop connects to":"Il portatile si collega a","On the reverse proxy":"Sul reverse proxy","Also called":"Chiamato anche","Load balancer, edge":"Bilanciatore di carico, edge","TLS Ends Here":"Qui finisce TLS","Offloading: the proxy does the TLS work":"Scarico: il lavoro TLS lo fa il proxy","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"La richiesta arriva cifrata e il reverse proxy la decifra. Questo è lo scarico: il lavoro TLS si fa qui, una volta, invece che su ogni server applicativo. Ora il proxy può leggere URL, intestazioni e cookie, e scegliere un server in base a essi.","At the reverse proxy":"Sul reverse proxy","Proxy can read":"Il proxy può leggere","URL, headers, cookies":"URL, intestazioni, cookie","Then picks":"Poi sceglie","An app server":"Un server applicativo","TLS ENDS HERE":"QUI FINISCE TLS","In the Clear":"In chiaro","Passed on to the app server":"Passata al server applicativo","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"Il proxy passa la richiesta sulla rete privata del data center, come HTTP in chiaro verso la porta 8080. Aggiunge X-Forwarded-For, l’indirizzo del visitatore, e X-Forwarded-Proto: https, il modo in cui è entrato il visitatore; altrimenti l’app vedrebbe solo il proxy. Chiunque possa osservare questa rete privata potrebbe leggere tutto.","The App Answers":"L’app risponde","In plain HTTP too":"Anche lei in HTTP in chiaro","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"Il server applicativo costruisce la pagina e risponde al proxy, in HTTP in chiaro: non ha mai a che fare con TLS o certificati.","text/html, 12,500 bytes":"text/html, 12,500 byte","readable inside":"leggibile all’interno","Encrypted Again":"Di nuovo cifrata","An ordinary HTTPS answer":"Una normale risposta HTTPS","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"Il reverse proxy cifra la risposta nella sessione TLS che ha con il portatile e la invia. Da fuori è un normale sito HTTPS.","Laptop sees":"Il portatile vede","One HTTPS server":"Un solo server HTTPS","App servers":"Server applicativi","Never handle TLS":"Non gestiscono mai TLS",Certificates:"Certificati","Renewed in one place":"Rinnovati in un solo posto","Three Options":"Tre opzioni","Offload, re-encrypt or pass through":"Scaricare, ricifrare o far passare","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Lo scarico, come qui, è semplice e veloce ma lascia leggibile il traffico interno. La ricifratura apre una seconda connessione TLS dal proxy al server applicativo, così resta cifrato anche all’interno. Il passaggio diretto inoltra i byte TLS senza aprirli: il certificato sta sui server applicativi, e il proxy può scegliere un server solo in base all’indirizzo e al nome nel Client Hello, non all’URL.",Offload:"Scarico","Plain HTTP inside":"HTTP in chiaro all’interno","Re-encrypt":"Ricifratura","TLS inside as well":"TLS anche all’interno","Pass through":"Passaggio diretto","Proxy can’t read it":"Il proxy non può leggerlo","PLAIN HTTP INSIDE":"HTTP IN CHIARO ALL’INTERNO","A Modern VPN":"Una VPN moderna","WireGuard (encrypted)":"WireGuard (cifrato)","TCP beyond the VPN":"TCP oltre la VPN",Keepalive:"Keepalive","VPN Server":"Server VPN","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"Una VPN porta il tuo traffico dentro un tunnel cifrato fino a un server VPN, che lo inoltra su Internet. Sul Wi-Fi di un bar gli altri vedono solo pacchetti cifrati diretti al server VPN; i siti vedono l’indirizzo del server VPN invece del tuo. WireGuard è una VPN moderna: poco codice, un unico insieme fisso di algoritmi moderni e un handshake di due messaggi.","UDP (51820 by default)":"UDP (51820 di default)","2 messages, 1 round trip":"2 messaggi, 1 viaggio di andata e ritorno",Crypto:"Crittografia",Identity:"Identità","Public keys, like SSH":"Chiavi pubbliche, come in SSH","The WireGuard whitepaper":"Il whitepaper di WireGuard","Tunnel up":"Tunnel attivo","Encrypted to the VPN, plain beyond it":"Cifrato fino alla VPN, in chiaro oltre","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Due messaggi di handshake hanno creato le chiavi. Poi ogni pacchetto inviato dal portatile è stato sigillato intero dentro un pacchetto UDP verso il server VPN, e il sito ha visto solo l’indirizzo del server VPN. Oltre il server VPN il traffico non è protetto meglio che senza VPN, quindi HTTPS conta ancora. Premi RIVEDI per guardarlo di nuovo.","Others nearby see":"Chi è vicino vede","UDP to 192.0.2.51":"UDP verso 192.0.2.51","Websites see":"I siti vedono","The VPN server":"Il server VPN","Beyond the VPN":"Oltre la VPN","Only HTTPS protects":"Protegge solo HTTPS",Overhead:"Sovraccarico","60 bytes + padding":"60 byte + riempimento","Set Up Once":"Configura una volta","Keys, not passwords":"Chiavi, non password","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"Il portatile esegue l’app WireGuard con una breve configurazione: la propria chiave privata, la chiave pubblica e l’indirizzo del server (192.0.2.51, porta UDP 51820), e AllowedIPs = 0.0.0.0/0, che significa che tutto passa nel tunnel. Dentro il tunnel l’indirizzo del portatile è 10.8.0.2.","Inside address":"Indirizzo interno","Through the tunnel":"Attraverso il tunnel","Everything (0.0.0.0/0)":"Tutto (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"INDIRIZZO NEL TUNNEL 10.8.0.2","Two messages, one round trip":"Due messaggi, un viaggio di andata e ritorno","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Quando il portatile ha per la prima volta qualcosa da inviare, avvia un handshake: 148 byte con una chiave pubblica nuova, la propria chiave a lungo termine (cifrata, così solo il server sa chi chiama) e l’ora (cifrata, così una registrazione non può essere riprodotta). Il server risponde solo alle chiavi che conosce, qui con 92 byte. Un viaggio di andata e ritorno, ed entrambi i lati hanno nuove chiavi di sessione.",Initiation:"Avvio","Server answers":"Il server risponde","Only keys it knows":"Solo alle chiavi che conosce",INITIATION:"INITIATION","fresh key + identity":"chiave nuova + identità",RESPONSE:"RESPONSE","keys agreed":"chiavi concordate","Into the Tunnel":"Nel tunnel","A packet inside a packet":"Un pacchetto dentro un pacchetto","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Apri https://www.example.com; anche il suo indirizzo è stato cercato attraverso il tunnel (non mostrato). Il primo pacchetto della connessione, un SYN TCP da 10.8.0.2 al server web, viene cifrato intero e inviato dentro un pacchetto UDP al server VPN. Sul Wi-Fi del bar si vede solo il pacchetto esterno: dal portatile a 192.0.2.51, porta 51820.",Outside:"Fuori","UDP to 192.0.2.51:51820":"UDP verso 192.0.2.51:51820","inside: TCP SYN to :443":"dentro: SYN TCP verso :443","Out to the Web":"Verso il web","Decrypted, then sent on":"Decifrato, poi inoltrato","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"Il server VPN decifra il pacchetto, sostituisce 10.8.0.2 con il proprio indirizzo pubblico (NAT) e inoltra il SYN, un salto più vecchio (TTL 127). Il SYN offre un segmento massimo di 1380 byte, non 1460: il tunnel aggiunge 60 byte a ogni pacchetto. Il server web vede un visitatore a 192.0.2.51 e risponde lì.","Website sees":"Il sito vede","192.0.2.51 (the VPN)":"192.0.2.51 (la VPN)","Hidden from the site":"Nascosto al sito","127 (one hop, the VPN)":"127 (un salto, la VPN)","from 192.0.2.51":"da 192.0.2.51","The Way Back":"La via del ritorno","Sealed again, for the laptop":"Di nuovo sigillato, per il portatile","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"La risposta torna allo stesso modo. Il server VPN sigilla il SYN-ACK in un pacchetto WireGuard per il portatile, che lo apre e lo passa a Windows come se fosse arrivato direttamente dal server web.",Counter:"Contatore","Each side counts its own":"Ogni lato conta il proprio",Replays:"Ripetizioni","Thrown away":"Scartate","inside: TCP SYN-ACK":"dentro: SYN-ACK TCP","Keeping It Open":"Tenerlo aperto","A keepalive, and new keys":"Un keepalive, e nuove chiavi","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Senza nulla da inviare, un tunnel WireGuard tace. Poiché il portatile è dietro NAT, è impostato per inviare un pacchetto vuoto ogni 25 secondi (PersistentKeepalive), un keepalive di 32 byte, così il router non si dimentica della connessione. Ogni due minuti un nuovo handshake crea chiavi nuove, e se il portatile passa a un’altra rete il tunnel continua semplicemente dal nuovo indirizzo.","Every 25 s, 32 bytes":"Ogni 25 s, 32 byte","New keys":"Nuove chiavi","Every 2 minutes":"Ogni 2 minuti","New network":"Nuova rete","The tunnel carries on":"Il tunnel continua",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"vuoto, 32 byte","Message type":"Tipo di messaggio","Sender index":"Indice del mittente","A number this side picked for the session; the other side puts it in every packet it sends back.":"Un numero scelto da questo lato per la sessione; l’altro lato lo mette in ogni pacchetto che rimanda.","Ephemeral key":"Chiave effimera","A new public key, made just for this handshake.":"Una nuova chiave pubblica, creata solo per questo handshake.","Encrypted static key":"Chiave statica cifrata","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"La chiave pubblica a lungo termine del portatile (32 byte) e un tag di 16 byte, cifrati: solo il server sa chi chiama.","Encrypted timestamp":"Timestamp cifrato","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"L’ora (12 byte) e un tag, cifrati. Un vecchio avvio rinviato viene rifiutato.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Calcolato con la chiave pubblica del server: senza di essa, il server non risponde affatto.","Used only when the server is busy and asks for a cookie first.":"Usato solo quando il server è occupato e chiede prima un cookie.","Receiver index":"Indice del destinatario","The other side’s index: which session this packet belongs to.":"L’indice dell’altro lato: a quale sessione appartiene questo pacchetto.","The server’s new public key for this handshake.":"La nuova chiave pubblica del server per questo handshake.","Encrypted nothing":"Niente, cifrato","Only a tag: it proves the server holds its private key.":"Solo un tag: dimostra che il server possiede la sua chiave privata.","Counts up with every packet; one seen before is thrown away.":"Aumenta a ogni pacchetto; uno già visto viene scartato.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"L’intero pacchetto interno, riempito fino a un multiplo di 16 byte, poi un tag di 16 byte.","then 12 bytes of padding, and the tag":"poi 12 byte di riempimento e il tag","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"Il portatile l’ha inviato con 128; il server VPN ha tolto 1 quando l’ha inoltrato.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Nient’altro che il tag di 16 byte: un pacchetto vuoto che tiene aperto il tunnel.","ESP (encrypted)":"ESP (cifrato)","TCP beyond the gateway":"TCP oltre il gateway","VPN Gateway":"Gateway VPN","IP Security":"IP Security","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec protegge i pacchetti IP stessi. IKEv2 prepara il terreno: i due lati concordano gli algoritmi, creano le chiavi e dimostrano chi sono con certificati o altre credenziali. Poi ESP porta ogni pacchetto cifrato dentro un altro. IPsec collega uffici tra loro e porta i portatili nelle reti aziendali, ed è integrato nella maggior parte dei sistemi operativi e dei firewall.","Behind NAT":"Dietro NAT","ESP (IP protocol 50)":"ESP (protocollo IP 50)","Certificates, EAP, keys":"Certificati, EAP, chiavi","IKE to set up, ESP to carry":"IKE per preparare, ESP per trasportare","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Quattro messaggi IKE hanno concordato gli algoritmi, scoperto il NAT, dimostrato entrambe le identità e preparato il tunnel. Poi ogni pacchetto ha viaggiato intero dentro ESP, cifrato e verificato, e avvolto in UDP per attraversare il router di casa. Premi RIVEDI per guardarlo di nuovo.","IKE messages":"Messaggi IKE","4 (2 exchanges)":"4 (2 scambi)","NAT traversal":"Attraversamento NAT","One SPI each way":"Uno SPI per verso","Agree on algorithms, swap keys":"Concorda gli algoritmi, scambia le chiavi","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"Il client VPN apre con IKE sulla porta UDP 500. Il primo messaggio propone gli algoritmi (AES-GCM con chiavi a 256 bit, SHA-256, Curve25519) e porta una chiave pubblica e un nonce casuale; il gateway sceglie la proposta e invia la propria chiave e il proprio nonce. Ora entrambi condividono un segreto, ma nessuno dei due ha ancora dimostrato chi è.",Proposed:"Proposti","After this":"Dopo questo","Shared keys, no identities":"Chiavi condivise, nessuna identità","proposal, key, nonce":"proposta, chiave, nonce","NAT detection":"rilevamento NAT","chosen proposal, key, nonce":"proposta scelta, chiave, nonce","A NAT in the Way":"Un NAT di mezzo","So everything moves to port 4500":"Quindi tutto passa alla porta 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Entrambi i messaggi portavano anche gli hash dell’indirizzo e della porta da cui ciascun lato ha inviato. Al gateway non corrispondono a ciò che è arrivato: il router di casa ha riscritto l’indirizzo del portatile lungo la strada (NAT). ESP non ha numeri di porta, quindi un NAT non può farlo passare; entrambi i lati passano alla porta UDP 4500 e d’ora in poi avvolgono ESP in UDP.","Hashes of":"Hash di","Address and port sent from":"Indirizzo e porta di invio",Mismatch:"Non corrispondono","The router rewrote them":"Il router li ha riscritti",Fix:"Soluzione","Everything over UDP 4500":"Tutto su UDP 4500","NAT DETECTED":"NAT RILEVATO","Prove who you are, encrypted":"Dimostra chi sei, cifrato","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Ora cifrato, ogni lato invia la propria identità, il proprio certificato e una firma su tutto ciò che è stato detto finora, così chiunque in mezzo verrebbe scoperto. Il portatile chiede un indirizzo dentro la rete e ottiene 10.8.0.2. Lo stesso scambio prepara il tunnel ESP vero e proprio, con chiavi proprie e uno SPI per ogni direzione.","UDP 4500 (NAT traversal)":"UDP 4500 (attraversamento NAT)","Identity, by certificate":"Identità, con certificato","Laptop gets":"Il portatile ottiene","10.8.0.2, and a DNS server":"10.8.0.2, e un server DNS","identity, certificate":"identità, certificato",signature:"firma","address 10.8.0.2":"indirizzo 10.8.0.2","The whole packet, encrypted":"L’intero pacchetto, cifrato","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Apri https://www.example.com, cercato attraverso il tunnel sul server DNS fornito dal gateway (non mostrato). Il SYN da 10.8.0.2 viene cifrato intero in un pacchetto ESP: uno SPI che identifica il tunnel, un numero di sequenza, poi il pacchetto cifrato e un valore di controllo, il tutto dentro la porta UDP 4500. Il suo checksum UDP è zero: ESP verifica da sé il proprio contenuto.","Names the tunnel":"Identifica il tunnel","The whole IP packet":"L’intero pacchetto IP","62 bytes + padding":"62 byte + riempimento","Out and Back":"Andata e ritorno","Through the gateway and home again":"Attraverso il gateway e di nuovo a casa","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"Il gateway decifra il pacchetto e inoltra il SYN dal proprio indirizzo, un salto più vecchio. La risposta torna al gateway e rientra nel tunnel come un altro pacchetto ESP, con lo SPI della direzione del portatile e i suoi numeri di sequenza.","192.0.2.51 (the gateway)":"192.0.2.51 (il gateway)","Each direction":"Ogni direzione","Its own SPI and keys":"Il proprio SPI e le proprie chiavi","Which VPN?":"Quale VPN?","IPsec or WireGuard":"IPsec o WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec è più vecchio e molto flessibile: negozia gli algoritmi, accetta molti tipi di credenziali ed è integrato in Windows, macOS, iOS, Android e nella maggior parte dei firewall, il che lo rende il modo abituale per entrare in una rete aziendale o collegare due uffici. WireGuard fa meno, con molto meno codice e un unico insieme fisso di algoritmi.","Built into":"Integrato in","Also links":"Collega anche","Office to office":"Ufficio con ufficio",Negotiates:"Negozia","Its algorithms (WireGuard: no)":"I suoi algoritmi (WireGuard: no)","Initiator SPI":"SPI dell’iniziatore","Picked by the laptop: which IKE session this is.":"Scelto dal portatile: quale sessione IKE è questa.","Responder SPI":"SPI del risponditore","0 (not known yet)":"0 (ancora sconosciuto)","Next payload":"Payload successivo","Exchange type":"Tipo di scambio","0x08 (initiator)":"0x08 (iniziatore)","Message ID":"ID messaggio","Each request and its response share a number; the next exchange counts up.":"Ogni richiesta e la sua risposta condividono un numero; lo scambio successivo conta in avanti.","SA payload":"Payload SA","Next payload, length":"Payload successivo, lunghezza",Proposal:"Proposta","What the laptop offers; a real client often offers several.":"Ciò che offre il portatile; un client reale spesso ne offre diverse.","KE payload":"Payload KE","DH group":"Gruppo DH","This side’s public key. From the two, both work out the same secret.":"La chiave pubblica di questo lato. Dalle due, entrambi ricavano lo stesso segreto.","Nonce payload":"Payload nonce","Notify payload":"Payload notify",Notify:"Notify",Hash:"Hash","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Un hash degli SPI e dell’indirizzo e della porta da cui questo lato ha inviato. Se ciò che arriva non corrisponde, un NAT l’ha cambiato lungo la strada.","The same for the address and port it sent to.":"Lo stesso per l’indirizzo e la porta di destinazione.","0x20 (response)":"0x20 (risposta)","The one the server chose from the laptop’s offer.":"Quella che il server ha scelto tra le offerte del portatile.","Non-ESP marker":"Marcatore non-ESP","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Quattro byte a zero: un messaggio IKE, non un pacchetto ESP (condividono la porta 4500).","Encrypted payload":"Payload cifrato","Encrypted payloads":"Payload cifrati","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Tutto il resto di questo messaggio, cifrato con le chiavi di IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: chi è il portatile, dimostrato","CP: asks for an inside address and DNS":"CP: chiede un indirizzo interno e il DNS","SA: what to use for ESP (AES-GCM)":"SA: cosa usare per ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: quale traffico va nel tunnel","Integrity check":"Controllo di integrità","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: chi è il gateway, dimostrato","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: indirizzo interno 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP con AES-GCM, e gli SPI","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: tutto (0.0.0.0/0)","0 (not used)":"0 (non usato)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP verifica da sé il proprio contenuto, quindi ESP trasportato in UDP lascia questo campo a zero.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"A quale tunnel (security association) appartiene; il lato ricevente l’ha scelto durante IKE_AUTH.","Different for every packet.":"Diverso per ogni pacchetto.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"L’intero pacchetto interno, poi il riempimento, la lunghezza del riempimento e l’intestazione successiva (4: un pacchetto IPv4).","then padding, pad length and next header (4)":"poi riempimento, lunghezza del riempimento e intestazione successiva (4)","Shows any change to the packet.":"Rivela qualsiasi modifica al pacchetto.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"Il portatile l’ha inviato con 128; il gateway ha tolto 1 quando l’ha inoltrato.","HTTP/3 over QUIC":"HTTP/3 su QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC è un trasporto più recente che funziona su UDP e ha TLS 1.3 integrato. I suoi primi pacchetti fanno insieme l’handshake del trasporto e quello della cifratura, così una richiesta di pagina può partire dopo un solo viaggio di andata e ritorno. Porta molti flussi insieme, quindi un pacchetto perso non blocca gli altri, e sopravvive a un cambio di rete. HTTP/3 è HTTP che funziona su QUIC.","Runs over":"Funziona su","UDP, port 443":"UDP, porta 443","TLS 1.3, always":"TLS 1.3, sempre","1 round trip (0 when returning)":"1 viaggio di andata e ritorno (0 al ritorno)",Streams:"Flussi","Many, independent":"Molti, indipendenti","One round trip, then the request":"Un viaggio di andata e ritorno, poi la richiesta","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC ha unito gli handshake di trasporto e TLS in un solo viaggio di andata e ritorno, così la richiesta è partita 36 ms dopo il primo pacchetto; con TCP e TLS avrebbe aspettato il doppio. Tutto ciò che è venuto dopo i primi pacchetti era cifrato, perfino gran parte dell’intestazione di ogni pacchetto. Premi RIVEDI per guardarlo di nuovo.","1 before the request (TCP + TLS: 2)":"1 prima della richiesta (TCP + TLS: 2)","Lost packet":"Pacchetto perso","Holds up one stream only":"Blocca un solo flusso","Choosing HTTP/3":"Scegliere HTTP/3","An earlier visit said it can":"Una visita precedente ha detto che si può",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'In una visita precedente il server ha risposto con Alt-Svc: h3=":443", cioè parla anche HTTP/3 sulla porta UDP 443 (il DNS può dire lo stesso in un record HTTPS). Così stavolta il browser salta TCP e parla QUIC.',"Learned from":"Appreso da","Alt-Svc header, or DNS":"Intestazione Alt-Svc, o DNS","QUIC over UDP 443":"QUIC su UDP 443","TLS 1.3, built in":"TLS 1.3, integrato","Initial Packets":"Pacchetti Initial","The Client Hello, straight away":"Il Client Hello, subito","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Non c’è un handshake TCP separato: i primissimi pacchetti portano il TLS Client Hello. Con la sua condivisione di chiave post-quantistica è di 1,880 byte, troppo per un pacchetto, quindi riempie due pacchetti Initial. Ogni datagramma è riempito fino ad almeno 1,200 byte; un server può rimandare solo il triplo di ciò che ha ricevuto, così un indirizzo mittente falsificato non può trasformarlo in un amplificatore.","2 × 1,250 bytes":"2 × 1,250 byte","The TLS Client Hello":"Il TLS Client Hello","Readable?":"Leggibile?","Yes (Initial keys are public)":"Sì (le chiavi Initial sono pubbliche)","Client Hello, part 1":"Client Hello, parte 1","Client Hello, part 2":"Client Hello, parte 2",padding:"riempimento","Then the certificate, encrypted":"Poi il certificato, cifrato","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"Il server risponde con il suo Server Hello in un pacchetto Initial. Ora entrambi i lati possono ricavare le chiavi di handshake, quindi il resto (il certificato, la sua firma e Finished) arriva in pacchetti Handshake che solo il portatile può leggere. Quattro datagrammi, ben meno del triplo di ciò che ha inviato il portatile.","Certificate, signature, Finished":"Certificato, firma, Finished","Server limit":"Limite del server","3× the bytes received":"3× i byte ricevuti","certificate, Finished":"certificato, Finished","The request, one round trip in":"La richiesta, dopo un viaggio di andata e ritorno","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"Il portatile verifica il certificato e invia il suo Finished, e nello stesso momento la sua prima richiesta HTTP/3 in un pacchetto 1-RTT: un frame HEADERS sul flusso 0, con le intestazioni compresse con QPACK. Un viaggio di andata e ritorno dopo il primo pacchetto, la richiesta è già in viaggio; TCP e TLS insieme ne richiederebbero due.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS sul flusso 0",Headers:"Intestazioni","Compressed (QPACK)":"Compresse (QPACK)","HTTP/3, stream 0":"HTTP/3, flusso 0","The Response":"La risposta","On its own stream":"Sul suo flusso","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"Il server conferma che l’handshake è finito (HANDSHAKE_DONE) e risponde sul flusso 0: intestazioni, poi la pagina. Ogni richiesta ha il suo flusso, quindi un pacchetto perso blocca solo il flusso a cui apparteneva. Con TCP un solo segmento mancante ferma tutto ciò che viene dopo.","Frames on QUIC streams":"Frame su flussi QUIC","Holds up one stream":"Blocca un solo flusso","All but a few header bits":"Tutto tranne pochi bit dell’intestazione","the page":"la pagina","New Network":"Nuova rete","Known by ID, not by address":"Riconosciuta dall’ID, non dall’indirizzo","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Una connessione QUIC si riconosce dai suoi ID di connessione, non da indirizzi e porte. Se il portatile passa dal Wi-Fi all’hotspot di un telefono, il suo indirizzo cambia ma la connessione continua: il server verifica il nuovo percorso e prosegue. E alla visita successiva il browser può inviare la richiesta nei primissimi pacchetti (0-RTT).","Known by":"Riconosciuta da","Connection ID":"ID di connessione","New address":"Nuovo indirizzo","The connection carries on":"La connessione continua","Next visit":"Visita successiva","0-RTT: request at once":"0-RTT: richiesta immediata","SAME CONNECTION ON ANY NETWORK":"STESSA CONNESSIONE SU QUALSIASI RETE","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, parte 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, parte 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (Certificato, parte 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (Certificato, parte 2)","Initial packet":"Pacchetto Initial","Header type":"Tipo di intestazione","long header, Initial":"intestazione lunga, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"I bit alti dicono che tipo di pacchetto è; gli ultimi bit sono mascherati (protezione dell’intestazione).","Destination connection ID":"ID di connessione di destinazione","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"A quale connessione appartiene. Ogni lato sceglie il proprio ID; l’altro lo scrive qui.","Source connection ID":"ID di connessione di origine","Token length":"Lunghezza del token","No token: the server hasn’t asked this client to prove its address first.":"Nessun token: il server non ha chiesto a questo client di dimostrare prima il proprio indirizzo.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Il numero di pacchetto e il payload. Ciò che segue è un altro pacchetto nello stesso datagramma.","Packet number":"Numero di pacchetto","Hidden by header protection, so nobody on the way can read or change it.":"Nascosto dalla protezione dell’intestazione, così nessuno lungo la strada può leggerlo o modificarlo.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Cifrato con chiavi che chiunque può ricavare dall’ID di connessione, quindi ferma gli incidenti, non chi ascolta: il Client Hello all’interno si può leggere lungo la strada.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, byte 1–1,203 di 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, key share X25519MLKEM768","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, byte 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, fino a 1,250 byte","ACK: packets 0–1 arrived":"ACK: i pacchetti 0–1 sono arrivati","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, con la sua metà della chiave (1,120 byte)","Handshake packet":"Pacchetto Handshake","long header, Handshake":"intestazione lunga, Handshake","Encrypted with keys from the key exchange so far.":"Cifrato con le chiavi dello scambio di chiavi fin qui.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (inizio)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (continua)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: è arrivato l’Initial del server","ACK: the Handshake packets arrived":"ACK: sono arrivati i pacchetti Handshake","1-RTT packet":"Pacchetto 1-RTT","short header":"intestazione corta","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Solo l’ID del destinatario, e nessuna lunghezza: conosce la lunghezza dei propri ID. Resta uguale se il portatile cambia rete.","Encrypted with the session keys.":"Cifrato con le chiavi di sessione.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (il flusso di controllo)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (compresso con QPACK)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: l’handshake è finito","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, poi DATA: la pagina (1,000 byte)","ACK: the response arrived":"ACK: la risposta è arrivata","Address Setup":"Configurazione dell’indirizzo","No IPv6 address":"Nessun indirizzo IPv6","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC e scoperta dei vicini","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"Gli indirizzi IPv6 sono lunghi 128 bit, abbastanza perché ogni dispositivo abbia il proprio. Di solito un dispositivo può configurarsi da solo senza un server DHCP: crea un indirizzo link-local, chiede un router e costruisce il proprio indirizzo globale dal prefisso che il router annuncia (SLAAC). La scoperta dei vicini, parte di ICMPv6, trova gli indirizzi MAC e fa il lavoro che ARP fa per IPv4.","128 bits":"128 bit",Addresses:"Indirizzi","SLAAC: no server needed":"SLAAC: nessun server necessario","Replaces ARP":"Sostituisce ARP","Neighbour discovery":"Scoperta dei vicini",Optional:"Facoltativo","Two addresses, no DHCP":"Due indirizzi, senza DHCP","Made by the laptop itself":"Creati dal portatile stesso","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"Il portatile ha creato un indirizzo link-local e uno globale, ha controllato che nessun altro li avesse e ha imparato router, MTU e server DNS da un unico annuncio. Quando sono arrivati pacchetti per lui, la scoperta dei vicini ha trovato il suo indirizzo MAC. Premi RIVEDI per guardarlo di nuovo.","Link-local":"Link-local",Global:"Globale","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + il proprio ID","Router, DNS":"Router, DNS","From one advertisement":"Da un unico annuncio","6, all ICMPv6":"6, tutti ICMPv6","Link-Local First":"Prima il link-local","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Ogni interfaccia IPv6 riceve un indirizzo link-local, utilizzabile solo sulla propria rete. Il portatile ne crea uno da fe80:: e un ID di interfaccia a 64 bit dall’aspetto casuale. Prima controlla che nessuno lo abbia già: una Neighbor Solicitation che chiede quell’indirizzo, inviata da :: perché non può ancora usare l’indirizzo. Nessuno risponde, quindi è del portatile.",Check:"Controllo","Duplicate address detection":"Rilevamento di indirizzi duplicati","None: the address is free":"Nessuna: l’indirizzo è libero","IS IT TAKEN?":"È GIÀ USATO?","from ::":"da ::","target fe80::8d2e:4f61:a9b0:7c13":"target fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"NESSUNA RISPOSTA: L’INDIRIZZO È LIBERO","Any Routers?":"Ci sono router?","A Router Solicitation":"Una Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Gli indirizzi link-local non raggiungono Internet. Il portatile invia una Router Solicitation a ff02::2, l’indirizzo che ogni router della rete ascolta, con allegato il proprio indirizzo MAC.","ff02::2 (all routers)":"ff02::2 (tutti i router)",Includes:"Include","ROUTERS?":"ROUTER?","Router Answers":"Il router risponde","Prefix, MTU and DNS in one message":"Prefisso, MTU e DNS in un messaggio","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"Il router risponde a ff02::1, cioè a ogni dispositivo della rete, con un Router Advertisement: usami come uscita per 30 minuti, ecco il mio indirizzo MAC, l’MTU è 1500, il prefisso della rete è 2001:db8:1234:5678::/64 e puoi crearti un indirizzo al suo interno, e chiedi il DNS a 2001:4860:4860::8888. I router inviano questi annunci anche da soli ogni pochi minuti.",Prefix:"Prefisso","Make your own":"Creane uno tuo","Yes (flag A)":"Sì (flag A)",ADVERTISEMENT:"ANNUNCIO","prefix 2001:db8:1234:5678::/64":"prefisso 2001:db8:1234:5678::/64","A Global Address":"Un indirizzo globale","Prefix + interface ID":"Prefisso + ID di interfaccia","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"Il portatile unisce il prefisso e il suo ID di interfaccia in un indirizzo globale, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, e lo controlla allo stesso modo. Windows crea anche un indirizzo temporaneo con un ID casuale che cambia ogni giorno, usato per le connessioni in uscita così i siti non possono seguire un dispositivo dal suo indirizzo.","Also made":"Creato anche","A temporary address":"Un indirizzo temporaneo","target the global address":"target l’indirizzo globale","Neighbour Lookup":"Ricerca del vicino","Who has this address? (ARP’s job)":"Chi ha questo indirizzo? (il lavoro di ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Una risposta da Internet arriva al router per l’indirizzo globale del portatile. Per consegnarla, il router ha bisogno dell’indirizzo MAC corrispondente: invia una Neighbor Solicitation al gruppo solicited-node dell’indirizzo, così solo i dispositivi il cui indirizzo finisce allo stesso modo la guardano. Il portatile risponde con un Neighbor Advertisement che porta il suo indirizzo MAC.","Asked to":"Chiesto a","Instead of":"Invece di","ARP broadcasts to everyone":"I broadcast ARP a tutti","WHO HAS?":"CHI CE L’HA?","the global address":"l’indirizzo globale","Ready, No DHCP":"Pronto, senza DHCP","And no NAT either":"E nemmeno NAT","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"Il portatile è su Internet con il proprio indirizzo globale, e nessun NAT lo cambia lungo la strada: l’indirizzo che vede un sito è quello del portatile. Il firewall del router di casa respinge comunque le connessioni che nessuno all’interno ha chiesto. Le reti che vogliono assegnare gli indirizzi in modo centralizzato possono usare DHCPv6.","Not needed":"Non serve",Incoming:"In entrata","Blocked by the firewall":"Bloccato dal firewall","Optional (flags M, O)":"Facoltativo (flag M, O)","ONLINE OVER IPv6":"ONLINE SU IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Un indirizzo MAC multicast: 33:33, poi gli ultimi quattro byte dell’indirizzo IPv6.","Version, class, flow":"Versione, classe, flusso","IPv6, ordinary traffic, no flow label.":"IPv6, traffico normale, nessuna etichetta di flusso.","Payload length":"Lunghezza del payload","What follows this 40-byte header.":"Ciò che segue questa intestazione di 40 byte.","Next header":"Intestazione successiva","Hop limit":"Limite di salti","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"La scoperta dei vicini deve arrivare con 255, prova che nessun router l’ha inoltrata: viene da questa rete.","Unspecified: the laptop has no address it may use yet.":"Non specificato: il portatile non ha ancora un indirizzo che può usare.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Multicast solicited-node: ascoltano solo i dispositivi il cui indirizzo finisce con gli stessi 24 bit.","Covers the message and both IPv6 addresses.":"Copre il messaggio ed entrambi gli indirizzi IPv6.",Target:"Target","The address the laptop wants to use. If anyone answers, it’s taken.":"L’indirizzo che il portatile vuole usare. Se qualcuno risponde, è già occupato.","A link-local address: usable only on this network.":"Un indirizzo link-local: utilizzabile solo su questa rete.","Every router on this network.":"Ogni router di questa rete.","Source link-layer address":"Indirizzo di livello link di origine","The sender’s MAC address, so nobody has to ask for it.":"L’indirizzo MAC del mittente, così nessuno deve chiederlo.","Every device on this network.":"Ogni dispositivo di questa rete.","The hop limit devices here should put on their packets.":"Il limite di salti che i dispositivi qui devono mettere sui loro pacchetti.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: prendi gli indirizzi da DHCPv6. O: prendi le altre impostazioni da DHCPv6. Entrambi spenti: questo annuncio contiene tutto.","Router lifetime":"Durata del router","How long the laptop may use this router as its way out.":"Per quanto tempo il portatile può usare questo router come uscita.","Reachable time":"Tempo di raggiungibilità","0 (not set)":"0 (non impostato)","Retransmit timer":"Timer di ritrasmissione","The largest packet this network carries.":"Il pacchetto più grande che questa rete trasporta.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, valido 86,400 s, preferito 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Flag L e A: gli indirizzi di questo prefisso sono su questa rete, e i dispositivi possono crearsene uno (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, per 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Server DNS ricorsivo: quale resolver interrogare, così nemmeno per questo serve DHCP.","Whose MAC address is wanted.":"Di chi si cerca l’indirizzo MAC.","The device this frame is for.":"Il dispositivo a cui è destinato questo frame.","0x60000000: solicited, override":"0x60000000: solicited, override","Solicited: this answers a question. Override: replace any older entry for this address.":"Solicited: risponde a una domanda. Override: sostituisce ogni voce più vecchia per questo indirizzo.","Target link-layer address":"Indirizzo di livello link del target","The answer: the MAC address that goes with the target.":"La risposta: l’indirizzo MAC che corrisponde al target.","Setting the Clock":"Regolare l’orologio","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Gli orologi dei computer derivano di qualche secondo a settimana, e molto dipende da loro: i certificati hanno date, accessi e pagamenti scadono, i log di macchine diverse devono combaciare. NTP regola un orologio da un server dell’ora su Internet. Una piccola richiesta e una risposta portano quattro timestamp, abbastanza per calcolare di quanto sbaglia l’orologio e quanto tempo ha impiegato la rete.",Accuracy:"Precisione","A few milliseconds online":"Pochi millisecondi online","Clock set":"Orologio regolato","Four timestamps, one answer":"Quattro timestamp, una risposta","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Una richiesta e una risposta hanno dato quattro timestamp. Da questi il portatile ha calcolato che il suo orologio era indietro di 0.25 s e che la rete impiegava 24 ms tra andata e ritorno, e ha iniziato a riallineare dolcemente l’orologio. Premi RIVEDI per guardarlo di nuovo.",Offset:"Scarto","250.0 ms (slow)":"250.0 ms (indietro)","Stratum 2":"Stratum 2","Next check":"Prossimo controllo","Minutes to days later":"Da minuti a giorni dopo","Clocks Drift":"Gli orologi derivano","The laptop’s clock is a little slow":"L’orologio del portatile è un po’ indietro","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Un computer misura il tempo con un cristallo di quarzo che va un po’ avanti o indietro, quindi gli orologi si allontanano di qualche secondo a settimana. L’orologio di questo portatile è indietro di un quarto di secondo. Windows lo regola da time.windows.com, il cui indirizzo ha già cercato con il DNS.","Laptop clock":"Orologio del portatile","0.25 s slow":"Indietro di 0.25 s","Time server":"Server dell’ora","Why it matters":"Perché conta","Certificates, logins, logs":"Certificati, accessi, log","CLOCK 0.250 s SLOW":"OROLOGIO INDIETRO DI 0.250 s","Ask for the Time":"Chiedi l’ora","T1: when the request leaves":"T1: quando la richiesta parte","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"Il portatile invia una richiesta di 48 byte alla porta 123. Ci scrive l’ora del proprio orologio al momento della partenza: T1, 09:40:59.750. Tutto il resto è vuoto.","T1 (laptop)":"T1 (portatile)",Mode:"Modo","3 (client)":"3 (client)","The Answer":"La risposta","T2 and T3 from the server, T4 on arrival":"T2 e T3 dal server, T4 all’arrivo","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"Il server ricopia T1, aggiunge T2, quando è arrivata la richiesta, e T3, quando parte la sua risposta, entrambi secondo il proprio orologio preciso. Quando arriva la risposta, il portatile annota T4 secondo il proprio orologio. Il server è di stratum 2: regola il suo orologio da un server di stratum 1, che ha un ricevitore GPS o un orologio atomico.","T4 (laptop)":"T4 (portatile)",Stratum:"Stratum","The Offset":"Lo scarto","Four times, two answers":"Quattro tempi, due risposte","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"Il tempo in rete, andata e ritorno, è (T4 − T1) − (T3 − T2) = 24.0 ms. Lo scarto presume che il viaggio duri lo stesso in ogni verso: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. L’orologio del portatile è indietro di un quarto di secondo. Un percorso asimmetrico (più lento in un verso che nell’altro) falserebbe il risultato fino a metà della differenza.",Assumes:"Presume","Equal time each way":"Stesso tempo in ogni verso","OFFSET +250.0 ms":"SCARTO +250.0 ms","Ease It In":"Riallineare dolcemente","No jumps backwards":"Niente salti all’indietro","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Un piccolo errore non si corregge con un salto: l’orologio viene fatto andare leggermente più veloce finché non recupera, così per i programmi in esecuzione il tempo non si ferma e non torna mai indietro. Solo un errore grande viene corretto subito. Man mano che l’orologio si stabilizza, un client NTP chiede meno spesso, da ogni 64 secondi fino a circa ogni 17 minuti; Windows da solo controlla time.windows.com molto più di rado, ogni diverse ore o meno.","Small offsets":"Scarti piccoli","Eased in gradually":"Riallineati gradualmente","Large offsets":"Scarti grandi","Set at once":"Corretti subito","Asks again":"Chiede di nuovo","Less often as it settles":"Meno spesso man mano che si stabilizza","CLOCK IN STEP":"OROLOGIO ALLINEATO","Leap, version, mode":"Leap, versione, modo","Mode 3: a client asking for the time.":"Modo 3: un client che chiede l’ora.",Poll:"Poll","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"Ogni quanto il client intende chiedere (2 alla 6 secondi). Cresce man mano che l’orologio si stabilizza.",Precision:"Precisione","How finely this clock can be read.":"Con quale finezza si può leggere questo orologio.","Root delay":"Ritardo dalla radice","Root dispersion":"Dispersione dalla radice","Reference ID":"ID di riferimento","Reference time":"Ora di riferimento","Origin time":"Ora di origine","Receive time":"Ora di ricezione","Transmit time":"Ora di trasmissione","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: quando è partita la richiesta, secondo l’orologio (sbagliato) del portatile.","Mode 4: an answer from a server.":"Modo 4: una risposta da un server.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"Due passi da un orologio di riferimento: segue un server di stratum 1, che ha un proprio GPS o orologio atomico.","Round-trip time from this server to the reference clock.":"Tempo di andata e ritorno da questo server all’orologio di riferimento.","How far off this server could be, at most.":"Di quanto può sbagliare questo server, al massimo.","192.0.2.123 (its own time source)":"192.0.2.123 (la sua fonte dell’ora)","When this server last set its own clock.":"Quando questo server ha regolato l’ultima volta il proprio orologio.","T1, copied from the request: the client can match the answer to its question.":"T1, ricopiato dalla richiesta: il client può abbinare la risposta alla sua domanda.","T2: when the request arrived, by the server’s clock.":"T2: quando è arrivata la richiesta, secondo l’orologio del server.","T3: when this answer left.":"T3: quando è partita questa risposta.",Private:"Privato","Plain DNS":"DNS in chiaro","DNS inside HTTPS":"DNS dentro HTTPS","DNS queries inside HTTPS":"Query DNS dentro HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"Il DNS normale viaggia in chiaro: chiunque sullo stesso Wi-Fi, e il tuo provider Internet, può leggere ogni nome che cerchi e perfino cambiare le risposte. DNS over HTTPS (DoH) invia gli stessi messaggi DNS dentro una connessione HTTPS cifrata verso il resolver, così lungo la strada sembrano traffico web come un altro. Browser e sistemi operativi possono attivarlo.","Ordinary DNS messages":"Normali messaggi DNS",Hides:"Nasconde","Which names you look up":"Quali nomi cerchi",Similar:"Simile","DNS over TLS (port 853)":"DNS over TLS (porta 853)","Looked up in private":"Ricerca in privato","Same question, sealed":"Stessa domanda, sigillata","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"La ricerca in chiaro poteva essere letta da chiunque lungo il percorso. Su HTTPS lo stesso messaggio DNS è stato sigillato dentro TLS, leggibile solo dal resolver. Il resolver vede comunque ogni domanda, quindi la fiducia si sposta su di lui, e il sito che poi visiti si vede ancora dal suo indirizzo. Premi RIVEDI per guardarlo di nuovo.","On the way":"Lungo la strada","Only “HTTPS to dns.google”":"Solo «HTTPS verso dns.google»","The resolver":"Il resolver","Still sees every name":"Vede ancora ogni nome","The site’s address you then visit":"L’indirizzo del sito che poi visiti","Can’t be changed on the way":"Non si può modificare lungo la strada","Readable by anyone on the way":"Leggibile da chiunque lungo la strada","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"È la ricerca delle altre lezioni: un pacchetto UDP verso la porta 53 che chiede www.example.com, e la risposta. Nessuno dei due è cifrato, quindi tutti sul Wi-Fi del bar, e il provider Internet, possono vedere quali nomi cerca il portatile, e perfino rispondere con un indirizzo falso.","UDP port 53":"Porta UDP 53","Can be changed":"Modificabile","Yes, on the way":"Sì, lungo la strada",readable:"leggibile","ANYONE HERE CAN READ IT":"CHIUNQUE QUI PUÒ LEGGERLO","An HTTPS Link":"Un collegamento HTTPS","TCP and TLS to dns.google":"TCP e TLS verso dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Con DNS over HTTPS attivo, il browser apre invece una connessione HTTPS verso il resolver: TCP verso la porta 443 e un handshake TLS per dns.google. Tiene aperta questa connessione e ci manda ogni ricerca.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, come qualsiasi sito","Kept open":"Tenuta aperta","For every lookup":"Per ogni ricerca","Sealed Question":"Domanda sigillata","A DNS message in an HTTP request":"Un messaggio DNS in una richiesta HTTP","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"La domanda è lo stesso messaggio DNS di prima. Va in una richiesta HTTP/2, GET /dns-query?dns= seguito dal messaggio in base64url, chiedendo una risposta di tipo application/dns-message. Dentro TLS nessuno lungo la strada può leggerla.",Format:"Formato","application/dns-message":"application/dns-message","Encrypted (TLS)":"Cifrato (TLS)","DoH QUERY":"QUERY DoH","inside: GET /dns-query?dns=…":"dentro: GET /dns-query?dns=…","Sealed Answer":"Risposta sigillata","The DNS answer in an HTTP response":"La risposta DNS in una risposta HTTP","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"Il resolver risponde 200 con un corpo di tipo application/dns-message: la stessa risposta DNS della ricerca in chiaro, A 203.0.113.10. Poiché arriva attraverso TLS da dns.google, nessuno lungo la strada avrebbe potuto modificarla.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"La risposta DNS (49 byte)",Tampering:"Manomissione","Impossible on the way":"Impossibile lungo la strada","DoH ANSWER":"RISPOSTA DoH","inside: A 203.0.113.10":"dentro: A 203.0.113.10","What Still Shows":"Cosa si vede ancora","Hidden on the way, not from the resolver":"Nascosto lungo la strada, non al resolver","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"Lungo la strada, ora le ricerche sembrano normale traffico HTTPS verso dns.google. Ma il resolver legge ogni domanda, quindi ti fidi di lui invece che di chi gestisce la tua rete. E il sito che poi visiti si vede comunque dal suo indirizzo IP, e dal suo nome nel TLS Client Hello a meno che non supporti Encrypted Client Hello. DNS over TLS fa lo stesso lavoro sulla porta 853.","Sees every name":"Vede ogni nome","Then visible":"Poi visibile","The site’s IP, maybe its name":"L’IP del sito, forse il nome",Alternative:"Alternativa","TRUST MOVES TO THE RESOLVER":"LA FIDUCIA PASSA AL RESOLVER","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: query DNS)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: risposta DNS)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: il preambolo di connessione e le impostazioni, poi la richiesta","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: impostazioni, le intestazioni della risposta, poi la risposta DNS","Signed Answers":"Risposte firmate","Question and answer":"Domanda e risposta","To the name servers":"Verso i name server","Signed answers":"Risposte firmate","DNS Security Extensions":"DNS Security Extensions","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Le risposte DNS normali si possono falsificare: chi risponde per primo, o sta in mezzo, può inviare un indirizzo falso. DNSSEC permette a un resolver di verificare che una risposta venga davvero dal proprietario del dominio. Ogni insieme di record è firmato; la chiave di ogni zona è garantita dalla zona superiore, fino alla radice, la cui chiave è integrata nei resolver. DNSSEC dimostra che le risposte sono autentiche; non le nasconde.","Adds records":"Aggiunge record","Checked by":"Verificato da","Trust anchor":"Ancora di fiducia","The root’s key (built in)":"La chiave della radice (integrata)","Hides queries":"Nasconde le query","No (that’s DoH)":"No (quello è DoH)","Answer checked":"Risposta verificata","A chain of signatures to the root":"Una catena di firme fino alla radice","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"Il resolver ha seguito una catena: l’indirizzo era firmato dalla chiave di example.com, quella chiave dalla sua chiave di firma delle chiavi, garantita da .com con un record DS firmato, e la chiave di .com è garantita dalla radice, la cui chiave è integrata nel resolver. Una risposta falsificata avrebbe spezzato la catena. Premi RIVEDI per guardarlo di nuovo.","Signatures checked":"Firme verificate","3 here (plus cached ones)":"3 qui (più quelle in cache)","The AD flag":"Il flag AD","Forged answer":"Risposta falsificata","Fails the check":"Non supera la verifica","Ask as Usual":"Chiedi come al solito","The laptop’s question doesn’t change":"La domanda del portatile non cambia","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"Il portatile chiede al suo resolver www.example.com come sempre. La verifica avviene sul resolver, che interroga i name server con il flag DNSSEC OK attivo: invia anche le firme.","Checking done by":"Verifica fatta da","The resolver (8.8.8.8)":"Il resolver (8.8.8.8)","Resolver sets":"Il resolver imposta","Signed Answer":"Risposta firmata","An RRSIG comes with the A record":"Un RRSIG arriva con il record A","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"Il resolver conosce già il name server di example.com da ricerche precedenti. Quel server invia l’indirizzo con un record RRSIG: una firma sul record A, fatta con la chiave privata della zona. L’RRSIG dice quale chiave l’ha firmato (la chiave 47362, la chiave di firma della zona) e quando scade la firma. Per verificarla il resolver ha bisogno di quella chiave.","RRSIG by key 47362":"RRSIG con la chiave 47362",Valid:"Valida","31 Oct to 21 Nov 2026":"Dal 31 ott al 21 nov 2026","signed by key 47362":"firmato con la chiave 47362","The Zone’s Keys":"Le chiavi della zona","DNSKEY records, signed too":"Record DNSKEY, firmati anche loro","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"Il resolver chiede le chiavi di example.com. Sono due: la chiave di firma della zona (flag 256) che ha firmato il record A, e la chiave di firma delle chiavi (flag 257), che firma solo l’insieme delle chiavi. Con esse il resolver verifica entrambe le firme. Ma chi dice che queste chiavi appartengono a example.com?","47362, zone-signing (256)":"47362, firma della zona (256)","61845, key-signing (257)":"61845, firma delle chiavi (257)","Keys signed by":"Chiavi firmate da","The key-signing key":"La chiave di firma delle chiavi","two keys":"due chiavi","signed by key 61845":"firmate con la chiave 61845","Vouched by .com":"Garantite da .com","The parent’s DS record":"Il record DS della zona superiore","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"Risponde la zona superiore. I server .com hanno un record DS per example.com: un hash della sua chiave di firma delle chiavi, firmato con la chiave di .com. Se l’hash corrisponde alla chiave 61845, le chiavi sono di example.com, per quanto riguarda .com.","Hash of key 61845":"Hash della chiave 61845","Signed by":"Firmato da",".com (key 19718)":".com (chiave 19718)",Matches:"Corrisponde","hash of key 61845":"hash della chiave 61845","signed by .com":"firmato da .com","Up to the Root":"Fino alla radice","Where the chain ends":"Dove finisce la catena","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Lo stesso vale più in alto: le chiavi di .com sono garantite da un record DS nella zona radice, firmato con la chiave della radice, e quella chiave è integrata in ogni resolver che verifica: l’ancora di fiducia. Il resolver aveva quei collegamenti in cache, quindi la catena è completa: radice → .com → example.com → l’indirizzo.",".com’s key":"La chiave di .com","Vouched for by the root":"Garantita dalla radice","Root’s key":"La chiave della radice","Built in (trust anchor)":"Integrata (ancora di fiducia)","Root → .com → example.com":"Radice → .com → example.com","CHAIN OF TRUST CHECKED":"CATENA DI FIDUCIA VERIFICATA","A Checked Answer":"Una risposta verificata","With the AD flag":"Con il flag AD","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"Il resolver risponde al portatile con l’indirizzo e il flag AD: dati autenticati. Se una qualsiasi firma non fosse tornata, il portatile avrebbe ricevuto un errore (SERVFAIL) invece di un indirizzo falso. DNSSEC non nasconde né la domanda né la risposta; per quello c’è DNS over HTTPS.",Flag:"Flag","AD (authenticated data)":"AD (dati autenticati)","Bad signature":"Firma non valida","SERVFAIL, no address":"SERVFAIL, nessun indirizzo","AD: checked":"AD: verificato","UDP size 1232, DNSSEC OK = 1":"Dimensione UDP 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Dice quanto può essere grande una risposta UDP, e DNSSEC OK: invia anche le firme.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, firmato con la chiave 47362 di example.com, valido dal 2026-10-31 al 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Una firma sui record sopra, fatta con la chiave privata della zona.","example.com, type DNSKEY, class IN":"example.com, tipo DNSKEY, classe IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (chiave di firma della zona 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"Una delle chiavi pubbliche della zona; serve a chi verifica una firma.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (chiave di firma delle chiavi 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, firmato con la chiave 61845 di example.com, valido dal 2026-10-31 al 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, tipo DS, classe IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS chiave 61845, digest SHA-256 (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Un hash della chiave di firma delle chiavi della zona figlia, conservato e firmato dalla zona superiore.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, firmato con la chiave 19718 di com, valido dal 2026-10-31 al 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: risposta, RD (ricorsione richiesta), RA (ricorsione disponibile), AD (dati autenticati)","Wi-Fi Logins":"Accessi al Wi-Fi","EAP over Wi-Fi":"EAP sul Wi-Fi","RADIUS Server":"Server RADIUS","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS e 802.1X (Wi-Fi aziendale)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"A casa tutti condividono una password Wi-Fi. Uffici, università ed eduroam usano invece WPA2- o WPA3-Enterprise: ogni persona o dispositivo accede con il proprio account o certificato, verificato da un server RADIUS. L’access point non conosce password. Passa l’accesso, una serie di messaggi EAP, tra il portatile e il server, e fa entrare il portatile solo quando il server dice sì.","EAP (here EAP-TLS)":"EAP (qui EAP-TLS)",Keys:"Chiavi","Different for every login":"Diverse a ogni accesso","Let in":"Accesso consentito","Its own login, its own keys":"Il suo accesso, le sue chiavi","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"Il portatile ha dimostrato chi era con il suo certificato. Il server RADIUS l’ha verificato e ha detto all’access point di farlo entrare, sulla VLAN 20, con una chiave solo per questo accesso. L’access point non ha mai visto una password: si è limitato a passare i messaggi. Premi RIVEDI per guardarlo di nuovo.","EAP-TLS (certificates)":"EAP-TLS (certificati)","17, then the 4-way handshake":"17, poi l’handshake a 4 vie","20 (staff)":"20 (personale)","A user leaves":"Un utente se ne va","Disable one account":"Disattiva un account","Who Are You?":"Chi sei?","The access point asks for an identity":"L’access point chiede un’identità","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"Il portatile è entrato in «Office», una rete WPA2-Enterprise, ma finché non ha effettuato l’accesso l’access point non lascia passare nulla tranne i messaggi di accesso. Chiede chi è il portatile con una richiesta EAP Identity, e il portatile risponde alex@example.org. L’access point non conosce account: passerà la risposta al server RADIUS.","Before login":"Prima dell’accesso","Only EAP gets through":"Passa solo EAP","IDENTITY?":"IDENTITÀ?","EAP Identity request":"Richiesta EAP Identity",IDENTITY:"IDENTITÀ","Ask RADIUS":"Chiedi a RADIUS","The login goes to the server":"L’accesso va al server","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"L’access point copia il messaggio EAP in un Access-Request RADIUS e lo invia al server RADIUS sulla porta UDP 1812, con l’indirizzo MAC del portatile e il nome della rete. Un segreto condiviso solo tra i due protegge ogni pacchetto. Il server risponde con un Access-Challenge: il prossimo messaggio per il portatile, cioè «avvia EAP-TLS».","RADIUS server, UDP 1812":"Server RADIUS, UDP 1812","A shared secret":"Un segreto condiviso","from the access point":"dall’access point","EAP-TLS start":"avvio EAP-TLS","TLS START":"AVVIO TLS","TLS Inside EAP":"TLS dentro EAP","The server proves who it is":"Il server dimostra chi è","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"Ora il portatile e il server eseguono un handshake TLS 1.3 dentro EAP; l’access point reimpacchetta ogni messaggio, EAPOL via radio e RADIUS sul cavo. Il server invia il suo certificato e chiede quello del portatile. Il portatile verifica che sia stato emesso dall’autorità di certificazione dell’azienda per radius.example.org. È questo controllo che impedisce a un falso access point di catturare l’accesso.","TLS 1.3, inside EAP":"TLS 1.3, dentro EAP","Its certificate":"Il suo certificato","Laptop checks":"Il portatile verifica","Issuer and name":"Emittente e nome","TLS inside EAP":"TLS dentro EAP","certificate (encrypted)":"certificato (cifrato)","Laptop’s Proof":"La prova del portatile","Its own certificate":"Il suo certificato","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"Il portatile risponde con il proprio certificato, emesso dall’azienda per questo utente, e una firma fatta con la sua chiave privata; la chiave non lascia mai il portatile. Non c’è alcuna password. Il server verifica certificato e firma e cerca l’account. Molte reti, eduroam compresa, usano invece una password, inviata dentro il tunnel TLS (PEAP o EAP-TTLS).","Its certificate, a signature":"Il suo certificato, una firma","None with EAP-TLS":"Nessuna con EAP-TLS","Or instead":"Oppure","PEAP: a password in TLS":"PEAP: una password dentro TLS",CERTIFICATE:"CERTIFICATO","laptop’s certificate":"certificato del portatile","Handshake Done":"Handshake finito","Nothing more to send":"Nient’altro da inviare","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Con TLS 1.3 il server invia poi un minuscolo messaggio cifrato, un solo byte a zero, per dire che l’handshake è finito, e il portatile risponde con un messaggio EAP vuoto. Ora entrambi gli estremi hanno gli stessi 64 byte di materiale per le chiavi, ricavati durante l’handshake. Nessuno lungo la strada li ha visti, nemmeno l’access point.","Server sends":"Il server invia","One encrypted 0 byte":"Un byte 0 cifrato","An empty EAP-TLS reply":"Una risposta EAP-TLS vuota","Both hold":"Entrambi hanno","64 bytes of key material":"64 byte di materiale per le chiavi","handshake over":"handshake finito","one encrypted byte":"un byte cifrato",EMPTY:"VUOTO","nothing more":"nient’altro","empty EAP-TLS":"EAP-TLS vuoto","And a key for the access point":"E una chiave per l’access point","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"Il server risponde Access-Accept. Dentro ci sono EAP Success per il portatile; i primi 32 byte del materiale per le chiavi per l’access point, cifrati con il segreto condiviso (MS-MPPE-Recv-Key); e la VLAN 20, così questo utente finisce sulla rete del personale. Lo stesso access point potrebbe mettere un altro utente su un’altra VLAN.","AP gets":"L’AP riceve","The key (MS-MPPE-Recv-Key)":"La chiave (MS-MPPE-Recv-Key)","key, VLAN 20":"chiave, VLAN 20","4-Way Handshake":"Handshake a 4 vie","As at home, from a different key":"Come a casa, da una chiave diversa","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Ora l’access point e il portatile hanno la stessa chiave di 32 byte, la PMK. Segue l’handshake a 4 vie della lezione sul Wi-Fi; cambia solo l’origine della PMK. A casa viene dalla password condivisa, qui da questo singolo accesso, quindi ogni utente ottiene chiavi diverse.","PMK from":"PMK da","This login":"Questo accesso","At home":"A casa","From the shared password":"Dalla password condivisa","Encrypted data (CCMP)":"Dati cifrati (CCMP)","group key, MIC":"chiave di gruppo, MIC","Why Enterprise":"Perché Enterprise","One account per person":"Un account per persona","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Quando qualcuno se ne va, il suo account viene disattivato e nessun altro cambia una password. Ogni accesso ha le sue chiavi, quindi gli utenti non possono leggere il traffico degli altri, e il server RADIUS registra chi si è collegato e quando. eduroam funziona allo stesso modo: l’accesso di un ospite per utente@la-sua-università passa da un server RADIUS all’altro finché non raggiunge la sua università.","Different for every user":"Diverse per ogni utente",eduroam:"eduroam","Login passed home":"Accesso inoltrato a casa","ONE ACCOUNT PER PERSON":"UN ACCOUNT PER PERSONA","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, certificato","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, handshake cifrato","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: handshake cifrato","Access-Request id=83: encrypted handshake":"Access-Request id=83: handshake cifrato","0 (EAP packet)":"0 (pacchetto EAP)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Porta un messaggio EAP. L’access point lo copia in un pacchetto RADIUS per il server, e viceversa.","A response carries the same number as the request it answers.":"Una risposta porta lo stesso numero della richiesta a cui risponde.","Who are you?":"Chi sei?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Chi sta accedendo. Il realm dopo la @ dice al server RADIUS (o ai server che inoltrano le richieste) dove si trova l’account.","Seen on the office network":"Visto sulla rete dell’ufficio","The server. It is on the same network, so the frame goes straight to it, not through the router.":"Il server. È sulla stessa rete, quindi il frame va direttamente a lui, non attraverso il router.","The access point’s wired port.":"La porta cablata dell’access point.","Should this device be let in?":"Questo dispositivo va fatto entrare?","A reply carries the number of the request it answers.":"Una risposta porta il numero della richiesta a cui risponde.",Authenticator:"Autenticatore","Random, new in every request.":"Casuale, nuovo a ogni richiesta.",Attributes:"Attributi","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"Un HMAC-MD5 dell’intero pacchetto, calcolato con il segreto condiviso. Ogni pacchetto che porta EAP deve averne uno; dall’attacco Blast-RADIUS del 2024, va messo per primo.","The identity the laptop gave.":"L’identità fornita dal portatile.","The access point asking.":"L’access point che chiede.","The access point’s MAC address and the network’s name.":"L’indirizzo MAC dell’access point e il nome della rete.","The laptop’s MAC address.":"L’indirizzo MAC del portatile.","Keep each EAP message small enough for one frame.":"Tiene ogni messaggio EAP abbastanza piccolo da stare in un frame.","The EAP packet, passed on unchanged.":"Il pacchetto EAP, passato invariato.","The server’s network card.":"La scheda di rete del server.","Not yet: here is the next message for the device.":"Non ancora: ecco il prossimo messaggio per il dispositivo.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Un hash di questa risposta, dell’autenticatore della richiesta e del segreto condiviso: solo il vero server può averlo creato.","A TLS handshake, carried inside EAP.":"Un handshake TLS, trasportato dentro EAP.","0x20 (start)":"0x20 (avvio)","Start: the server is ready for the laptop’s Client Hello.":"Avvio: il server è pronto per il Client Hello del portatile.","The server’s bookmark for this login: the access point sends it back with the next request.":"Il segnalibro del server per questo accesso: l’access point lo rimanda con la richiesta successiva.","0x80 (length included)":"0x80 (lunghezza inclusa)","TLS length":"Lunghezza TLS","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"I messaggi TLS più lunghi vengono divisi in pezzi di circa 1,000 byte, ognuno confermato.","TLS records":"Record TLS","The same TLS records as over TCP, only carried in EAP.":"Gli stessi record TLS che su TCP, solo trasportati in EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, la condivisione di chiave del portatile","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Il pacchetto EAP (1,008 byte), diviso su 4 attributi di al massimo 253 byte.","EAP-Message, continued":"EAP-Message, continua","TLS records, continued":"Record TLS, continua","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, la condivisione di chiave del server","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Cifrati: certificato per radius.example.org, una richiesta del certificato del portatile, firma, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Cifrati: il certificato del portatile (per alex@example.org), la sua firma, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Il pacchetto EAP (822 byte), diviso su 4 attributi di al massimo 253 byte.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Cifrato: un byte 0, il «messaggio di impegno»: niente più messaggi di handshake","0x00 (no data)":"0x00 (nessun dato)","Nothing to send: an empty answer that keeps the conversation going.":"Niente da inviare: una risposta vuota che fa proseguire la conversazione.","Yes: let it in.":"Sì: fallo entrare.","Put this device on VLAN 20, the staff network.":"Metti questo dispositivo sulla VLAN 20, la rete del personale.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"I primi 32 byte del materiale per le chiavi che entrambi gli estremi dell’handshake TLS hanno ricavato. L’access point lo usa come PMK, la chiave di partenza dell’handshake a 4 vie.","Salt, encrypted key":"Salt, chiave cifrata","Encrypted with the shared secret, so only the access point can read the key.":"Cifrata con il segreto condiviso, così solo l’access point può leggere la chiave.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"I successivi 32 byte del materiale per le chiavi. Al Wi-Fi non servono.","The RADIUS server accepted the login.":"Il server RADIUS ha accettato l’accesso.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (accessi verificati da un server RADIUS)","Shared Folders":"Cartelle condivise",Responses:"Risposte","nas (File Server)":"nas (file server)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"SMB è il modo in cui Windows condivide file e stampanti: \\\\server\\share in Esplora file, un’unità di rete mappata, un NAS in casa. Lo parlano anche macOS e Linux. Su una sola connessione TCP verso la porta 445 il client concorda una versione, accede e si collega a una condivisione, poi apre, legge, scrive e chiude file con richieste numerate.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM o Kerberos",Protection:"Protezione","Signing, optional encryption":"Firma, cifratura facoltativa","File read":"File letto","Seven requests, one connection":"Sette richieste, una connessione","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Su una sola connessione TCP il portatile ha concordato SMB 3.1.1, ha effettuato l’accesso con NTLM senza inviare la password, si è collegato alla condivisione e ha letto un file di 240 KB con una sola richiesta. Ogni messaggio dopo l’accesso era firmato. Premi RIVEDI per guardarlo di nuovo.","7 on one connection":"7 su una connessione","NTLMv2, no password sent":"NTLMv2, nessuna password inviata","240 KB in 169 segments":"240 KB in 169 segmenti",Signed:"Firmato","Every message after login":"Ogni messaggio dopo l’accesso","Port 445":"Porta 445","A TCP connection to the NAS":"Una connessione TCP verso il NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"Il portatile apre \\\\nas\\Documents, una cartella condivisa sul NAS. Trova l’indirizzo di nas con una ricerca di nomi locale e apre una connessione TCP verso la porta 445. I pacchetti passano dal router di casa al NAS e non lasciano mai la rete di casa.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Resta","On the home network":"Sulla rete di casa",Negotiate:"Negotiate","Agree on a version":"Accordo su una versione","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"Il portatile elenca ogni versione di SMB che parla, da 2.0.2 a 3.1.1, e dice che richiede la firma. Il NAS sceglie 3.1.1, la più recente. Entrambi i lati tengono un hash SHA-512 di tutto ciò che si scambiano da qui fino alla fine dell’accesso. Entra nelle chiavi, quindi se qualcuno modificasse questi messaggi lungo la strada, per esempio per forzare una versione più vecchia, l’accesso fallirebbe.",Chosen:"Scelta","Tamper check":"Controllo manomissioni","SHA-512 of the exchange":"SHA-512 dello scambio","signing required":"firma obbligatoria","NTLM Challenge":"Challenge NTLM","The NAS sends a random number":"Il NAS invia un numero casuale","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"Un NAS di casa non ha un dominio, quindi niente Kerberos: il portatile accede con NTLM. Il suo primo SESSION_SETUP dice che vuole accedere, e il NAS risponde «serve altra elaborazione» con una challenge di 8 byte casuali. Assegna anche a questo accesso un ID di sessione.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (in un dominio: Kerberos)",Challenge:"Challenge","More processing required":"Serve altra elaborazione","NTLM: let me log in":"NTLM: fammi accedere","a session ID":"un ID di sessione","NTLM Response":"Risposta NTLM","Proof, not the password":"Una prova, non la password","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"Il portatile risponde con il nome utente, alex, e una risposta NTLMv2: un HMAC della challenge e di pochi altri valori, calcolato con un hash della password. Il NAS ha lo stesso hash e ricava lo stesso valore. La password non attraversa mai la rete, e ora entrambi i lati hanno una chiave di sessione con cui firmare i messaggi.",User:"Utente",alex:"alex",Sends:"Invia","An HMAC of the challenge":"Un HMAC della challenge","Never sent":"Mai inviata","user alex":"utente alex","NTLMv2 response":"risposta NTLMv2","LOGGED IN":"ACCESSO EFFETTUATO",signed:"firmato","Connect a Share":"Collegarsi a una condivisione","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT chiede la condivisione con il suo nome completo, \\\\nas\\Documents. La risposta le assegna un tree ID e dice cosa può fare lì questo utente. Ogni messaggio ora è firmato: ognuno porta un tag sull’intero messaggio, fatto con una chiave dell’accesso, così un messaggio modificato o falsificato verrebbe scoperto.",Share:"Condivisione","Every message":"Ogni messaggio","Signed (AES-GMAC)":"Firmato (AES-GMAC)","tree ID 0x2a51":"tree ID 0x2a51","Open the File":"Apri il file","With CREATE":"Con CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB apre i file con CREATE, che può anche crearne di nuovi. Questo apre report.pdf in lettura e fallisce se non esiste. La risposta dà dimensione e date del file, e un file ID che useranno la lettura e la chiusura.",Handle:"Handle","A 16-byte file ID":"Un file ID di 16 byte","open to read":"apri in lettura","file ID":"file ID","Read It":"Leggilo","The whole file in one request":"L’intero file in una richiesta","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Un solo READ chiede l’intero file, 245,760 byte dall’offset 0. Costa 4 crediti, uno ogni 64 KB. La risposta è fatta di 80 byte di intestazioni e poi il file, in 169 segmenti TCP. Un file più grande si legge con più richieste, molte in viaggio insieme, per quanto consentono i crediti.","245,760 bytes from 0":"245,760 byte da 0",Credits:"Crediti","4 (one per 64 KB)":"4 (uno ogni 64 KB)","Arrives in":"Arriva in","from offset 0":"dall’offset 0","Close the File":"Chiudi il file","And keep 445 at home":"E tieni la 445 in casa","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE restituisce il file ID; la connessione resta aperta per il file successivo. SMB 3 può anche cifrare ogni messaggio con AES-GCM, per una condivisione o un intero server. Qui protegge i messaggi solo la firma, quindi chiunque sulla rete potrebbe leggere il file mentre passa. La porta 445 non dovrebbe mai essere raggiungibile da Internet: il worm WannaCry (2017) si è diffuso attraverso una falla nel vecchio SMB1.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, facoltativo","Switched off: old, unsafe":"Disattivato: vecchio, insicuro","Never open to the internet":"Mai aperto verso Internet",done:"fatto","KEEP PORT 445 OFF THE INTERNET":"TIENI LA PORTA 445 LONTANA DA INTERNET","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Sulla porta 445 ogni messaggio SMB inizia con la sua lunghezza, un residuo di NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 o 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'I messaggi SMB1 iniziavano con 0xFF "SMB". Oggi SMB1 è disattivato in Windows.',"Header size":"Dimensione dell’intestazione","Credit charge":"Costo in crediti","Channel sequence":"Sequenza del canale","Credits asked for":"Crediti richiesti","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"I crediti limitano quante richieste il portatile può avere in attesa insieme. Li distribuisce il server.","Next command":"Comando successivo","0 (none chained)":"0 (nessuno concatenato)","Counts up with each request; the response carries the same number.":"Aumenta a ogni richiesta; la risposta porta lo stesso numero.","0 (no share yet)":"0 (ancora nessuna condivisione)","Session ID":"ID di sessione","0 (not logged in yet)":"0 (accesso non ancora effettuato)","zeros (not signed)":"zeri (non firmato)","Structure size":"Dimensione della struttura","Dialect count":"Numero di dialetti","Security mode":"Modalità di sicurezza","0x0002 (signing required)":"0x0002 (firma obbligatoria)","Recent versions of Windows 11 require signing by default.":"Le versioni recenti di Windows 11 richiedono la firma per impostazione predefinita.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, lease, letture e scritture grandi, multicanale, handle persistenti, lease di directory, cifratura.","Client GUID":"GUID del client","A random ID for this computer.":"Un ID casuale per questo computer.","Negotiate contexts":"Contesti di negoziazione","at offset 112, 4 of them":"all’offset 112, 4 in tutto",Dialects:"Dialetti","Every version the laptop speaks. The server picks the newest it also knows.":"Ogni versione che il portatile parla. Il server sceglie la più recente che conosce anche lui.",Contexts:"Contesti","SMB 3.1.1 extras, each in its own small block.":"Extra di SMB 3.1.1, ciascuno nel suo piccolo blocco.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Integrità pre-autenticazione: SHA-512, e un salt casuale di 32 byte","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Cifratura: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Firma: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"Il nome del server: nas","Credits granted":"Crediti concessi","0x00000001 (response)":"0x00000001 (risposta)","0x0001 (signing enabled)":"0x0001 (firma abilitata)",Dialect:"Dialetto","The newest version both sides speak.":"La versione più recente che entrambi i lati parlano.","Context count":"Numero di contesti","Server GUID":"GUID del server","Leases, large reads and writes.":"Lease, letture e scritture grandi.","Largest read, write":"Lettura, scrittura massime","8 MB each":"8 MB ciascuna","The most data one request may carry: transactions, reads and writes.":"Il massimo di dati che una richiesta può portare: transazioni, letture e scritture.","System time":"Ora di sistema","7 Nov 2026, 09:41:00":"7 nov 2026, 09:41:00","Security buffer":"Buffer di sicurezza","Context offset":"Offset dei contesti","Security blob":"Blob di sicurezza","GSS-API and SPNEGO wrapping, around NTLMSSP.":"Involucro GSS-API e SPNEGO, intorno a NTLMSSP.","The login methods the server accepts: NTLMSSP":"I metodi di accesso che il server accetta: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Integrità pre-autenticazione: SHA-512, e il salt del server","Encryption: AES-128-GCM":"Cifratura: AES-128-GCM","Signing: AES-GMAC":"Firma: AES-GMAC","0x02 (signing required)":"0x02 (firma obbligatoria)","Previous session":"Sessione precedente","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: le opzioni NTLM che il portatile supporta","Not an error: the login needs another round.":"Non è un errore: l’accesso richiede un altro giro.","The server’s number for this login, from now on in every message.":"Il numero del server per questo accesso, d’ora in poi in ogni messaggio.","Session flags":"Flag di sessione","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: una challenge casuale di 8 byte","The NAS’s names and its clock":"I nomi del NAS e il suo orologio","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: utente alex, computer ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"Risposta NTLMv2: un HMAC della challenge, calcolato con un hash della password","A key for signing, encrypted":"Una chiave per la firma, cifrata","0x00000009 (response, signed)":"0x00000009 (risposta, firmata)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC sull’intero messaggio, con una chiave dell’accesso: un messaggio modificato o falsificato verrebbe scoperto.","The login is complete.":"L’accesso è completato.","0x00000008 (signed)":"0x00000008 (firmato)","Server and share name, in UTF-16.":"Nome del server e della condivisione, in UTF-16.","The number for this share; later requests carry it.":"Il numero di questa condivisione; le richieste successive lo riportano.","Share type":"Tipo di condivisione","1 (disk)":"1 (disco)","Share flags":"Flag della condivisione","Encryption not required for this share; signing still protects every message.":"Cifratura non richiesta per questa condivisione; la firma protegge comunque ogni messaggio.","0x001f01ff (full control)":"0x001f01ff (controllo completo)","What this user may do in the share.":"Cosa può fare questo utente nella condivisione.","Oplock, impersonation":"Oplock, impersonificazione","none, 2 (impersonation)":"nessuno, 2 (impersonificazione)","Desired access":"Accesso desiderato","0x00120089 (read)":"0x00120089 (lettura)","Read the data, its attributes and its permissions.":"Leggere i dati, i loro attributi e i permessi.","File attributes":"Attributi del file","Share access":"Accesso condiviso","0x00000001 (read)":"0x00000001 (lettura)","Others may read the file while it is open, but not change it.":"Altri possono leggere il file mentre è aperto, ma non modificarlo.",Disposition:"Disposizione","1 (open, fail if missing)":"1 (apri, fallisci se manca)","0x00000040 (a file, not a folder)":"0x00000040 (un file, non una cartella)",Name:"Nome","Create contexts":"Contesti di creazione","File name":"Nome del file","Relative to the share.":"Relativo alla condivisione.","Oplock, flags":"Oplock, flag","none, 0":"nessuno, 0",Action:"Azione","1 (opened)":"1 (aperto)",Times:"Orari","created, accessed, written, changed":"creazione, accesso, scrittura, modifica","Windows FILETIME: 100-nanosecond steps since 1601.":"FILETIME di Windows: passi da 100 nanosecondi dal 1601.","Allocation size":"Dimensione allocata","File size":"Dimensione del file","0x00000020 (archive)":"0x00000020 (archivio)","File ID":"File ID","The handle for the open file: reads and the close name it.":"L’handle del file aperto: le letture e la chiusura lo nominano.","A big read costs one credit per 64 KB.":"Una lettura grande costa un credito ogni 64 KB.","Padding, flags":"Riempimento, flag","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Dove il server deve mettere i dati nella sua risposta: a 80 byte dall’inizio, subito dopo le intestazioni.","The whole file in one request.":"L’intero file in una richiesta.","Minimum, channel, remaining":"Minimo, canale, restante","Channel info":"Informazioni sul canale","Data offset":"Offset dei dati","Data length":"Lunghezza dei dati","Remaining, flags":"Restante, flag","The file itself; its contents are not part of the lesson.":"Il file stesso; il suo contenuto non fa parte della lezione.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"Il portatile non ha chiesto i dettagli del file, quindi il resto è a zero.","Times, sizes, attributes":"Orari, dimensioni, attributi","Talking to a PLC":"Parlare con un PLC",Switch:"Switch","Plant network":"Rete dell’impianto","Modbus/TCP, for industrial control":"Modbus/TCP, per il controllo industriale","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus è uno dei protocolli più vecchi e diffusi nel controllo industriale (OT, tecnologia operativa): lo parlano PLC, sensori, azionamenti di motori e contatori in fabbriche, acquedotti ed edifici. Un client legge e scrive registri e coil numerati su un dispositivo. Modbus/TCP porta gli stessi piccoli messaggi sulla porta TCP 502, senza accesso e senza cifratura.","1979, by Modicon":"1979, da Modicon","16-bit registers, on/off coils":"Registri a 16 bit, coil acceso/spento","None built in":"Nessuna integrata","Modbus.org specifications":"Specifiche di Modbus.org","Pump running":"Pompa in funzione","Simple, and wide open":"Semplice, e completamente aperto","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"Il portatile ha letto quattro registri, cambiato un setpoint e avviato una pompa, ognuno con una richiesta di 12 byte e una breve risposta. Nessun messaggio portava una password e nessuno era cifrato: Modbus si fida di chiunque riesca a raggiungerlo, quindi a proteggerlo deve pensarci la rete intorno. Premi RIVEDI per guardarlo di nuovo.","4 requests, 4 answers":"4 richieste, 4 risposte",Biggest:"Il più grande","17 bytes (the read answer)":"17 byte (la risposta di lettura)","Protect with":"Proteggere con","Separate networks":"Reti separate","Port 502":"Porta 502","A TCP connection to the PLC":"Una connessione TCP verso il PLC","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"Un PLC (controllore logico programmabile) gestisce una piccola stazione di pompaggio: legge i sensori e accende le pompe. Il portatile di un tecnico sulla rete dell’impianto gli parla in Modbus/TCP, quindi apre una connessione TCP verso la porta 502. Nei termini di Modbus il portatile è il client e il PLC il server.",Roles:"Ruoli","Client asks, server answers":"Il client chiede, il server risponde","Read Registers":"Leggi i registri","Function 3: four numbers":"Funzione 3: quattro numeri","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"Il portatile chiede 4 holding register a partire dall’indirizzo 0, con il codice funzione 3. Il PLC risponde con 8 byte: quattro numeri a 16 bit. Cosa significano (il livello del serbatoio in centimetri, la temperatura in decimi di grado) è scritto solo nella documentazione del PLC; il messaggio non porta nomi né unità. Uno schermo HMI invia letture come questa circa ogni secondo.",Function:"Funzione","4 registers from 0":"4 registri da 0","function 3":"funzione 3","registers 0–3":"registri 0–3",VALUES:"VALORI","Write a Setpoint":"Scrivi un setpoint","Function 6: one register":"Funzione 6: un registro","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"Il tecnico alza il setpoint di livello del serbatoio da 4.50 m a 5.00 m: funzione 6, scrittura di un singolo registro, registro 3, valore 500. Il PLC risponde ripetendo la richiesta, che significa fatto. D’ora in poi il suo programma tiene il serbatoio più pieno.","Register 3":"Registro 3","The request, repeated":"La richiesta, ripetuta",WRITE:"SCRITTURA","register 3 = 500":"registro 3 = 500","Start a Pump":"Avvia una pompa","Function 5: a coil":"Funzione 5: un coil","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"I coil sono singole uscite acceso/spento. La funzione 5 ne scrive uno: coil 0, pompa 2, valore 0xFF00, che significa acceso. Il PLC accende la pompa e ripete la richiesta. In un impianto reale di solito lo decide il programma del PLC stesso, con interblocchi di sicurezza.","Coil 0":"Coil 0","Pump 2: on":"Pompa 2: accesa","0xFF00 (off: 0x0000)":"0xFF00 (spenta: 0x0000)","COIL ON":"COIL ACCESO","coil 0: pump 2":"coil 0: pompa 2","pump 2 on":"pompa 2 accesa","PUMP 2 RUNNING":"POMPA 2 IN FUNZIONE","An Exception":"Un’eccezione","No such register":"Registro inesistente","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Una richiesta di registri che non esistono, qui 100 e 101, riceve un’eccezione: il codice funzione con il bit più alto attivo (3 + 128 = 131) e il codice di eccezione 2, indirizzo dati non valido. Altri codici dicono che la funzione non è supportata o che il dispositivo è occupato.",Exception:"Eccezione",Means:"Significa","No register there":"Nessun registro lì","registers 100–101":"registri 100–101",EXCEPTION:"ECCEZIONE","code 2: no such register":"codice 2: registro inesistente","No Security":"Nessuna sicurezza","Anyone who can reach it":"Chiunque riesca a raggiungerlo","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Niente in questi messaggi dice chi li ha inviati: Modbus, del 1979, non ha accesso né cifratura, quindi qualsiasi dispositivo che raggiunga la porta 502 può leggere i valori e avviare la pompa. Gli impianti lo proteggono con reti separate, firewall tra ufficio e impianto, elenchi di chi può parlare con ogni PLC e monitoraggio. Modbus/TCP Security avvolge gli stessi messaggi in TLS, sulla porta 802.","Separate networks, TLS":"Reti separate, TLS","NO LOGIN, NO ENCRYPTION":"NIENTE ACCESSO, NIENTE CIFRATURA","Seen on the plant network":"Visto sulla rete dell’impianto","Picked by the client; the answer carries the same number.":"Scelto dal client; la risposta porta lo stesso numero.","Protocol ID":"ID protocollo","The unit ID and everything after it.":"L’ID unità e tutto ciò che segue.","Unit ID":"ID unità","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Quale dispositivo. Conta quando un gateway inoltra le richieste a dispositivi su una linea seriale.","Function code":"Codice funzione","Starting address":"Indirizzo iniziale","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus conta da 0, anche se i manuali spesso numerano lo stesso registro da 40001 in su.",Quantity:"Quantità","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, risposta","The same number as the request.":"Lo stesso numero della richiesta.","Byte count":"Numero di byte","Register 0":"Registro 0","412 (tank level, 4.12 m)":"412 (livello del serbatoio, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"Semplici numeri a 16 bit. Cosa significa ciascuno è scritto nella documentazione del PLC, non nel messaggio.","Register 1":"Registro 1","183 (temperature, 18.3 °C)":"183 (temperatura, 18.3 °C)","Register 2":"Registro 2","1450 (pump speed, 1,450 rpm)":"1450 (velocità della pompa, 1,450 giri/min)","450 (level setpoint, 4.50 m)":"450 (setpoint di livello, 4.50 m)","Register address":"Indirizzo del registro","3 (level setpoint)":"3 (setpoint di livello)",Value:"Valore","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, risposta","The answer repeats the request: done.":"La risposta ripete la richiesta: fatto.","Coil address":"Indirizzo del coil","0 (pump 2)":"0 (pompa 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Un coil è una singola uscita acceso/spento. 0xFF00 lo accende.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, risposta","Modbus/TCP · exception":"Modbus/TCP · eccezione","131 (3 + 128: an exception)":"131 (3 + 128: un’eccezione)","The top bit set: the request failed.":"Il bit più alto attivo: la richiesta è fallita.","Exception code":"Codice di eccezione","There is no register at that address.":"Non c’è nessun registro a quell’indirizzo.","Internet Routes":"Rotte di Internet",Routes:"Rotte","The laptop’s packets":"I pacchetti del portatile","Border Gateway Protocol":"Border Gateway Protocol","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Internet è una rete di reti: decine di migliaia, gestite da provider Internet, cloud, università e aziende, ognuna con il proprio numero AS. BGP è il modo in cui i loro router di confine si dicono a vicenda quali indirizzi possono raggiungere. Ogni router passa avanti ciò che impara aggiungendo il proprio numero, così ogni rete si costruisce la propria mappa dei percorsi verso ogni indirizzo di Internet.",Between:"Tra","Networks (ASes)":"Reti (AS)",Table:"Tabella","About a million IPv4 routes":"Circa un milione di rotte IPv4","Path choice":"Scelta del percorso","Policy, then shortest":"Politica, poi il più corto","Route learned":"Rotta appresa","Announced, passed on, used":"Annunciata, passata avanti, usata","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"La rete di hosting ha annunciato i suoi indirizzi, la rete di transito li ha passati avanti aggiungendo il proprio numero, e il router del provider ha usato quel percorso per i pacchetti del portatile. Quando la rotta è stata ritirata, la notizia si è diffusa allo stesso modo. Non c’è una mappa centrale: ogni rete si costruisce la propria da ciò che dicono i vicini. Premi RIVEDI per guardarlo di nuovo.",Map:"Mappa","Each network makes its own":"Ogni rete fa la propria","RPKI and filters":"RPKI e filtri","Many Networks":"Tante reti","Each with its own number":"Ognuna con il suo numero","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Internet è fatto di oltre 75,000 reti separate, chiamate sistemi autonomi (AS): provider Internet, cloud, università, grandi aziende, ognuna con un numero. Eccone tre: il provider del portatile (AS 64500), una rete di transito che trasporta il traffico altrui (AS 64510) e la rete di hosting di www.example.com (AS 64511). BGP è il modo in cui i loro router si dicono dove si può raggiungere ogni indirizzo.",Networks:"Reti","More than 75,000 ASes":"Oltre 75,000 AS",Here:"Qui","3 ASes, a router each":"3 AS, un router ciascuno",Numbers:"Numeri","TCP to port 179":"TCP verso la porta 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"I router BGP non si scoprono da soli: i tecnici ai due capi li configurano come vicini. Il router del provider apre una connessione TCP verso il router di transito sulla porta 179. Sono collegati direttamente, quindi i loro pacchetti partono con un TTL di 1: non possono attraversare nemmeno un altro router, così la sessione funziona solo tra vicini diretti.",Neighbours:"Vicini","Set up by hand":"Configurati a mano","1: the next router only":"1: solo il router successivo","OPEN, then KEEPALIVE":"OPEN, poi KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Ogni router invia un OPEN: il suo numero AS, un hold time di 180 secondi, il suo ID router e ciò che supporta, come i numeri AS a 4 byte. Ciascuno risponde con un KEEPALIVE, e la sessione è stabilita. Da qui in poi parte un KEEPALIVE ogni 60 secondi quando non c’è altro da inviare; dopo 180 secondi di silenzio la sessione verrebbe chiusa.","AS, hold time, ID":"AS, hold time, ID","KEEPALIVE: established":"KEEPALIVE: stabilita","Hold time":"Hold time","hold 180 s":"hold 180 s","SESSION ESTABLISHED":"SESSIONE STABILITA","Announce a Route":"Annuncia una rotta","The hosting network: “I have these”":"La rete di hosting: «ho questi»","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"Il router della rete di hosting annuncia 203.0.113.0/24, i 256 indirizzi che includono www.example.com, alla rete di transito, che paga perché trasporti il suo traffico. L’UPDATE dice come arrivarci: AS_PATH 64511, per ora solo la sua rete, e NEXT_HOP, il suo indirizzo sul collegamento tra loro.","path 64511":"percorso 64511","Passed On":"Passata avanti","Each network adds its number":"Ogni rete aggiunge il suo numero","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"Il router di transito accetta la rotta e la passa agli altri vicini, tra cui il provider, con il proprio numero aggiunto in testa: AS_PATH 64510 64511, e se stesso come prossimo salto. Il router del provider può sentire parlare dello stesso prefisso da più vicini. Ne sceglie uno prima in base alla propria politica (per esempio le rotte attraverso clienti paganti prima delle altre), poi in base al percorso AS più corto.","Best path":"Percorso migliore","path 64510 64511":"percorso 64510 64511","ROUTE TO 203.0.113.0/24":"ROTTA VERSO 203.0.113.0/24","Follow the Route":"Segui la rotta","Packets go where BGP said":"I pacchetti vanno dove ha detto BGP","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Quando il portatile si collega a www.example.com (con l’indirizzo trovato dal DNS come al solito), i suoi pacchetti arrivano al provider, il cui router ora manda tutto ciò che è diretto a 203.0.113.0/24 al router di transito, che lo inoltra alla rete di hosting. La risposta torna per la rotta che la rete di hosting ha scelto verso il provider del portatile: su Internet la via del ritorno è spesso diversa da quella dell’andata.","Way back":"Via del ritorno","Chosen separately":"Scelta separatamente","the way back":"la via del ritorno",Withdrawn:"Ritirata","Routes can be taken back":"Le rotte si possono ritirare","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Più tardi la rete di hosting ritira il prefisso, come farebbe se un collegamento cadesse: un UPDATE che lo elenca tra le rotte ritirate. Il router di transito lo passa avanti, e in un tempo tra secondi e minuti le reti di tutto il mondo dimenticano il percorso. Una sessione che resta in silenzio oltre il suo hold time perde tutte le sue rotte in una volta. Nel 2021 Facebook ha ritirato le rotte verso i propri server DNS ed è sparito da Internet per sei ore.","Spreads in":"Si diffonde in","Seconds to minutes":"Da secondi a minuti","Session lost":"Sessione persa","All its routes go":"Spariscono tutte le sue rotte",WITHDRAW:"RITIRO","Trust Problems":"Problemi di fiducia","BGP believes its neighbours":"BGP crede ai vicini","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Un router accetta ciò che annunciano i vicini. Una rete che annuncia indirizzi non suoi, per errore o di proposito, attira verso di sé il loro traffico: nel 2008 un provider pakistano ha messo offline YouTube in tutto il mondo proprio così. Con RPKI chi detiene un prefisso firma quale AS può annunciarlo, e i router che lo verificano scartano ogni altro. I filtri su ciò che ogni vicino può annunciare fanno il resto.",Risk:"Rischio","Hijacks and leaks":"Dirottamenti e fughe","Signed: who may announce":"Firmato: chi può annunciare",Also:"Inoltre","Filters per neighbour":"Filtri per vicino","CHECK WHO MAY ANNOUNCE":"VERIFICA CHI PUÒ ANNUNCIARE","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: ritirata 203.0.113.0/24",Marker:"Marcatore","16 bytes of 0xFF":"16 byte di 0xFF","All ones: where a message starts.":"Tutti uno: dove inizia un messaggio.","The first message on a session: who this router is and what it supports.":"Il primo messaggio di una sessione: chi è questo router e cosa supporta.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"La rete di questo router. (Un numero AS a 4 byte va nella capability qui sotto, con 23456 qui.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Se per tanto tempo non arriva proprio nulla, la sessione viene chiusa. Entrambi i lati usano l’offerta più bassa.","BGP identifier":"Identificativo BGP","The router’s ID, usually one of its addresses.":"L’ID del router, di solito uno dei suoi indirizzi.","Optional parameters":"Parametri facoltativi","parameter 2, 14 bytes":"parametro 2, 14 byte","What this router can do beyond the basics.":"Cosa sa fare questo router oltre le basi.",Multiprotocol:"Multiprotocollo","Which kinds of routes it will exchange on this session.":"Quali tipi di rotte scambierà in questa sessione.","Route refresh":"Aggiornamento delle rotte","It can ask the other side to send all its routes again.":"Può chiedere all’altro lato di reinviare tutte le sue rotte.","4-byte AS numbers":"Numeri AS a 4 byte","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"I numeri AS a 2 byte stavano finendo, quindi quelli nuovi sono lunghi 4 byte.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Solo l’intestazione: «ci sono ancora». Inviato quando non c’è altro da dire, ogni terzo dell’hold time.","Routes: paths to new addresses, and ones taken back.":"Rotte: percorsi verso nuovi indirizzi, e quelli ritirati.","Withdrawn routes":"Rotte ritirate","Path attributes":"Attributi del percorso","0 (IGP: from inside the network that announced it)":"0 (IGP: dall’interno della rete che l’ha annunciata)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Ogni rete attraversata dalla rotta, la più recente per prima. A parità di altre condizioni vince il percorso più corto; un router che ci trova il proprio numero scarta la rotta, così le rotte non possono girare in tondo.","Send packets for these addresses to this router.":"Invia i pacchetti per questi indirizzi a questo router.",Reachable:"Raggiungibili","The addresses this route leads to: a prefix, here 256 addresses.":"Gli indirizzi a cui porta questa rotta: un prefisso, qui 256 indirizzi.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (ritiro)","These addresses can no longer be reached through this router.":"Questi indirizzi non si possono più raggiungere attraverso questo router.","A Video Call":"Una videochiamata",Signalling:"Segnalazione","STUN and ICE":"STUN e ICE",Media:"Media","STUN Server":"Server STUN","Sam’s Router":"Router di Sam","Sam’s Laptop":"Portatile di Sam","Web Real-Time Communication":"Web Real-Time Communication","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"WebRTC permette a due browser di chiamarsi, con audio, video e dati che vanno direttamente dall’uno all’altro, non attraverso un server. Un server si limita a presentarli: si scambiano descrizioni di cosa possono inviare e dove si possono raggiungere (segnalazione), trovano un passaggio attraverso entrambi i router di casa con ICE e STUN, cifrano con DTLS e inviano i media su UDP come SRTP.","Media over":"Media su","Always on":"Sempre attiva","Works in":"Funziona in","Every major browser":"Tutti i principali browser","W3C; RFC 8825 and others":"W3C; RFC 8825 e altre","On the call":"In chiamata","Introduced by a server, then direct":"Presentati da un server, poi diretti","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"Il server di segnalazione ha passato l’offerta e la risposta tra i due browser, un server STUN ha detto al portatile il suo indirizzo pubblico e un controllo ICE ha trovato un passaggio attraverso entrambi i router di casa. Dopo un handshake DTLS, audio e video cifrati sono andati direttamente da un portatile all’altro. Premi RIVEDI per guardarlo di nuovo.","Via call.example.com":"Tramite call.example.com","Media path":"Percorso dei media","Direct, through 2 NATs":"Diretto, attraverso 2 NAT","DTLS, then SRTP":"DTLS, poi SRTP","If blocked":"Se bloccato","A TURN relay":"Un relay TURN","Join the Call":"Entra nella chiamata","Through a signalling server":"Tramite un server di segnalazione","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"Il portatile apre una pagina di chiamata su call.example.com, e la pagina tiene aperto un WebSocket verso il server, dentro TLS. Entra nella stanza 42, dove Sam sta già aspettando. Il server passerà i messaggi tra i due browser. WebRTC non dice come: ogni app fa questa segnalazione a modo suo.","The app’s own server":"Il server dell’app","A WebSocket in TLS":"Un WebSocket in TLS",Room:"Stanza","42, with Sam":"42, con Sam",JOIN:"ENTRA","room 42":"stanza 42","SAM IS HERE":"SAM È QUI","peer: Sam":"interlocutore: Sam","Public Address?":"Indirizzo pubblico?","Ask a STUN server":"Chiedi a un server STUN","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Dietro il router di casa il portatile conosce solo il suo indirizzo privato, 192.168.1.10, che nessuno su Internet può raggiungere. Quindi chiede a un server STUN indicato nelle impostazioni della pagina di chiamata, con una piccola richiesta UDP. La risposta dice da dove sembrava arrivare la richiesta, 198.51.100.7 porta 61022: l’indirizzo pubblico del router e la porta che il suo NAT ha aperto per questa conversazione.",Public:"Pubblico","what is my address?":"qual è il mio indirizzo?","YOUR ADDRESS":"IL TUO INDIRIZZO","The Offer":"L’offerta","An SDP description, via the server":"Una descrizione SDP, tramite il server","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"Il browser scrive un’offerta in SDP: i media che vuole inviare (audio Opus; video in VP8, H.264 e altri), l’impronta del suo certificato DTLS, il suo nome utente e la password ICE, e i suoi candidati, gli indirizzi a cui potrebbe essere raggiunto. Il suo indirizzo privato è nascosto dietro un nome .local casuale. Il server di segnalazione passa l’offerta a Sam.","SDP, in a JSON message":"SDP, in un messaggio JSON",Candidates:"Candidati",".local name, 198.51.100.7":"nome .local, 198.51.100.7","About 4.7 KB":"Circa 4.7 KB","SDP: audio, video":"SDP: audio, video",candidates:"candidati","to Sam":"a Sam","Sam’s browser replies":"Risponde il browser di Sam","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Sam accetta la chiamata. Il browser di Sam risponde con un SDP suo: i codec scelti dall’offerta, l’impronta del suo certificato, il suo nome utente e la password ICE, e i suoi candidati, tra cui il suo indirizzo pubblico, 198.51.100.200 porta 49170, scoperto con un server STUN allo stesso modo. Dice anche che avvierà lui l’handshake di cifratura. Ora ogni browser sa dove l’altro potrebbe essere raggiunto.",Codecs:"Codec","Sam’s address":"Indirizzo di Sam","Starts DTLS":"Avvia DTLS","Sam’s browser":"Il browser di Sam","from Sam":"da Sam","Punch Through":"Aprire un varco","Checks straight to each other":"Controlli diretti tra i due","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Ora i browser provano coppie di indirizzi con controlli STUN inviati direttamente l’uno all’altro (ICE). Ogni controllo apre anche una via di ritorno attraverso il router del mittente, quindi quando entrambi i lati ne hanno inviato uno, i controlli passano entrambi i NAT. Questo riceve risposta: il percorso diretto funziona. Il portatile ripete poi il controllo con USE-CANDIDATE, scegliendo questa coppia per la chiamata.",Checks:"Controlli","STUN, peer to peer":"STUN, da pari a pari","The ICE password":"La password ICE","A direct path":"Un percorso diretto",CHECK:"CONTROLLO","IT WORKS":"FUNZIONA","direct path":"percorso diretto","THROUGH BOTH ROUTERS":"ATTRAVERSO ENTRAMBI I ROUTER","DTLS Handshake":"Handshake DTLS","Keys for the media":"Le chiavi per i media","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Sullo stesso percorso i browser eseguono un handshake DTLS: TLS per UDP. I loro certificati sono autofirmati, quindi ciascuno verifica quello dell’altro rispetto all’impronta nell’SDP, arrivata tramite il server di segnalazione dentro TLS. L’handshake concorda anche le chiavi per SRTP, che cifra audio e video. WebRTC non invia mai media non cifrati.","1.2, TLS over UDP":"1.2, TLS su UDP","Checked by fingerprint":"Verificati tramite impronta",Gives:"Fornisce","The SRTP keys":"Le chiavi SRTP",certificate:"certificato","Media Flows":"I media scorrono","Audio and video, direct":"Audio e video, diretti","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"L’audio va in un pacchetto SRTP ogni 20 ms, e il video in fotogrammi divisi su più pacchetti. Ogni pacchetto ha un’intestazione RTP leggibile (numero di sequenza, timestamp, ID del flusso) e media cifrati. Nulla passa da call.example.com. Entrambi i browser osservano ritardo e perdite e adattano la qualità del video, e un canale dati per chat o file può condividere lo stesso percorso.","Opus, a packet per 20 ms":"Opus, un pacchetto ogni 20 ms",Video:"Video","VP8, adapts to the network":"VP8, si adatta alla rete","None of it":"Nulla",AUDIO:"AUDIO","Opus, every 20 ms":"Opus, ogni 20 ms",VIDEO:"VIDEO","VP8, a frame in 3 packets":"VP8, un fotogramma in 3 pacchetti","Peer to Peer":"Da pari a pari","And when it can’t be":"E quando non si può","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"Il server ha aiutato i due browser a trovarsi, poi si è fatto da parte: la chiamata va direttamente tra le due case. Quando una rete non lascia passare pacchetti diretti (alcuni firewall aziendali, alcune reti mobili), ICE ripiega su un server TURN che inoltra i media cifrati senza poterli leggere. Anche le chiamate di gruppo di solito inviano i media tramite un server, chiamato SFU.","Laptop to laptop":"Da portatile a portatile",Fallback:"Ripiego","TURN relay (encrypted)":"Relay TURN (cifrato)","Group calls":"Chiamate di gruppo","Usually via an SFU":"Di solito tramite un SFU","NO SERVER IN THE MIDDLE":"NESSUN SERVER IN MEZZO","A WebSocket text message":"Un messaggio di testo WebSocket","The attributes; the 20-byte header isn’t counted.":"Gli attributi; l’intestazione di 20 byte non è contata.","Always this value: tells STUN apart from the other traffic on the same port.":"Sempre questo valore: distingue STUN dall’altro traffico sulla stessa porta.","Random; the response carries the same ID.":"Casuale; la risposta porta lo stesso ID.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"Da dove è arrivata la richiesta, come l’ha vista il server: l’indirizzo pubblico del router di casa e la porta che il suo NAT ha scelto per questa conversazione.","Their internet provider’s router, the next hop.":"Il router del loro provider Internet, il prossimo salto.","Their router’s internet-facing port.":"La porta del loro router rivolta verso Internet.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"I nomi utente ICE dall’offerta e dalla risposta, prima quello dell’altro lato: dimostra che il controllo appartiene a questa chiamata.","The priority a new candidate found by this check would get.":"La priorità che avrebbe un nuovo candidato trovato da questo controllo.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Questo lato, il chiamante, fa la scelta finale del percorso. Il numero casuale risolve un pareggio.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 del messaggio, calcolato con una password ICE scambiata tramite il server di segnalazione, così uno sconosciuto non può falsificare un controllo o la sua risposta.","A CRC-32 of the message: marks it clearly as STUN.":"Un CRC-32 del messaggio: lo segna chiaramente come STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"Da dove è arrivato il controllo, come l’ha visto l’altro portatile: l’indirizzo pubblico e la porta del router di casa.",Epoch:"Epoca","Counts this side’s records, so repeats and stale ones can be spotted.":"Conta i record di questo lato, così si possono individuare ripetizioni e record vecchi.","Message length":"Lunghezza del messaggio","Message sequence":"Sequenza del messaggio","Handshake messages are numbered, so they can be put back in order.":"I messaggi di handshake sono numerati, così si possono rimettere in ordine.",Fragment:"Frammento","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Suite di cifratura: ECDHE-ECDSA con AES-GCM, e altre","use_srtp: the SRTP protection it supports":"use_srtp: la protezione SRTP che supporta","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Scelta: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Un certificato autofirmato creato dal browser; la sua impronta era nell’offerta","Its half of an X25519 key exchange, signed":"La sua metà di uno scambio di chiavi X25519, firmata","Asks Sam’s browser for its certificate too":"Chiede anche al browser di Sam il suo certificato","Sam’s self-signed certificate; its fingerprint was in the answer":"Il certificato autofirmato di Sam; la sua impronta era nella risposta","Its half of the X25519 key exchange":"La sua metà dello scambio di chiavi X25519","A signature that proves it holds the certificate’s key":"Una firma che dimostra che possiede la chiave del certificato","From the next record on, this side encrypts.":"Dal prossimo record in poi, questo lato cifra.","Finished (encrypted)":"Finished (cifrato)","Epoch 1: protected with the keys just agreed.":"Epoca 1: protetto con le chiavi appena concordate.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Un nonce di 8 byte, il messaggio Finished e un tag di 16 byte (AES-128-GCM).","SRTP · audio":"SRTP · audio","2, no padding, extension, no CSRCs":"2, senza riempimento, estensione, senza CSRC","X set: a header extension follows the fixed header.":"X attivo: un’estensione dell’intestazione segue l’intestazione fissa.","One more for each packet, so a lost or late one shows.":"Uno in più per ogni pacchetto, così si nota uno perso o in ritardo.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Orologio audio, 48,000 tick al secondo: +960 ogni 20 ms.","Which stream this is; announced in the SDP.":"Quale flusso è; annunciato nell’SDP.","Header extension":"Estensione dell’intestazione","0xbede, 2 words":"0xbede, 2 parole","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Elementi da un byte: un ID (dalle righe a=extmap dell’SDP) e una lunghezza.","Audio level":"Livello audio","How loud this packet is, so a group call can show who is talking without decrypting.":"Quanto è forte questo pacchetto, così una chiamata di gruppo può mostrare chi parla senza decifrare.","Transport sequence":"Sequenza di trasporto","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Numera ogni pacchetto della chiamata; il destinatario riferisce cosa è arrivato e quando, per il controllo della congestione.","Encrypted media":"Media cifrati","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms di audio Opus, cifrati con le chiavi dell’handshake DTLS (AES-128-GCM).","Authentication tag":"Tag di autenticazione","Proves the packet came from the other side unchanged; the header is covered too.":"Dimostra che il pacchetto arriva dall’altro lato invariato; copre anche l’intestazione.","SRTP · video":"SRTP · video","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Orologio video, 90,000 tick al secondo: +3,000 per fotogramma a 30 fotogrammi al secondo.","Absolute send time":"Ora di invio assoluta","When the packet was sent, so the receiver can tell when the network is filling up.":"Quando è stato inviato il pacchetto, così il destinatario capisce quando la rete si sta riempiendo.","1 byte":"1 byte","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Parte di un fotogramma video VP8, cifrata con le chiavi dell’handshake DTLS (AES-128-GCM).","Marker set: the last packet of a video frame.":"Marker attivo: l’ultimo pacchetto di un fotogramma video.","8 ports":"8 porte","Frames and switches":"Frame e switch","Broadband logins":"Accesso a banda larga","The laptop sent it with 128; the router took 1 when it passed it on.":"Il portatile l’ha inviato con 128; il router ha tolto 1 quando l’ha inoltrato.","Frames & Switches":"Frame e switch","To the NAS":"Verso il NAS","To the internet":"Verso Internet","Ethernet and Switches":"Ethernet e switch","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Ethernet porta quasi ogni rete cablata, e gli access point Wi-Fi le passano il loro traffico. Ogni scheda di rete ha un indirizzo MAC di 48 bit. Un frame dice a quale scheda è destinato e quale scheda l’ha inviato, e uno switch lo consegna: impara dietro quale porta si trova ogni indirizzo dai frame che vede, e manda ogni frame solo dove deve andare.","48-bit MAC":"MAC a 48 bit","14 bytes, plus a 4-byte FCS":"14 byte, più un FCS di 4 byte","Frame size":"Dimensione del frame","64 to 1,518 bytes":"Da 64 a 1.518 byte",Speeds:"Velocità",Switched:"Commutato","Learned, flooded, forwarded":"Imparato, inondato, inoltrato","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"Lo switch ha imparato dove si trovavano il portatile e il NAS dai frame che hanno inviato, ha inondato solo il broadcast e ha mandato ogni altro frame solo dalla porta necessaria. Gli indirizzi MAC hanno portato ogni frame su un solo collegamento; al router il pacchetto è passato in un frame nuovo. Premi RIVEDI per guardarlo di nuovo.",Learned:"Imparati","2 addresses, 2 ports":"2 indirizzi, 2 porte",Flooded:"Inondato","Only the broadcast":"Solo il broadcast",Frame:"Frame","14-byte header, 4-byte FCS":"Header di 14 byte, FCS di 4","Forgets after":"Dimentica dopo","5 minutes unused":"5 minuti senza uso","Who Has the NAS?":"Chi ha il NAS?","A broadcast asks for a MAC address":"Un broadcast chiede un indirizzo MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"Il portatile vuole raggiungere il NAS a 192.168.1.20. In una rete locale i frame vengono consegnati in base all’indirizzo MAC, e il portatile non conosce ancora quello del NAS. Così invia una richiesta ARP a ff:ff:ff:ff:ff:ff, l’indirizzo di broadcast, nella porta 1 dello switch.","Looking for":"Cerca","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (tutti)",Into:"Entra da","Switch port 1":"Porta 1 dello switch","who has 192.168.1.20?":"chi ha 192.168.1.20?","Learn, Then Flood":"Imparare, poi inondare","The switch notes where the laptop is":"Lo switch annota dov’è il portatile","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Uno switch legge l’indirizzo sorgente di ogni frame e lo annota nella sua tabella MAC: 00:00:5e:00:53:10 è sulla porta 1. Un broadcast è per tutti, quindi ne manda una copia da ogni altra porta: al NAS sulla porta 2 e al router sulla porta 8. Anche i frame per indirizzi sconosciuti vengono inondati.","…:53:10 is on port 1":"…:53:10 è sulla porta 1",Copies:"Copie","Out of every other port":"Da ogni altra porta","Unknown address":"Indirizzo sconosciuto","Flooded the same way":"Inondato allo stesso modo","…:53:10 IS ON PORT 1":"…:53:10 È SULLA PORTA 1","copies out of ports 2 and 8":"copie dalle porte 2 e 8","Only the NAS Answers":"Risponde solo il NAS","The reply goes to one port":"La risposta va a una porta","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Ogni dispositivo legge la richiesta, ma solo il NAS ha 192.168.1.20, quindi risponde solo lui, direttamente al MAC del portatile; il router la ignora. Lo switch impara che 00:00:5e:00:53:20 è sulla porta 2. Sa già dov’è il portatile, quindi la risposta esce solo dalla porta 1.","To the laptop only":"Solo al portatile","…:53:20 is on port 2":"…:53:20 è sulla porta 2","Out of":"Esce da","Port 1":"Porta 1","…:53:20 IS ON PORT 2":"…:53:20 È SULLA PORTA 2","port 1 only":"solo porta 1","Port to Port":"Da porta a porta","Frames go only where they must":"I frame vanno solo dove devono","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"Il portatile si collega al NAS. Ogni frame inizia con il MAC del NAS, poi il proprio, poi un tipo: 0x0800, un pacchetto IPv4. Dopo il pacchetto la scheda aggiunge un checksum di 4 byte. Lo switch cerca la destinazione e manda ogni frame solo dalla porta 2. Il router non li vede mai.","To, from, type: 14 bytes":"A, da, tipo: 14 byte","4 bytes, added by the card":"4 byte, aggiunti dalla scheda","Router sees":"Il router vede",Nothing:"Niente","type 0x0800 (IPv4)":"tipo 0x0800 (IPv4)","out of port 2 only":"solo dalla porta 2","Off the Network":"Fuori dalla rete","A frame for the router":"Un frame per il router","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Poi il portatile apre un sito su 203.0.113.10. Quell’indirizzo non è nella rete locale, quindi il frame va al router: la destinazione è il MAC del router, noto da un ARP precedente, mentre il pacchetto dentro indica ancora 203.0.113.10. Lo switch lo manda dalla porta 8.","Frame to":"Frame a","The router’s MAC":"Il MAC del router","Packet to":"Pacchetto a","Port 8":"Porta 8","IP packet to 203.0.113.10":"pacchetto IP a 203.0.113.10","out of port 8":"dalla porta 8","A New Frame":"Un frame nuovo","Every hop rewraps the packet":"Ogni hop reimpacchetta il pacchetto","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"Il router toglie il pacchetto dal frame, abbassa il TTL e mette il suo indirizzo pubblico (NAT). Poi mette il pacchetto in un frame nuovo per il collegamento successivo: il suo MAC lato Internet come sorgente, il router del provider come destinazione. Gli indirizzi MAC non attraversano mai più di un collegamento.","The router’s internet port":"La porta Internet del router","The provider’s router":"Il router del provider","Still 203.0.113.10":"Sempre 203.0.113.10","NEW FRAME":"FRAME NUOVO","from the router’s internet port":"dalla porta Internet del router","IP still to 203.0.113.10":"IP sempre a 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"Entra, porta 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Esce, porta 2 (inondato) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Esce, porta 8 (inondato) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"Entra, porta 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Esce solo dalla porta 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"Entra, porta 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Esce, porta 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"Entra, porta 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Esce, porta 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"Entra, porta 1 · 52344 → 443 [SYN] (frame per il router)","Out port 8 · 52344 → 443 [SYN]":"Esce, porta 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (frame nuovo, dopo il NAT)","Seen going into the switch, port 1":"Visto entrare nello switch, porta 1","Seen leaving the switch, port 2":"Visto uscire dallo switch, porta 2","Seen leaving the switch, port 8":"Visto uscire dallo switch, porta 8","Seen going into the switch, port 2":"Visto entrare nello switch, porta 2","Seen leaving the switch, port 1":"Visto uscire dallo switch, porta 1","Broadband Logins":"Accesso a banda larga",Discovery:"Discovery","PPP setup":"Avvio di PPP","Home Router":"Router di casa","Access Server":"Server di accesso","Point-to-Point Protocol over Ethernet":"Point-to-Point Protocol su Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Molti provider DSL e in fibra fanno autenticare il router di casa prima di farlo andare online. PPPoE è il modo: il router trova il server di accesso del provider e apre una sessione con lui, poi ci fa girare PPP, concordando le impostazioni del collegamento, autenticandosi con il nome utente e la password del provider e ricevendo il suo indirizzo IP pubblico. Da lì in poi ogni pacchetto porta un header PPPoE di 8 byte.","CHAP or PAP":"CHAP o PAP","From IPCP":"Da IPCP","8 bytes (MTU 1,492)":"8 byte (MTU 1.492)","Logged in":"Autenticato","Found, agreed, checked, addressed":"Trovato, concordato, verificato, indirizzato","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"Il router ha trovato il server di accesso del provider, ha ottenuto una sessione, ha concordato le impostazioni del collegamento, ha dimostrato la password senza inviarla e ha ricevuto il suo indirizzo pubblico. Ora ogni pacchetto viaggia dentro quella sessione, finché un PADT non la chiude. Premi RIVEDI per guardarlo di nuovo.","17 to get online":"17 per andare online","Public IP":"IP pubblico","8 bytes per packet":"8 byte per pacchetto","Anyone There?":"C’è nessuno?","The router looks for an access server":"Il router cerca un server di accesso","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"Il router di casa è collegato alla linea in fibra o DSL del provider. Prima di autenticarsi deve trovare il server di accesso del provider, quindi invia in broadcast un PADI: “PPPoE Active Discovery Initiation”. Un server di accesso risponde con un PADO, un’offerta che lo nomina: bng-1.example.net.","PADI, to everyone":"PADI, a tutti","PADO, from the server":"PADO, dal server","Ethernet type":"Tipo Ethernet","0x8863 (discovery)":"0x8863 (discovery)","is there an access server?":"c’è un server di accesso?","and a cookie":"e un cookie","Pick a Server":"Scegliere un server","A session number for the line":"Un numero di sessione per la linea","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Se hanno risposto più server, il router ne sceglie uno e lo interpella direttamente con un PADR, rimandando il cookie ricevuto. Il server risponde con un PADS che porta un ID di sessione, 0x2f1c. D’ora in poi ogni frame tra i due porta quel numero.",Confirmed:"Confermato","this server, please":"questo server, per favore","with its cookie":"con il suo cookie","session ID 0x2f1c":"ID di sessione 0x2f1c","SESSION 0x2F1C":"SESSIONE 0x2F1C","Link Settings":"Impostazioni del collegamento","LCP agrees on size and login":"LCP concorda dimensione e accesso","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"Ora PPP gira dentro la sessione, a partire da LCP. Ogni lato chiede le sue impostazioni: pacchetti di al massimo 1.492 byte, perché gli 8 byte di PPPoE devono stare nei 1.500 di Ethernet, e un magic number casuale per scoprire i loop. Il server chiede anche un accesso CHAP. Entrambi accettano.","Largest packet":"Pacchetto più grande","1,492 bytes (MRU)":"1.492 byte (MRU)","CHAP with MD5":"CHAP con MD5","0x8864 (session)":"0x8864 (sessione)","LCP REQUEST":"RICHIESTA LCP","magic number":"magic number","MRU 1492, log in with CHAP":"MRU 1492, accesso con CHAP","LCP ACK":"LCP ACK","A password check without the password":"Verificare la password senza inviarla","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"Il server invia una sfida casuale. Il router risponde con il suo nome utente, alex@fibre.example, e un hash MD5 della sfida e della password, quindi la password stessa non attraversa mai la linea. Il server verifica la risposta con il server RADIUS del provider, poi risponde Success.",Username:"Nome utente","A hash, not the password":"Un hash, non la password","The provider’s RADIUS":"Il RADIUS del provider","MD5(id, password, challenge)":"MD5(id, password, sfida)","CHECKED WITH RADIUS":"VERIFICATO CON RADIUS","Get an Address":"Ottenere un indirizzo","IPCP hands out the public IP":"IPCP assegna l’IP pubblico","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"Il server comunica prima al router il proprio capo, 198.51.100.1. Il router chiede un indirizzo e dei server DNS, proponendo 0.0.0.0: “uno qualsiasi”. Il server rifiuta e suggerisce 198.51.100.7 e due server DNS. Il router richiede con quei valori, e il server accetta.","Other end":"L’altro capo","IPCP REQUEST":"RICHIESTA IPCP","my end: 198.51.100.1":"il mio capo: 198.51.100.1","address? 0.0.0.0":"indirizzo? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"usa 198.51.100.7","198.51.100.7, please":"198.51.100.7, per favore",agreed:"d’accordo","Every packet in an 8-byte wrapper":"Ogni pacchetto in un involucro di 8 byte","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"Il portatile apre un sito. Il router mette il suo indirizzo pubblico (NAT) e invia il pacchetto dentro la sessione: un header PPPoE di 6 byte, poi 2 byte che dicono “IPv4”. Abbassa anche l’MSS offerto dal portatile da 1460 a 1452, così le risposte stanno in 1.492 byte.",Wrapper:"Involucro","6 + 2 bytes":"6 + 2 byte","1460 → 1452 (clamped)":"1460 → 1452 (ridotto)","in session 0x2f1c":"nella sessione 0x2f1c","MSS now 1452":"MSS ora 1452","Seen on the router’s line to the provider":"Visto sulla linea del router verso il provider","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 byte","PADI, 2 tags":"PADI, 2 tag","Broadcast: everything on the line receives it.":"Broadcast: lo riceve tutto ciò che è sulla linea.","0x8863 (PPPoE discovery)":"0x8863 (discovery PPPoE)","Version, type":"Versione, tipo","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: c’è un server di accesso là fuori?","0 (none yet)":"0 (ancora nessuno)","What follows this header.":"Ciò che segue questo header.","The service the router wants; empty means any.":"Il servizio che vuole il router; vuoto significa uno qualsiasi.","Type, length":"Tipo, lunghezza","A value the router made up. Answers carry it back, so the router can match them to its request.":"Un valore inventato dal router. Le risposte lo riportano indietro, così il router può abbinarle alla sua richiesta.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 byte","PADO, 4 tags":"PADO, 4 tag","The access server’s port.":"La porta del server di accesso.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: un server di accesso risponde.","The access server’s name.":"Il nome del server di accesso.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Un valore che il server riconoscerà quando il router lo chiederà di nuovo, così una valanga di richieste false non gli costa nulla.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 byte","PADR, 3 tags":"PADR, 3 tag","The access server that answered.":"Il server di accesso che ha risposto.","Active Discovery Request: the router picks this server.":"Active Discovery Request: il router sceglie questo server.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 byte","PADS, 2 tags":"PADS, 2 tag","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: ecco l’ID di sessione.","Given by the server in its PADS; every frame of the session carries it.":"Assegnato dal server nel suo PADS; lo porta ogni frame della sessione.","PPPoE · 6 bytes":"PPPoE · 6 byte","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 byte","0x8864 (PPPoE session)":"0x8864 (sessione PPPoE)","0x00 (Session)":"0x00 (sessione)","Session data: one PPP packet.":"Dati di sessione: un pacchetto PPP.","Link Control Protocol: the link’s settings.":"Link Control Protocol: le impostazioni del collegamento.","The settings this side wants.":"Le impostazioni che vuole questo lato.","The answer carries the same number.":"La risposta porta lo stesso numero.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Il pacchetto più grande che accetta questo lato: 1.500 byte di Ethernet meno gli 8 di PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Casuale. Vedere tornare il proprio numero vorrebbe dire che la linea è chiusa su sé stessa.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 byte","How the server wants the router to log in.":"Come il server vuole che il router si autentichi.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 byte","Every setting accepted, exactly as asked.":"Ogni impostazione accettata, esattamente come chiesta.","The number of the request this answers.":"Il numero della richiesta a cui risponde.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 byte","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 byte","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: l’accesso.","A random value for the router to prove its password with.":"Un valore casuale con cui il router dimostra la sua password.","The response must carry the same number.":"La risposta deve portare lo stesso numero.","Value size":"Dimensione del valore","Random, new for every login.":"Casuale, nuovo a ogni accesso.","The server’s name.":"Il nome del server.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 byte","The proof, and who is logging in.":"La prova, e chi sta accedendo.","The number of the challenge this answers.":"Il numero della sfida a cui risponde.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 dell’identificativo, della password e della sfida: dimostra la password senza inviarla.","The username the provider gave.":"Il nome utente dato dal provider.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 byte","The login worked.":"L’accesso è riuscito.","Text for people to read; any words will do.":"Testo da leggere per le persone; vanno bene parole qualsiasi.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 byte","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: l’indirizzo IP e i server DNS.","The address of the server’s end of the link.":"L’indirizzo del capo del server sul collegamento.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 byte","Zero: “please give me an address”.":"Zero: “dammi un indirizzo, per favore”.","Zero: “which DNS server should I use?”":"Zero: “quale server DNS devo usare?”","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 byte","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 byte","Not these values: here are ones that would be accepted.":"Non questi valori: eccone alcuni che verrebbero accettati.","The address for the router.":"L’indirizzo per il router.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 byte","PPP · 2 bytes":"PPP · 2 byte","An IPv4 packet follows.":"Segue un pacchetto IPv4.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Abbassato da 1460 dal router, così i pacchetti di ritorno stanno nei 1.492 byte che lascia PPPoE.","Internet phone calls":"Chiamate via internet","IP camera streams":"Flussi da telecamere IP","Live streaming upload":"Caricare dirette","Multicast and TV channels":"Multicast e canali TV","IP Camera":"Telecamera IP","TV Box":"Decoder TV",Camera:"Telecamera","Internet Phone Calls":"Chiamate via internet","Voice (RTP)":"Voce (RTP)","SIP Server":"Server SIP","Bob’s Router":"Router di Bob","Session Initiation Protocol":"Session Initiation Protocol","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP imposta le telefonate via internet: telefoni da scrivania in ufficio, app telefoniche e gli operatori dietro di loro. Un telefono accede al server SIP del suo operatore. Per chiamare qualcuno invia un INVITE; l’altro telefono squilla e risponde, e i due si accordano su come inviare la voce, che poi viaggia come RTP. I messaggi sono testo semplice, molto simili a HTTP.","UDP or TCP 5060":"UDP o TCP 5060","Call setup":"Avvio chiamata",Voice:"Voce","RTP, described by SDP":"RTP, descritto da SDP","Codec here":"Codec qui","Call ended":"Chiamata finita","Signed in, rang, talked, hung up":"Registrato, squillato, parlato, riattaccato","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"Il telefono di Alice si è registrato con una password che non ha mai inviato, ha invitato il telefono di Bob tramite il server SIP, l’ha sentito squillare e ha parlato via RTP finché Bob non ha riattaccato con un BYE. SIP ha solo aperto e chiuso la chiamata; la voce ha viaggiato in pacchetti propri. Premi RIVEDI per guardarlo di nuovo.","50 packets a second each way":"50 pacchetti al secondo per verso",Through:"Passa da","The provider’s server":"Il server dell’operatore","No (SIPS and SRTP add it)":"No (SIPS e SRTP la aggiungono)","Sign In":"Accesso","The phone tells the server where it is":"Il telefono dice al server dove si trova","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"Il telefono di Alice, un’app sul suo portatile, si registra sul server SIP del suo operatore: alice@example.net è raggiungibile qui. Il server risponde 401 con una sfida, così il telefono richiede con un hash ricavato dalla sfida e dalla password. 200 OK: registrato per un’ora.","Good for":"Valido per","3600 s, then again":"3600 s, poi di nuovo","is here":"è qui","with a challenge":"con una sfida","again, with a hash":"di nuovo, con un hash",registered:"registrato","Call Bob":"Chiamare Bob","An INVITE, passed on by the server":"Un INVITE, inoltrato dal server","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice chiama bob@example.net. Il suo INVITE porta SDP: audio G.711, da inviare al suo telefono. Il server risponde 100 Trying, trova dove si è registrato il telefono di Bob e inoltra l’INVITE con il proprio Via, il Record-Route e il proprio indirizzo nell’SDP: la voce passerà da lui.","Offer (SDP)":"Offerta (SDP)","G.711, port 49170":"G.711, porta 49170","Stops Alice resending":"Alice smette di ritrasmettere","call bob@example.net":"chiama bob@example.net","SDP: G.711 audio":"SDP: audio G.711","passed on to Bob":"inoltrato a Bob","voice via the server":"voce tramite il server",Ringing:"Squilla","The answer retraces the route":"La risposta ripercorre la strada","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"Il telefono di Bob inizia a squillare e lo comunica: 180 Ringing. Le risposte seguono le intestazioni Via all’indietro lungo la strada della richiesta, quindi va al server, che toglie il proprio Via e la passa ad Alice. Il suo telefono riproduce il tono di chiamata.","Route back":"Strada di ritorno","The Via headers, in reverse":"Le intestazioni Via, al contrario","Alice hears":"Alice sente","The ringing tone":"Il tono di chiamata","Bob’s phone rings":"squilla il telefono di Bob","to Alice":"verso Alice",Answered:"Risposta","200 OK, then ACK":"200 OK, poi ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob risponde. Il suo 200 OK porta la sua risposta SDP: G.711, da inviare al suo telefono. Il server rimette il proprio indirizzo prima di passarla ad Alice. Il suo telefono conferma con un ACK, che il server passa a Bob. La chiamata è avviata.","Answer (SDP)":"Risposta (SDP)","G.711, port 49172":"G.711, porta 49172","Confirmed by":"Confermata da","Voice goes to":"La voce va a","The server, ports 40000, 40002":"Il server, porte 40000, 40002","Bob answers":"Bob risponde",answered:"risposto",Talking:"Conversazione","Voice flows as RTP":"La voce viaggia come RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Ora la voce: ogni 20 ms ciascun telefono invia un pacchetto RTP con 160 byte di suono G.711, un numero di sequenza e un timestamp, via UDP. Vanno al server, che li passa all’altro telefono. SIP tace mentre parlano.",Every:"Ogni","20 ms, 160 bytes of sound":"20 ms, 160 byte di suono","Carried by":"Trasportata da","RTP over UDP":"RTP su UDP","SIP meanwhile":"SIP intanto","Nothing to say":"Niente da dire",VOICE:"VOCE","20 ms of Alice":"20 ms di Alice","20 ms of Bob":"20 ms di Bob","Hang Up":"Riattaccare","BYE, and 200 OK":"BYE e 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob riattacca: il suo telefono invia BYE, instradato dal server come chiedeva il Record-Route, e il telefono di Alice risponde 200 OK. Entrambi smettono di inviare voce. La chiamata ha richiesto quattro tipi di richiesta; la voce non ha mai fatto parte di SIP.","No more RTP":"Niente più RTP","Bob hangs up":"Bob riattacca","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: G.711 legge μ, il classico codec telefonico)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Clock audio a 8000 al secondo: +160 ogni 20 ms di suono.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 byte di audio G.711 (20 ms, un byte per campione)","IP Camera Streams":"Flussi da telecamere IP","Video (RTP)":"Video (RTP)","Real Time Streaming Protocol":"Real Time Streaming Protocol","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"RTSP è il modo in cui lettori video, registratori e app di sorveglianza ricevono video in diretta dalle telecamere IP. Funziona come un telecomando: il lettore chiede cosa offre la telecamera, prepara un flusso e dice PLAY e poi TEARDOWN, con messaggi di testo molto simili a HTTP. Il video stesso non viaggia in RTSP: scorre a parte come RTP, qui su UDP.",Controls:"Comandi",Watched:"Visto","Described, set up, played, stopped":"Descritto, preparato, riprodotto, fermato","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC ha chiesto alla telecamera cosa aveva, ha fatto l’accesso con un hash della password, ha preparato una traccia video e ha premuto PLAY. Il video è arrivato come pacchetti RTP su porte proprie, un fotogramma chiave in tre pezzi, finché TEARDOWN non ha chiuso la sessione. Premi RIVEDI per guardarlo di nuovo.","6 on one TCP connection":"6 su una connessione TCP","Key frame":"Fotogramma chiave","Split into 3 packets":"Diviso in 3 pacchetti","1185d200, 60 s timeout":"1185d200, scade dopo 60 s","What Can You Do?":"Cosa sai fare?","OPTIONS over a TCP connection":"OPTIONS su una connessione TCP","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC apre rtsp://192.168.1.64/stream1. Si collega alla telecamera sulla porta TCP 554 e inizia con OPTIONS: quali comandi supporti? La telecamera li elenca. Come in HTTP, ogni richiesta e risposta è testo; un’intestazione CSeq le numera.","Numbered by":"Numerate da","what can you do?":"cosa sai fare?","Describe the Stream":"Descrivere il flusso","SDP says what the video is":"L’SDP dice cos’è il video","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE chiede la descrizione del flusso. La telecamera vuole prima un accesso: 401, con una sfida digest. VLC richiede con un hash della password, e la risposta porta SDP: una traccia video H.264, tipo di payload RTP 96, con un clock a 90 kHz.","Digest: a hash":"Digest: un hash","H.264, payload type 96":"H.264, tipo di payload 96",Track:"Traccia","describe stream1":"descrivi stream1","log in first":"prima accedi","SDP: H.264 video":"SDP: video H.264","track 1":"traccia 1","Set Up":"Preparazione","Agree on ports for the video":"Accordarsi sulle porte del video","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP per trackID=1 dice come consegnarla: RTP su UDP, alle porte 50000 (video) e 50001 (report RTCP) del portatile. La telecamera accetta, sceglie le sue porte, 6970 e 6971, e apre una sessione, 1185d200, che ogni richiesta successiva nomina.","Laptop ports":"Porte del portatile","track 1, RTP over UDP":"traccia 1, RTP su UDP","to ports 50000-50001":"alle porte 50000-50001","session 1185d200":"sessione 1185d200","from ports 6970-6971":"dalle porte 6970-6971",Play:"Riproduzione","The remote control’s PLAY button":"Il tasto PLAY del telecomando","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY avvia il flusso da adesso (npt=0.000-). La risposta dice a VLC quale numero di sequenza e timestamp RTP arrivano per primi, così può allineare il video. Da qui in poi il video non passa più per RTSP.",Range:"Intervallo","From now":"Da adesso","First packet":"Primo pacchetto","Video arrives":"Il video arriva","On the UDP ports":"Sulle porte UDP","play from now":"riproduci da adesso",playing:"in riproduzione","Video Arrives":"Arriva il video","A key frame in RTP packets":"Un fotogramma chiave in pacchetti RTP","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"La telecamera invia un fotogramma chiave, un’immagine intera, in tre pacchetti RTP: frammenti H.264 segnati come primo, centrale e ultimo, con il bit marker sull’ultimo. Tutti e tre hanno lo stesso timestamp a 90 kHz. Seguono fotogrammi più piccoli con solo le modifiche, 25 al secondo.",Packets:"Pacchetti","3 for one key frame":"3 per un fotogramma chiave","Same for the whole frame":"Uguale per tutto il fotogramma",Frames:"Fotogrammi","25 a second":"25 al secondo","a key frame in 3 packets":"un fotogramma chiave in 3 pacchetti",Stop:"Stop","TEARDOWN ends the session":"TEARDOWN chiude la sessione","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Quando lo spettatore chiude il flusso, VLC invia TEARDOWN con l’ID di sessione. La telecamera smette di inviare video e conferma. Se VLC fosse semplicemente sparito, la telecamera si sarebbe fermata comunque dopo 60 secondi senza sue notizie.",Ended:"Chiusa",Otherwise:"Altrimenti","Timeout after 60 s":"Scade dopo 60 s","stop session 1185d200":"chiudi la sessione 1185d200",stopped:"fermato","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"La telecamera. È sulla stessa rete, quindi il frame va dritto a lei, senza passare dal router.","The camera’s network port.":"La porta di rete della telecamera.","RTP + video":"RTP + video","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, come diceva la descrizione della telecamera)","Marker clear: more of this frame follows.":"Marker spento: segue altro di questo fotogramma.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Clock video a 90.000 al secondo; tutti i pacchetti di un fotogramma hanno lo stesso valore.","Identifies this video stream.":"Identifica questo flusso video.","FU indicator":"Indicatore FU","0x7c (fragment of a frame)":"0x7c (frammento di un fotogramma)","Fragmentation unit: one piece of a frame too big for one packet.":"Unità di frammentazione: un pezzo di un fotogramma troppo grande per un pacchetto.","FU header":"Intestazione FU","0x85 (first piece of a key frame)":"0x85 (primo pezzo di un fotogramma chiave)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Tipo 5: un fotogramma chiave (IDR), un’immagine intera da cui il decoder può partire.","1398 bytes of the key frame":"1398 byte del fotogramma chiave","0x05 (middle piece of a key frame)":"0x05 (pezzo centrale di un fotogramma chiave)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, come diceva la descrizione della telecamera)","Marker set: the last packet of a frame.":"Marker acceso: l’ultimo pacchetto di un fotogramma.","0x45 (last piece of a key frame)":"0x45 (ultimo pezzo di un fotogramma chiave)","900 bytes of the key frame":"900 byte del fotogramma chiave","Multicast TV":"TV multicast","Joins and leaves":"Ingressi e uscite","Channel 1":"Canale 1","TV channels":"Canali TV","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Il multicast invia un solo flusso a un indirizzo di gruppo, e la rete lo copia solo dove serve: è così che i provider internet distribuiscono i canali TV in diretta. IGMP è il modo in cui un dispositivo dice al router quali gruppi vuole. Gli switch ascoltano (IGMP snooping), così ogni flusso raggiunge solo le porte che l’hanno chiesto.","IP protocol 2":"Protocollo IP 2",Groups:"Gruppi","Version here":"Versione qui","Tuned In":"Sintonizzato","Joined, copied, checked, left":"Entrato, copiato, verificato, uscito","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"Il decoder e poi il portatile si sono uniti al canale 1 con report IGMP. Il router si è unito una volta sola per tutta la casa, e lo switch, in ascolto, ha copiato il canale solo verso le porte che lo volevano. Le query l’hanno tenuto attivo e, quando il portatile è uscito, la risposta del decoder l’ha lasciato acceso. Premi RIVEDI per guardarlo di nuovo.",Upstream:"Verso il provider","One stream for the home":"Un flusso per tutta la casa","Copies to ports that joined":"Copie verso le porte unite","Every 125 s":"Ogni 125 s","Pick a Channel":"Scegliere un canale","The TV box joins a group":"Il decoder si unisce a un gruppo","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"Lo spettatore sceglie il canale 1. Ogni canale è un gruppo multicast, qui 233.252.0.1, e il decoder invia un IGMP Membership Report a quell’indirizzo: voglio questo gruppo. Lo switch ascolta (IGMP snooping), annota la porta 2 e passa il report solo al router.","Switch notes":"Lo switch annota","Port 2 wants it":"La porta 2 lo vuole","233.252.0.1, please":"233.252.0.1, per favore","to the router port only":"solo alla porta del router","Ask the Provider":"Chiedere al provider","The router joins for the home":"Il router si unisce per la casa","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"Il router è un proxy IGMP: si unisce al gruppo sul lato internet con un report suo, dal suo indirizzo pubblico, e la rete del provider inizia a mandare il canale 1 sulla linea. Per quanti schermi si sintonizzino in casa, il router si unisce una volta sola.","Router role":"Ruolo del router","IGMP proxy":"Proxy IGMP",Joins:"Si unisce","Once for the whole home":"Una volta per tutta la casa","for the whole home":"per tutta la casa","The Channel Flows":"Il canale scorre","Sent only where it was asked for":"Inviato solo dove richiesto","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"Il server TV del provider invia il canale 1 a 233.252.0.1: datagrammi UDP con sette pacchetti MPEG-TS da 188 byte di video e audio ciascuno. Il router li fa entrare e lo switch li fa uscire solo dalla porta 2: si è unito solo il decoder, quindi il portatile non ne riceve nessuno.",Datagram:"Datagramma","UDP, 1,316 bytes of TV":"UDP, 1.316 byte di TV",Holds:"Contiene","7 MPEG-TS packets":"7 pacchetti MPEG-TS","CHANNEL 1":"CANALE 1","MPEG-TS over UDP":"MPEG-TS su UDP","passed into the home":"passato in casa","port 2 only":"solo porta 2","A Second Screen":"Un secondo schermo","The laptop tunes in too":"Anche il portatile si sintonizza","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"Il portatile apre il canale 1 in VLC e invia il proprio report. Lo switch aggiunge la porta 1 e ora fa due copie di ogni datagramma. Il router riceve già il canale, quindi non chiede nulla al provider: sulla linea arriva sempre un solo flusso.","Switch sends to":"Lo switch invia a","Ports 1 and 2":"Porte 1 e 2","Still one stream":"Sempre un solo flusso","Router asks":"Il router chiede","Nothing new":"Niente di nuovo","the same one stream":"lo stesso unico flusso","copied to ports 1 and 2":"copiato alle porte 1 e 2","Still Watching?":"Stai ancora guardando?","The router checks regularly":"Il router controlla regolarmente","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Ogni 125 secondi il router invia una General Query a 224.0.0.1, tutti i dispositivi: quali gruppi volete ancora? Lo switch la passa a tutte le porte. Ogni membro risponde in un momento a caso entro 10 secondi, così router e switch continuano a far arrivare il canale.","125 seconds":"125 secondi","224.0.0.1, all devices":"224.0.0.1, tutti i dispositivi","Answer within":"Risposta entro","10 seconds":"10 secondi",QUERY:"QUERY","any groups wanted?":"quali gruppi volete?","to every port":"a tutte le porte",REPORT:"REPORT","still watching":"sto ancora guardando",Leave:"Uscita","The laptop stops watching":"Il portatile smette di guardare","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"Chiudere VLC invia un Leave Group a 224.0.0.2, tutti i router. Altri potrebbero ancora guardare, quindi il router chiede solo di quel gruppo e aspetta 1 secondo. Il decoder risponde, quindi il canale resta; lo switch smette solo di inviarlo alla porta 1.","Leave sent to":"Uscita inviata a","224.0.0.2, all routers":"224.0.0.2, tutti i router","About that group alone":"Solo di quel gruppo","Stays: the TV box answered":"Resta: il decoder ha risposto",LEAVE:"USCITA","done with 233.252.0.1":"basta con 233.252.0.1","anyone for 233.252.0.1?":"qualcuno per 233.252.0.1?","to the ports that joined":"alle porte unite","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Multicast: 01:00:5e, poi gli ultimi 23 bit dell’indirizzo del gruppo. Le schede di rete ascoltano i gruppi a cui si è unito il loro sistema.","The TV box’s network port.":"La porta di rete del decoder.","4, 24 bytes":"4, 24 byte","IPv4, with one 4-byte option.":"IPv4, con un’opzione di 4 byte.","48 (network control), 0":"48 (controllo di rete), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Segnato come controllo di rete, quindi parte prima del traffico normale.","Always 1: IGMP never goes past the first router.":"Sempre 1: IGMP non va mai oltre il primo router.","A multicast group address.":"Un indirizzo di gruppo multicast.","Router Alert option":"Opzione Router Alert","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Chiede a ogni router lungo la strada di guardare dentro, anche se il pacchetto non è indirizzato a lui.","This device wants the group’s traffic.":"Questo dispositivo vuole il traffico del gruppo.","Max response time":"Tempo massimo di risposta","Only queries use it.":"Lo usano solo le query.","Covers the IGMP message.":"Copre il messaggio IGMP.","Group address":"Indirizzo del gruppo","The multicast group: one TV channel.":"Il gruppo multicast: un canale TV.","Seen arriving on the router’s internet side":"Visto arrivare sul lato internet del router","MPEG-TS · 7 packets":"MPEG-TS · 7 pacchetti","The provider’s router, passing the channel on.":"Il router del provider, che inoltra il canale.","Sync byte":"Byte di sincronia","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Ogni pacchetto di transport stream inizia con 0x47, così il ricevitore trova dove iniziano i pacchetti.","Flags, PID":"Flag, PID","0x0100 (PID 256: video)":"0x0100 (PID 256: video)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"A quale flusso appartiene il pacchetto: il video del canale, il suo audio o le tabelle che li elencano.","Payload, counter":"Payload, contatore","0x14 (payload only, counter 4)":"0x14 (solo payload, contatore 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Conta da 0 a 15 per ogni PID, così un pacchetto perso si vede come un buco.","184 bytes of the channel’s video":"184 byte del video del canale","More packets":"Altri pacchetti","6 × 188 bytes: video and audio":"6 × 188 byte: video e audio","Six more transport stream packets, each with its own 4-byte header.":"Altri sei pacchetti di transport stream, ciascuno con la propria intestazione di 4 byte.","Seen going into the switch, port 8":"Visto entrare nello switch, porta 8","The router, passing the channel into the home.":"Il router, che passa il canale in casa.","0x19 (payload only, counter 9)":"0x19 (solo payload, contatore 9)","The router asks: which groups does anyone here still want?":"Il router chiede: quali gruppi vuole ancora qualcuno qui?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"I membri rispondono in un momento a caso entro questo tempo, così le risposte non arrivano tutte insieme.","Zero in a general query: every group.":"Zero in una query generale: tutti i gruppi.","This device no longer wants the group.":"Questo dispositivo non vuole più il gruppo.","The router asks: does anyone still want this group?":"Il router chiede: qualcuno vuole ancora questo gruppo?","Live Streaming Upload":"Caricare dirette","RTMP handshake":"Handshake RTMP","Video and audio":"Video e audio","Ingest Server":"Server di ingest","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"RTMP è il modo in cui la maggior parte degli streamer invia video in diretta a una piattaforma: OBS e altre app lo spingono verso un server di ingest, che lo trasforma in dirette per gli spettatori. Nato per Flash, è sopravvissuto a Flash come modo di caricare. Tutto condivide una connessione TCP: comandi, audio e video, tagliati in chunk.","H.264 video, AAC audio":"Video H.264, audio AAC","Encoded in AMF0":"Codificati in AMF0","Secure version":"Versione sicura","RTMPS, over TLS":"RTMPS, su TLS","Adobe specification (2012)":"Specifica Adobe (2012)",Live:"In diretta","Connected, published, streamed":"Connesso, pubblicato, trasmesso","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS ha fatto l’handshake con il server di ingest, si è connesso alla sua app live, ha ottenuto lo stream 1 e vi ha pubblicato con la chiave di stream. Video e audio sono poi scorsi in chunk sulla stessa connessione TCP finché lo streamer non si è fermato. Premi RIVEDI per guardarlo di nuovo.","One TCP, port 1935":"Una TCP, porta 1935",Stream:"Stream",Chunks:"Chunk","Up to 4,096 bytes":"Fino a 4.096 byte","None: RTMPS adds TLS":"Nessuna: RTMPS aggiunge TLS","TCP, then RTMP’s own":"TCP, poi quello di RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"Lo streamer clicca su Avvia diretta. OBS si collega al server di ingest sulla porta TCP 1935, poi RTMP fa il suo handshake: versione 3 e 1.536 byte casuali in ogni verso, che ciascun lato rimanda indietro. Dimostra che entrambi i capi parlano RTMP; non cifra nulla.","Each side":"Ciascun lato","Sends 3,073 bytes":"Invia 3.073 byte","version 3":"versione 3","1,536 random bytes":"1.536 byte casuali","version 3, its own bytes":"versione 3, i suoi byte","and C1 sent back":"e C1 rimandato","S1 sent back":"S1 rimandato",Connect:"Connessione","To the server’s live app":"All’app live del server","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS porta la dimensione dei chunk a 4.096 byte e invia connect per l’app chiamata live, in AMF0, un formato binario compatto nato con Flash. Il server fissa la propria finestra, banda e dimensione dei chunk, e risponde _result: NetConnection.Connect.Success.",App:"App",Encoding:"Codifica","chunk size 4,096":"chunk da 4.096","window, bandwidth, chunks":"finestra, banda, chunk","Make a Stream":"Creare uno stream","createStream returns stream 1":"createStream restituisce lo stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Ogni messaggio indica uno stream di messaggi; lo 0 è la connessione stessa. OBS rilascia e annuncia la sua chiave di stream, poi chiede con createStream uno stream su cui inviare, tutti e tre i comandi in un pacchetto. Il server risponde con lo stream ID 1.","3 in one packet":"3 in un pacchetto",Gets:"Ottiene","Stream ID 1":"Stream ID 1","stream ID 1":"stream ID 1",Publish:"Pubblicazione","The stream key goes live":"La chiave di stream va in onda","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish indica la chiave di stream, il segreto che dice di chi è il canale. RTMP non cifra nulla, quindi la chiave passa in chiaro; le piattaforme preferiscono RTMPS, la stessa cosa su TLS. Il server controlla la chiave e risponde NetStream.Publish.Start.","The stream key":"La chiave di stream","None (RTMPS adds TLS)":"Nessuna (RTMPS aggiunge TLS)","on stream 1":"sullo stream 1","stream key, live":"chiave di stream, live","Video and Sound":"Video e suono","Metadata, settings, then frames":"Metadati, impostazioni, poi fotogrammi","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS descrive la diretta: 1920×1080 a 30 fotogrammi al secondo, video H.264, audio AAC. Invia le impostazioni dei decoder, poi un fotogramma chiave di circa 30 KB tagliato in chunk da 4.096 byte. I fotogrammi seguono senza sosta, sulla stessa connessione TCP.","AAC, 48 kHz stereo":"AAC, 48 kHz stereo","30 KB in 8 chunks":"30 KB in 8 chunk",METADATA:"METADATI","H.264 + AAC settings":"impostazioni H.264 e AAC","KEY FRAME":"FOTOGRAMMA CHIAVE","8 chunks":"8 chunk","Stop Streaming":"Fine della diretta","FCUnpublish and deleteStream":"FCUnpublish e deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Quando lo streamer clicca su Interrompi diretta, OBS invia FCUnpublish e deleteStream per lo stream 1. Il server risponde NetStream.Unpublish.Success e chiude la trasmissione per gli spettatori. Poi OBS chiude la connessione TCP.","C0: version":"C0: versione","RTMP version 3, the only one in use.":"RTMP versione 3, l’unica in uso.",Time:"Tempo","A timestamp; zero is allowed.":"Un timestamp; zero è ammesso.",Zero:"Zero","Random data":"Dati casuali","Random bytes the server must send back.":"Byte casuali che il server deve rimandare.","S0: version":"S0: versione","Random bytes the client must send back.":"Byte casuali che il client deve rimandare.","1,536 bytes: C1 back":"1.536 byte: C1 rimandato","The timestamp from the block it echoes.":"Il timestamp del blocco che rimanda.","Time read":"Tempo letto","C1’s random bytes, sent back unchanged.":"I byte casuali di C1, rimandati invariati.","1,536 bytes: S1 back":"1.536 byte: S1 rimandato","S1’s random bytes, sent back unchanged.":"I byte casuali di S1, rimandati invariati.","RTMP · 2 messages":"RTMP · 2 messaggi","First message":"Primo messaggio","Chunk header":"Intestazione del chunk","type 0, chunk stream 2":"tipo 0, chunk stream 2","A full header follows: this chunk starts a message.":"Segue un’intestazione completa: questo chunk inizia un messaggio.","Message stream":"Stream dei messaggi","Stream 0: the connection itself. (This number alone is little-endian.)":"Stream 0: la connessione stessa. (Solo questo numero è little-endian.)","Chunk size":"Dimensione del chunk","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"D’ora in poi questo lato taglia i messaggi in chunk fino a questa dimensione (128 finché non dice altro).","Second message":"Secondo messaggio","type 0, chunk stream 3":"tipo 0, chunk stream 3","Matches a reply to its request.":"Abbina una risposta alla sua richiesta.","Command object":"Oggetto del comando","object, 5 properties":"oggetto, 5 proprietà","Which app on the server, and the address OBS was given.":"Quale app sul server, e l’indirizzo dato a OBS.","End of object":"Fine dell’oggetto","RTMP · 4 messages":"RTMP · 4 messaggi","The other side should hear back after every this many bytes it sends.":"L’altro lato deve ricevere un riscontro dopo ogni tot di byte che invia.","Bandwidth, limit":"Banda, limite","5,000,000 bytes, dynamic":"5.000.000 byte, dinamico","How much the sender may have unacknowledged at once.":"Quanto il mittente può avere senza conferma alla volta.","Third message":"Terzo messaggio","Fourth message":"Quarto messaggio",Properties:"Proprietà","object, 2 properties":"oggetto, 2 proprietà",Information:"Informazioni","object, 4 properties":"oggetto, 4 proprietà","RTMP · 3 messages":"RTMP · 3 messaggi","Nothing: AMF0 null.":"Niente: null di AMF0.","Stream key":"Chiave di stream","Which channel this is. It works like a password, and here it travels unencrypted.":"Quale canale è. Funziona come una password, e qui viaggia senza cifratura.","Stream ID":"Stream ID","The new stream: video and audio will go on it.":"Il nuovo stream: video e audio passeranno da lì.","type 0, chunk stream 4":"tipo 0, chunk stream 4","Stream 1, the one createStream made.":"Stream 1, quello creato da createStream.","Publishing type":"Tipo di pubblicazione","Live: not recorded by this request.":"Live: questa richiesta non registra.","type 0, chunk stream 5":"tipo 0, chunk stream 5","object, 3 properties":"oggetto, 3 proprietà",Handler:"Gestore",Event:"Evento",Metadata:"Metadati","array of 14":"array di 14","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"ID dei codec come nei file video Flash: 7 è H.264, 10 è AAC.","type 0, chunk stream 6":"tipo 0, chunk stream 6","Frame, codec":"Fotogramma, codec","0x17 (key frame, H.264)":"0x17 (fotogramma chiave, H.264)","AVC packet type":"Tipo di pacchetto AVC","0 (decoder settings)":"0 (impostazioni del decoder)","The sequence header: the settings a decoder needs before the first frame.":"L’intestazione di sequenza: le impostazioni che servono al decoder prima del primo fotogramma.","Composition time":"Tempo di composizione","The H.264 profile, level and parameter sets.":"Profilo, livello e set di parametri H.264.","AAC; the other bits are fixed for AAC.":"AAC; gli altri bit sono fissi per AAC.","AAC packet type":"Tipo di pacchetto AAC","Sample rate and channels, for the decoder.":"Frequenza di campionamento e canali, per il decoder.","1 (video)":"1 (video)","Compressed picture data.":"Dati d’immagine compressi.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"Il fotogramma chiave: un’immagine intera. Ogni 4.096 byte, un’intestazione di chunk da 1 byte lo prosegue."},d={strings:{...l,...n,...r},patterns:[[/^([\d,]+) bytes$/,"$1 byte"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 byte: report.pdf, byte $2"],[/^(.+) h later$/,"$1 h dopo"],[/^(.+) min later$/,"$1 min dopo"],[/^(.+) s later$/,"$1 s dopo"],[/^(\S+) \(relative\)$/,"$1 (relativo)"],[/^(\d+) \(ephemeral\)$/,"$1 (effimera)"],[/^(\d+) TCP segments$/,"$1 segmenti TCP"],[/^(\d+) segments$/,"$1 segmenti"],[/^(.*), (\d+) segments$/,"$1, $2 segmenti"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,"TLS 1.3 · $1 record · byte $2 di $3"],[/^TLS 1\.3 · (\d+) records?$/,"TLS 1.3 · $1 record"],[/^Ethernet padding · (\d+) bytes$/,"Riempimento Ethernet · $1 byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 byte a zero, fino al minimo di 300 byte"],[/^(\d+) zero bytes$/,"$1 byte a zero"],[/^(\d+) random bytes$/,"$1 byte casuali"],[/^Seen as it leaves (.+)$/,"Visto all’uscita da $1"],[/^Option (\d+)$/,"Opzione $1"],[/^value (\d+), echo (\d+)$/,"valore $1, eco $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 byte, più $1 di opzioni."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows parte da $1. Qui è impostato a $2 di proposito."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(i,e,a)=>a==="1"?`Partito da ${e}; il router lungo il percorso ha tolto 1.`:`Partito da ${e}; ognuno dei ${a} router lungo il percorso ha tolto 1.`],[/^all (\d+) bytes of it$/,"tutti i suoi $1 byte"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Il pacchetto che l’ha causato, come l’ha ricevuto il dispositivo che segnala (TTL $1), così il mittente capisce di quale pacchetto si tratta."],[/^Port (\d+), TLS from the start$/,"Porta $1, TLS fin dall’inizio"],[/^(\d+), TLS from the start$/,"$1, TLS fin dall’inizio"],[/^type 79, (\d+) bytes$/,"tipo 79, $1 byte"],[/^(\d+) of (\d+) bytes$/,"$1 di $2 byte"],[/^(\d+) more bytes$/,"altri $1 byte"],[/^offset (\d+), (\d+) bytes$/,"offset $1, $2 byte"],[/^offset 0, (\d+) bytes \(all of it\)$/,"offset 0, $1 byte (tutto)"],[/^record, (\d+) bytes$/,"record, $1 byte"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · messaggio $1 di 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(i,e,a,t)=>{const o=t==="request"?"richiesta":"risposta";return e?`${e}${o} ${a}`:`${o[0].toUpperCase()}${o.slice(1)} ${a}`}],[/^(\d+) registers$/,"$1 registri"],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, voce"],[/^"(.*)" \(([\d,]+) bytes\)$/,'"$1" ($2 byte)'],[/^(masked|not masked), (\d+) bytes?$/,(i,e,a)=>`${e==="masked"?"mascherato":"non mascherato"}, ${a} byte`],[/^(\d+) \(disguised\)$/,"$1 (nascosto)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$1 ($2), $3 byte"],[/^0 \(none\), (\d+) bytes$/,"0 (nessuno), $1 byte"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), tipo $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (registro $2)"],[/^yes, AS (\d+)$/,"sì, AS $1"],[/^id 2, (\d+) bytes$/,"id 2, $1 byte"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, come concordato nell’SDP)"]],post:s};export{d as default};
